{
  "name": "X-Search Pro",
  "description": "High-performance local transaction search tool for Excel, CSV, and TXT files. Operates 100% in-browser with zero data uploads.",
  "requestFramePermissions": []
}

export interface SearchResult {
  id: string;
  fileName: string;
  filePath: string;
  sheetName?: string;
  rowNumber: number;
  matchedValue: string;
  rowData: Record<string, any>;
  preview: string;
}

export interface IndexingProgress {
  totalFiles: number;
  processedFiles: number;
  currentFileName: string;
  isComplete: boolean;
}

export interface IndexingStats {
  totalRows: number;
  totalFiles: number;
  timeTakenMs: number;
}

export enum FileType {
  EXCEL = 'xlsx',
  CSV = 'csv',
  TXT = 'txt'
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

/**
 * Note: Since we are in a single-response environment, 
 * this file content will be converted to a string and loaded as a Blob in App.tsx.
 */
import { FileType } from './types';

// We rely on standard browser APIs and globally loaded scripts in the worker context
// The worker will be initialized with XLSX and PapaParse if possible, 
// or we will use standard parsing logic.

export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  let index = [];
  let fileRegistry = [];

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'INDEX_FILES':
        await indexFiles(payload);
        break;
      case 'SEARCH':
        const results = searchIndex(payload);
        self.postMessage({ action: 'SEARCH_RESULTS', payload: results });
        break;
      case 'CLEAR_INDEX':
        index = [];
        fileRegistry = [];
        break;
    }
  };

  async function indexFiles(files) {
    let totalRows = 0;
    const startTime = Date.now();

    for (let i = 0; i < files.length; i++) {
      const fileObj = files[i];
      const { name, path, blob, type } = fileObj;

      self.postMessage({ 
        action: 'PROGRESS', 
        payload: { 
          currentFileName: name, 
          processedFiles: i + 1, 
          totalFiles: files.length,
          isComplete: false
        } 
      });

      try {
        const rows = await parseFile(blob, type, name, path);
        index.push(...rows);
        totalRows += rows.length;
      } catch (err) {
        console.error('Error parsing ' + name + ':', err);
      }
    }

    const endTime = Date.now();
    self.postMessage({ 
      action: 'INDEXING_COMPLETE', 
      payload: { 
        totalRows, 
        totalFiles: files.length, 
        timeTakenMs: endTime - startTime 
      } 
    });
  }

  async function parseFile(blob, type, name, path) {
    const results = [];

    if (type === 'xlsx' || type === 'xls') {
      const buffer = await blob.arrayBuffer();
      const workbook = XLSX.read(buffer, { type: 'array' });

      workbook.SheetNames.forEach(sheetName => {
        const sheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });

        jsonData.forEach((row, idx) => {
          const rowString = Object.values(row).join(' ').toLowerCase();
          results.push({
            id: Math.random().toString(36).substr(2, 9),
            fileName: name,
            filePath: path,
            sheetName: sheetName,
            rowNumber: idx + 2, // Header is 1
            rowData: row,
            searchString: rowString
          });
        });
      });
    } else if (type === 'csv') {
      const text = await blob.text();
      const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });

      parsed.data.forEach((row, idx) => {
        const rowString = Object.values(row).join(' ').toLowerCase();
        results.push({
          id: Math.random().toString(36).substr(2, 9),
          fileName: name,
          filePath: path,
          rowNumber: idx + 2,
          rowData: row,
          searchString: rowString
        });
      });
    } else if (type === 'txt') {
      const text = await blob.text();
      const lines = text.split(/\\r?\\n/);

      lines.forEach((line, idx) => {
        if (!line.trim()) return;
        results.push({
          id: Math.random().toString(36).substr(2, 9),
          fileName: name,
          filePath: path,
          rowNumber: idx + 1,
          rowData: { content: line },
          searchString: line.toLowerCase()
        });
      });
    }

    return results;
  }

  function searchIndex({ query, exactMatch }) {
    if (!query) return [];
    const lowerQuery = query.toLowerCase();

    return index
      .filter(item => {
        if (exactMatch) {
          return Object.values(item.rowData).some(val => 
            String(val).toLowerCase() === lowerQuery
          );
        }
        return item.searchString.includes(lowerQuery);
      })
      .slice(0, 500) // Performance cap: only return top 500 results
      .map(item => ({
        ...item,
        matchedValue: query // Simplified for speed
      }));
  }
`;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  ArrowRight,
  ChevronRight,
  Filter,
  Download,
  X,
  Zap
} from 'lucide-react';
import { SearchResult, IndexingProgress, IndexingStats } from './types';
import { workerScript } from './worker';

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isIndexing, setIsIndexing] = useState(false);
  const [progress, setProgress] = useState<IndexingProgress | null>(null);
  const [stats, setStats] = useState<IndexingStats | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const workerRef = useRef<Worker | null>(null);

  useEffect(() => {
    // Create worker from blob to stay within single file constraint environment
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const worker = new Worker(URL.createObjectURL(blob));

    worker.onmessage = (e) => {
      const { action, payload } = e.data;

      switch (action) {
        case 'PROGRESS':
          setProgress(payload);
          break;
        case 'INDEXING_COMPLETE':
          setStats(payload);
          setIsIndexing(false);
          setProgress(prev => prev ? { ...prev, isComplete: true } : null);
          break;
        case 'SEARCH_RESULTS':
          setResults(payload);
          setIsSearching(false);
          break;
      }
    };

    workerRef.current = worker;

    return () => {
      worker.terminate();
    };
  }, []);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setError(null);
    setIsIndexing(true);
    setResults([]);
    setStats(null);
    setProgress({
      totalFiles: files.length,
      processedFiles: 0,
      currentFileName: '',
      isComplete: false
    });

    const fileList = [];
    const supportedExtensions = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      if (supportedExtensions.includes(extension)) {
        fileList.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file // Passing the File object directly
        });
      }
    }

    if (fileList.length === 0) {
      setError("No supported transaction files (.xlsx, .csv, .txt) found in the selected folder.");
      setIsIndexing(false);
      return;
    }

    workerRef.current?.postMessage({
      action: 'INDEX_FILES',
      payload: fileList
    });
  };

  const handleSearch = useCallback((searchTerm: string) => {
    setQuery(searchTerm);
    if (searchTerm.length < 2) {
      setResults([]);
      return;
    }
    setIsSearching(true);
    workerRef.current?.postMessage({
      action: 'SEARCH',
      payload: { query: searchTerm, exactMatch }
    });
  }, [exactMatch]);

  const exportResults = () => {
    if (results.length === 0) return;
    const headers = ["File", "Sheet", "Row", "Content"];
    const csvContent = [
      headers.join(","),
      ...results.map(r => [
        `"${r.fileName}"`,
        `"${r.sheetName || 'N/A'}"`,
        r.rowNumber,
        `"${Object.values(r.rowData).join(' ').replace(/"/g, '""')}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `search_results_${new Date().getTime()}.csv`);
    link.click();
  };

  return (
    <div className="flex flex-col h-full bg-gray-900 overflow-hidden">
      {/* Header */}
      <header className="px-6 py-4 bg-gray-800 border-b border-gray-700 flex justify-between items-center shrink-0">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-lg">
            <Zap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-white">X-Search Pro</h1>
            <p className="text-xs text-gray-400 font-medium">Ultra-Fast Local Transaction Indexer</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-green-500/10 border border-green-500/20 rounded-full">
            <ShieldCheck className="w-4 h-4 text-green-400" />
            <span className="text-xs font-semibold text-green-400">100% Local Privacy</span>
          </div>

          <label className="flex items-center gap-2 cursor-pointer bg-blue-600 hover:bg-blue-700 transition-colors px-4 py-2 rounded-lg font-semibold text-sm shadow-lg shadow-blue-900/20">
            <FolderOpen className="w-4 h-4" />
            Select Folder
            <input 
              type="file" 
              className="hidden" 
              webkitdirectory="" 
              directory="" 
              multiple 
              onChange={handleFolderSelect}
            />
          </label>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-h-0 overflow-hidden">

        {/* Search Bar Wrapper */}
        <div className="p-6 bg-gray-900 border-b border-gray-800 shrink-0">
          <div className="max-w-4xl mx-auto space-y-4">
            <div className="relative group">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
              <input 
                type="text"
                placeholder={stats ? `Search across ${stats.totalRows.toLocaleString()} rows...` : "Select a folder to start searching..."}
                className="w-full bg-gray-800 border border-gray-700 rounded-xl py-3.5 pl-12 pr-4 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                disabled={!stats}
                value={query}
                onChange={(e) => handleSearch(e.target.value)}
              />
              {isSearching && (
                <div className="absolute right-4 top-1/2 -translate-y-1/2">
                  <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                </div>
              )}
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <label className="flex items-center gap-2 cursor-pointer select-none">
                  <div className={`w-10 h-5 rounded-full relative transition-colors ${exactMatch ? 'bg-blue-600' : 'bg-gray-700'}`}>
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={exactMatch} 
                      onChange={() => setExactMatch(!exactMatch)} 
                    />
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  <span className="text-xs font-medium text-gray-300">Exact Match</span>
                </label>

                {stats && (
                  <div className="flex items-center gap-4 text-xs font-medium text-gray-400">
                    <div className="flex items-center gap-1.5">
                      <Database className="w-3.5 h-3.5 text-gray-500" />
                      {stats.totalFiles} Files
                    </div>
                    <div className="flex items-center gap-1.5">
                      <FileText className="w-3.5 h-3.5 text-gray-500" />
                      {stats.totalRows.toLocaleString()} Records
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Clock className="w-3.5 h-3.5 text-gray-500" />
                      Index build: {stats.timeTakenMs}ms
                    </div>
                  </div>
                )}
              </div>

              {results.length > 0 && (
                <button 
                  onClick={exportResults}
                  className="flex items-center gap-2 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 border border-gray-700 rounded-lg text-xs font-semibold text-gray-300 transition-colors"
                >
                  <Download className="w-3.5 h-3.5" />
                  Export {results.length} Results
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Dynamic Display Area */}
        <div className="flex-1 overflow-auto bg-gray-900">
          {!stats && !isIndexing && !error && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 space-y-6">
              <div className="relative">
                <div className="absolute -inset-4 bg-blue-600/20 rounded-full blur-2xl animate-pulse"></div>
                <FolderOpen className="w-20 h-20 text-gray-700 relative z-10" />
              </div>
              <div className="max-w-md space-y-2">
                <h3 className="text-xl font-bold text-white">Ready to index local files</h3>
                <p className="text-gray-400">Select a folder containing Excel, CSV, or Text transaction reports to begin high-speed local searching.</p>
              </div>
              <div className="grid grid-cols-2 gap-4 w-full max-w-lg mt-8">
                <div className="p-4 bg-gray-800/50 border border-gray-700 rounded-xl space-y-1">
                  <div className="font-bold text-blue-400">Privacy First</div>
                  <div className="text-xs text-gray-500">Your data never leaves this machine. Zero uploads.</div>
                </div>
                <div className="p-4 bg-gray-800/50 border border-gray-700 rounded-xl space-y-1">
                  <div className="font-bold text-blue-400">Instant Search</div>
                  <div className="text-xs text-gray-500">Search thousands of files in milliseconds.</div>
                </div>
              </div>
            </div>
          )}

          {isIndexing && progress && (
            <div className="h-full flex flex-col items-center justify-center p-8">
              <div className="w-full max-w-md space-y-6">
                <div className="flex justify-between items-end">
                  <div className="space-y-1">
                    <h3 className="text-lg font-bold text-white">Indexing Content...</h3>
                    <p className="text-sm text-gray-400 truncate max-w-[300px]">
                      Parsing {progress.currentFileName || 'files...'}
                    </p>
                  </div>
                  <div className="text-right">
                    <span className="text-2xl font-black text-blue-500">
                      {Math.round((progress.processedFiles / progress.totalFiles) * 100)}%
                    </span>
                  </div>
                </div>

                <div className="h-3 w-full bg-gray-800 rounded-full overflow-hidden border border-gray-700">
                  <div 
                    className="h-full bg-blue-600 transition-all duration-300 ease-out shadow-[0_0_15px_rgba(37,99,235,0.5)]"
                    style={{ width: `${(progress.processedFiles / progress.totalFiles) * 100}%` }}
                  ></div>
                </div>

                <div className="flex justify-between text-xs font-medium text-gray-500 uppercase tracking-wider">
                  <span>Processed {progress.processedFiles} / {progress.totalFiles} Files</span>
                  <span className="animate-pulse">Optimizing Index...</span>
                </div>
              </div>
            </div>
          )}

          {error && (
            <div className="h-full flex flex-col items-center justify-center p-8 text-center space-y-4">
              <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center border border-red-500/20">
                <X className="w-8 h-8 text-red-500" />
              </div>
              <div className="space-y-2">
                <h3 className="text-lg font-bold text-white">Error Occurred</h3>
                <p className="text-gray-400 max-w-sm">{error}</p>
              </div>
              <button 
                onClick={() => setError(null)}
                className="px-6 py-2 bg-gray-800 border border-gray-700 rounded-lg text-sm font-semibold text-white hover:bg-gray-700 transition-colors"
              >
                Go Back
              </button>
            </div>
          )}

          {stats && !isIndexing && (
            <div className="p-6">
              {results.length > 0 ? (
                <div className="space-y-4 max-w-6xl mx-auto">
                  <div className="flex items-center justify-between text-xs font-semibold text-gray-500 uppercase tracking-widest px-2">
                    <span>Search Results ({results.length})</span>
                    <span>Top 500 matches shown</span>
                  </div>

                  <div className="overflow-hidden border border-gray-800 rounded-xl bg-gray-800/30">
                    <table className="w-full text-left border-collapse">
                      <thead>
                        <tr className="bg-gray-800/80 text-gray-400 text-[11px] uppercase tracking-wider border-b border-gray-700">
                          <th className="px-4 py-3 font-semibold">Source File</th>
                          <th className="px-4 py-3 font-semibold">Location</th>
                          <th className="px-4 py-3 font-semibold">Transaction Data Preview</th>
                          <th className="px-4 py-3 font-semibold text-right">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-800">
                        {results.map((result) => (
                          <tr key={result.id} className="hover:bg-blue-600/5 transition-colors group">
                            <td className="px-4 py-4">
                              <div className="flex flex-col">
                                <span className="text-sm font-bold text-gray-200 truncate max-w-[200px]">{result.fileName}</span>
                                <span className="text-[10px] text-gray-500 font-medium truncate max-w-[200px]">{result.filePath}</span>
                              </div>
                            </td>
                            <td className="px-4 py-4">
                              <div className="flex flex-col gap-1">
                                {result.sheetName && (
                                  <span className="inline-flex items-center gap-1 text-[10px] bg-gray-700 text-gray-300 px-1.5 py-0.5 rounded uppercase font-bold">
                                    <Database className="w-2.5 h-2.5" />
                                    {result.sheetName}
                                  </span>
                                )}
                                <span className="text-[10px] text-gray-400 font-bold uppercase">Row {result.rowNumber}</span>
                              </div>
                            </td>
                            <td className="px-4 py-4">
                              <div className="text-sm text-gray-300 font-mono bg-black/20 p-2 rounded border border-gray-700/50 line-clamp-2">
                                {Object.entries(result.rowData).map(([key, value]) => (
                                  <span key={key} className="mr-3">
                                    <span className="text-blue-400 text-[10px] font-bold uppercase mr-1">{key}:</span>
                                    <span className={String(value).toLowerCase().includes(query.toLowerCase()) ? 'bg-blue-500/30 text-white rounded px-0.5' : ''}>
                                      {String(value)}
                                    </span>
                                  </span>
                                ))}
                              </div>
                            </td>
                            <td className="px-4 py-4 text-right">
                              <button className="p-2 text-gray-500 hover:text-blue-400 transition-colors opacity-0 group-hover:opacity-100">
                                <ChevronRight className="w-5 h-5" />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ) : query.length > 1 ? (
                <div className="h-full flex flex-col items-center justify-center pt-20 text-center space-y-4 opacity-60">
                  <div className="w-16 h-16 bg-gray-800 rounded-full flex items-center justify-center border border-gray-700">
                    <Search className="w-8 h-8 text-gray-600" />
                  </div>
                  <div className="space-y-1">
                    <h3 className="text-lg font-bold text-white">No matches found</h3>
                    <p className="text-sm text-gray-500">Try adjusting your search term or toggle Exact Match.</p>
                  </div>
                </div>
              ) : null}
            </div>
          )}
        </div>
      </main>

      {/* Footer Info */}
      <footer className="px-6 py-2 bg-gray-800 border-t border-gray-700 flex justify-between items-center shrink-0">
        <div className="flex gap-4 text-[10px] font-bold text-gray-500 uppercase tracking-tighter">
          <span className="flex items-center gap-1"><Filter className="w-3 h-3" /> Filters: Off</span>
          <span className="flex items-center gap-1"><Zap className="w-3 h-3" /> Mode: Performance</span>
        </div>
        <div className="text-[10px] text-gray-500">
          Powered by React Worker & FileSystem API
        </div>
      </footer>
    </div>
  );
};

export default App;

/**
 * Note: This file content is converted to a string and loaded as a Blob in App.tsx.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  let index = [];

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'INDEX_FILES':
        await indexFiles(payload);
        break;
      case 'SEARCH':
        const results = searchIndex(payload);
        self.postMessage({ action: 'SEARCH_RESULTS', payload: results });
        break;
      case 'CLEAR_INDEX':
        index = [];
        self.postMessage({ action: 'INDEX_CLEARED' });
        break;
    }
  };

  async function indexFiles(files) {
    let totalRows = 0;
    const startTime = Date.now();
    index = []; // Clear previous index on new folder select

    for (let i = 0; i < files.length; i++) {
      const fileObj = files[i];
      const { name, path, blob, type } = fileObj;

      self.postMessage({ 
        action: 'PROGRESS', 
        payload: { 
          currentFileName: name, 
          processedFiles: i + 1, 
          totalFiles: files.length,
          isComplete: false
        } 
      });

      try {
        const rows = await parseFile(blob, type, name, path);
        index.push(...rows);
        totalRows += rows.length;
      } catch (err) {
        console.error('Error parsing ' + name + ':', err);
      }
    }

    const endTime = Date.now();
    self.postMessage({ 
      action: 'INDEXING_COMPLETE', 
      payload: { 
        totalRows, 
        totalFiles: files.length, 
        timeTakenMs: endTime - startTime 
      } 
    });
  }

  async function parseFile(blob, type, name, path) {
    const results = [];

    try {
      if (type === 'xlsx' || type === 'xls') {
        const buffer = await blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'array', cellDates: true });

        workbook.SheetNames.forEach(sheetName => {
          const sheet = workbook.Sheets[sheetName];
          const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });

          jsonData.forEach((row, idx) => {
            const rowValues = Object.values(row).map(v => String(v));
            results.push({
              id: \`\${name}-\${sheetName}-\${idx}\`,
              fileName: name,
              filePath: path,
              sheetName: sheetName,
              rowNumber: idx + 2,
              rowData: row,
              searchString: rowValues.join(' ').toLowerCase(),
              timestamp: Date.now() // Placeholder for date sorting if needed
            });
          });
        });
      } else if (type === 'csv') {
        const text = await blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });

        parsed.data.forEach((row, idx) => {
          const rowValues = Object.values(row).map(v => String(v));
          results.push({
            id: \`\${name}-\${idx}\`,
            fileName: name,
            filePath: path,
            rowNumber: idx + 2,
            rowData: row,
            searchString: rowValues.join(' ').toLowerCase()
          });
        });
      } else if (type === 'txt') {
        const text = await blob.text();
        const lines = text.split(/\\r?\\n/);

        lines.forEach((line, idx) => {
          if (!line.trim()) return;
          results.push({
            id: \`\${name}-\${idx}\`,
            fileName: name,
            filePath: path,
            rowNumber: idx + 1,
            rowData: { content: line },
            searchString: line.toLowerCase()
          });
        });
      }
    } catch (e) {
      console.warn('Parser failed for ' + name, e);
    }

    return results;
  }

  function searchIndex({ query, exactMatch, filters, sortBy }) {
    if (!query && !filters.fileType) return [];

    let filtered = index;
    const lowerQuery = query.toLowerCase();

    // 1. Text Search
    if (lowerQuery) {
      filtered = filtered.filter(item => {
        if (exactMatch) {
          // Check if any specific cell value matches exactly
          return Object.values(item.rowData).some(val => 
            String(val).toLowerCase() === lowerQuery
          );
        }
        // Partial match
        return item.searchString.includes(lowerQuery);
      });
    }

    // 2. File Type Filters
    if (filters && filters.fileType && filters.fileType !== 'all') {
      filtered = filtered.filter(item => {
        const ext = item.fileName.split('.').pop().toLowerCase();
        return ext === filters.fileType;
      });
    }

    // 3. Sorting
    if (sortBy) {
      filtered.sort((a, b) => {
        if (sortBy === 'fileName') return a.fileName.localeCompare(b.fileName);
        if (sortBy === 'rowNumber') return a.rowNumber - b.rowNumber;
        return 0;
      });
    }

    // Performance cap: only return top 1000 results to avoid UI lag
    return filtered.slice(0, 1000);
  }
`;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
