import { workerScript } from './worker';

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isIndexing, setIsIndexing] = useState(false);
  const [progress, setProgress] = useState<IndexingProgress | null>(null);
  const [stats, setStats] = useState<IndexingStats | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [fileTypeFilter, setFileTypeFilter] = useState('all');
  const [sortBy, setSortBy] = useState('fileName');
  const [error, setError] = useState<string | null>(null);

  const workerRef = useRef<Worker | null>(null);
  const searchTimeout = useRef<number | null>(null);

  useEffect(() => {
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const worker = new Worker(URL.createObjectURL(blob));

    worker.onmessage = (e) => {
      const { action, payload } = e.data;

      switch (action) {
        case 'PROGRESS':
          setProgress(payload);
          break;
        case 'INDEXING_COMPLETE':
          setStats(payload);
          setIsIndexing(false);
          setProgress(prev => prev ? { ...prev, isComplete: true } : null);
          break;
        case 'SEARCH_RESULTS':
          setResults(payload);
          setIsSearching(false);
          break;
        case 'INDEX_CLEARED':
          setStats(null);
          setResults([]);
          setQuery('');
          break;
      }
    };

    workerRef.current = worker;
    return () => worker.terminate();
  }, []);

  const triggerSearch = useCallback((q: string, exact: boolean, filter: string, sort: string) => {
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);

    if (!q && filter === 'all') {
      setResults([]);
      setIsSearching(false);
      return;
    }

    setIsSearching(true);
    searchTimeout.current = window.setTimeout(() => {
      workerRef.current?.postMessage({
        action: 'SEARCH',
        payload: { 
          query: q, 
          exactMatch: exact, 
          filters: { fileType: filter },
          sortBy: sort
        }
      });
    }, 200);
  }, []);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setError(null);
    setIsIndexing(true);
    setResults([]);
    setStats(null);
    setProgress({
      totalFiles: files.length,
      processedFiles: 0,
      currentFileName: '',
      isComplete: false
    });

    const fileList = [];
    const supportedExtensions = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      if (supportedExtensions.includes(extension)) {
        fileList.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file 
        });
      }
    }

    if (fileList.length === 0) {
      setError("No supported transaction files found. Please ensure the folder contains .xlsx, .csv, or .txt files.");
      setIsIndexing(false);
      return;
    }

    workerRef.current?.postMessage({
      action: 'INDEX_FILES',
      payload: fileList
    });
  };

  const clearIndex = () => {
    if (confirm("Are you sure you want to clear the search index and free up memory?")) {
      workerRef.current?.postMessage({ action: 'CLEAR_INDEX' });
    }
  };

  const exportResults = () => {
    if (results.length === 0) return;
    const headers = ["File", "Sheet", "Row", "Data"];
    const csvContent = [
      headers.join(","),
      ...results.map(r => [
        `"${r.fileName}"`,
        `"${r.sheetName || 'N/A'}"`,
        r.rowNumber,
        `"${Object.values(r.rowData).join(' | ').replace(/"/g, '""')}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_export_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  };

  const onQueryChange = (val: string) => {
    setQuery(val);
    triggerSearch(val, exactMatch, fileTypeFilter, sortBy);
  };

