          </label>
        </div>
      </header>

      {/* Main Container */}
      <main className="flex-1 flex flex-col min-h-0 relative">

        {/* Search & Filter Strip */}
        <div className="px-6 py-4 bg-gray-900/50 backdrop-blur-md border-b border-gray-800/50 shrink-0">
          <div className="max-w-6xl mx-auto space-y-4">
            <div className="flex gap-4">
              <div className="relative flex-1 group">
                <Search className={`absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={stats ? `Search ${stats.totalRows.toLocaleString()} transaction records...` : "Select a folder to begin indexing..."}
