  const [progress, setProgress] = useState<IndexingProgress | null>(null);
  const [stats, setStats] = useState<IndexingStats | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [fileTypeFilter, setFileTypeFilter] = useState('all');
  const [sortBy, setSortBy] = useState('fileName');
  const [error, setError] = useState<string | null>(null);
  const [statusMessage, setStatusMessage] = useState<string>('');

  const workerRef = useRef<Worker | null>(null);
  const searchTimeout = useRef<number | null>(null);

  const initWorker = useCallback(() => {
    if (workerRef.current) {
      workerRef.current.terminate();
    }
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const worker = new Worker(URL.createObjectURL(blob));

    worker.onmessage = (e) => {
      const { action, payload } = e.data;

      switch (action) {
        case 'PROGRESS':
          setProgress(payload);
          break;
        case 'INDEXING_COMPLETE':
          setStats(payload);
          setIsIndexing(false);
          setStatusMessage('Ready');
          setProgress(prev => prev ? { ...prev, isComplete: true } : null);
          break;
        case 'SEARCH_RESULTS':
          setResults(payload);
          setIsSearching(false);
          break;
        case 'INDEX_CLEARED':
          setStats(null);
          setResults([]);
          setQuery('');
          setStatusMessage('Index Cleared');
          break;
      }
    };

    workerRef.current = worker;
  }, []);

  useEffect(() => {
    initWorker();
    return () => {
      workerRef.current?.terminate();
    };
  }, [initWorker]);

  const triggerSearch = useCallback((q: string, exact: boolean, filter: string, sort: string) => {
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);

    if (!q && filter === 'all') {
      setResults([]);
      setIsSearching(false);
      return;
    }

    setIsSearching(true);
    searchTimeout.current = window.setTimeout(() => {
      workerRef.current?.postMessage({
        action: 'SEARCH',
        payload: { 
          query: q, 
          exactMatch: exact, 
          filters: { fileType: filter },
          sortBy: sort
        }
      });
    }, 200);
  }, []);

  const handleCancelIndexing = useCallback(() => {
    if (isIndexing) {
      initWorker(); // Re-initialize terminates the old worker immediately
      setIsIndexing(false);
      setProgress(null);
      setStats(null);
      setResults([]);
      setQuery('');
      setError(null);
      setStatusMessage('Indexing Cancelled');
    }
  }, [isIndexing, initWorker]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    // Auto-cancel if already indexing
    if (isIndexing) {
      handleCancelIndexing();
    }

    setError(null);
    setIsIndexing(true);
    setResults([]);
    setStats(null);
    setStatusMessage('Scanning Folder...');
    setProgress({
      totalFiles: files.length,
      processedFiles: 0,
      currentFileName: '',
      isComplete: false
    });

    const fileList = [];
    const supportedExtensions = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      if (supportedExtensions.includes(extension)) {
        fileList.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file 
        });
      }
    }

    if (fileList.length === 0) {
      setError("No supported transaction files found (.xlsx, .csv, .txt).");
      setIsIndexing(false);
      return;
    }

    workerRef.current?.postMessage({
      action: 'INDEX_FILES',
      payload: fileList
    });
  };

  const clearIndex = () => {
    if (confirm("Are you sure you want to clear the search index and free up memory?")) {
      workerRef.current?.postMessage({ action: 'CLEAR_INDEX' });
    }
  };

  const exportResults = () => {
    if (results.length === 0) return;
    const headers = ["File", "Sheet", "Row", "Data"];
    const csvContent = [
      headers.join(","),
      ...results.map(r => [
        `"${r.fileName}"`,
        `"${r.sheetName || 'N/A'}"`,
        r.rowNumber,
        `"${Object.values(r.rowData).join(' | ').replace(/"/g, '""')}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_export_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  };

  const onQueryChange = (val: string) => {
    setQuery(val);
    triggerSearch(val, exactMatch, fileTypeFilter, sortBy);
  };

  const onFilterChange = (val: string) => {
    setFileTypeFilter(val);
    triggerSearch(query, exactMatch, val, sortBy);
  };

  const onSortChange = (val: string) => {
    setSortBy(val);
    triggerSearch(query, exactMatch, fileTypeFilter, val);
  };

  const onExactMatchToggle = () => {
    const next = !exactMatch;
    setExactMatch(next);
    triggerSearch(query, next, fileTypeFilter, sortBy);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden">
      {/* Header */}
      <header className="px-6 py-3 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-20 shadow-lg">
        <div className="flex items-center gap-3">
          <div className="bg-gradient-to-br from-blue-500 to-indigo-600 p-2 rounded-xl shadow-inner">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-lg font-black tracking-tight text-white flex items-center gap-2">
              X-SEARCH <span className="text-blue-500">PRO</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold tracking-widest uppercase">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              Isolated Local Engine
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {stats && !isIndexing && (
            <button 
              onClick={clearIndex}
              className="p-2 text-gray-500 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
              title="Clear Index"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          )}

          <label className="group flex items-center gap-2 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-4 py-2 rounded-xl font-bold text-xs shadow-lg shadow-blue-900/40">
            <FolderOpen className="w-4 h-4 group-hover:scale-110 transition-transform" />
            {isIndexing ? 'CHANGE FOLDER' : 'OPEN FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Main Container */}
      <main className="flex-1 flex flex-col min-h-0 relative">

        {/* Search & Filter Strip */}
        <div className="px-6 py-4 bg-gray-900/50 backdrop-blur-md border-b border-gray-800/50 shrink-0">
          <div className="max-w-6xl mx-auto space-y-4">
            <div className="flex gap-4">
              <div className="relative flex-1 group">
                <Search className={`absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={stats ? `Search ${stats.totalRows.toLocaleString()} transaction records...` : "Select a folder to begin indexing..."}
                  className="w-full bg-gray-800/50 border border-gray-700/50 rounded-xl py-3 pl-11 pr-4 text-sm text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500/50 transition-all disabled:opacity-40"
                  disabled={!stats || isIndexing}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                />
                {isSearching && (
                  <div className="absolute right-4 top-1/2 -translate-y-1/2">
                    <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2 shrink-0 bg-gray-800/40 border border-gray-700/50 rounded-xl px-2">
                <Filter className="w-3.5 h-3.5 text-gray-500 ml-2" />
                <select 
                  className="bg-transparent border-none text-xs font-bold text-gray-300 focus:ring-0 cursor-pointer py-2 pr-8"
                  value={fileTypeFilter}
                  onChange={(e) => onFilterChange(e.target.value)}
                  disabled={!stats || isIndexing}
                >
                  <option value="all">ALL FILES</option>
                  <option value="xlsx">EXCEL (.xlsx)</option>
                  <option value="csv">CSV (.csv)</option>
                  <option value="txt">TEXT (.txt)</option>
                </select>
              </div>

              <div className="flex items-center gap-2 shrink-0 bg-gray-800/40 border border-gray-700/50 rounded-xl px-2">
                <SortAsc className="w-3.5 h-3.5 text-gray-500 ml-2" />
                <select 
                  className="bg-transparent border-none text-xs font-bold text-gray-300 focus:ring-0 cursor-pointer py-2 pr-8"
                  value={sortBy}
                  onChange={(e) => onSortChange(e.target.value)}
                  disabled={!stats || isIndexing}
                >
                  <option value="fileName">SORT BY FILE</option>
                  <option value="rowNumber">SORT BY ROW</option>
                </select>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-5">
                <button 
                  onClick={onExactMatchToggle}
                  className={`flex items-center gap-2 text-[11px] font-bold transition-colors ${exactMatch ? 'text-blue-400' : 'text-gray-500 hover:text-gray-400'}`}
                  disabled={!stats || isIndexing}
                >
                  <div className={`w-8 h-4 rounded-full relative transition-colors ${exactMatch ? 'bg-blue-600' : 'bg-gray-700'}`}>
                    <div className={`absolute top-0.5 left-0.5 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-4' : ''}`} />
                  </div>
                  EXACT MATCH
                </button>

                {(stats || statusMessage) && (
                  <div className="h-4 w-px bg-gray-800" />
                )}

                {stats && !isIndexing && (
                  <div className="flex items-center gap-4 text-[11px] font-bold text-gray-600">
                    <span className="flex items-center gap-1.5"><Layers className="w-3 h-3" /> {stats.totalFiles} FILES</span>
                    <span className="flex items-center gap-1.5"><Database className="w-3 h-3" /> {stats.totalRows.toLocaleString()} RECORDS</span>
                    <span className="flex items-center gap-1.5 text-blue-500/60"><Clock className="w-3 h-3" /> {stats.timeTakenMs}MS INDEXED</span>
                  </div>
                )}

                {statusMessage && !stats && (
                  <div className="text-[11px] font-bold text-yellow-500 uppercase tracking-widest flex items-center gap-2">
                    {statusMessage === 'Indexing Cancelled' && <Ban className="w-3 h-3" />}
                    {statusMessage}
                  </div>
                )}
              </div>

              {results.length > 0 && !isIndexing && (
                <button 
                  onClick={exportResults}
                  className="flex items-center gap-2 px-3 py-1.5 bg-indigo-600/10 hover:bg-indigo-600/20 border border-indigo-500/30 rounded-lg text-[11px] font-black text-indigo-400 transition-all uppercase tracking-widest"
                >
                  <Download className="w-3.5 h-3.5" />
                  Export {results.length} CSV
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Dynamic Display Area */}
        <div className="flex-1 overflow-auto bg-gray-950 relative">

          {/* Initial State */}
          {!stats && !isIndexing && !error && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 space-y-8">
              <div className="relative group">
                <div className="absolute -inset-10 bg-blue-600/10 rounded-full blur-3xl group-hover:bg-blue-600/20 transition-all duration-700"></div>
                <div className="w-24 h-24 bg-gray-900 border border-gray-800 rounded-3xl flex items-center justify-center shadow-2xl relative z-10 rotate-3 group-hover:rotate-0 transition-transform">
                  <FolderOpen className="w-10 h-10 text-blue-500" />
                </div>
              </div>
              <div className="max-w-md text-center space-y-3 relative z-10">
                <h3 className="text-2xl font-black text-white">Local Transaction Intelligence</h3>
                <p className="text-gray-500 text-sm leading-relaxed">
                  Fast, offline, and secure. Index your local payment logs, settlement reports, and transaction CSVs without uploading a single byte.
                </p>
              </div>
              <div className="flex gap-3 text-[10px] font-bold text-gray-600 uppercase tracking-widest bg-gray-900/50 p-3 rounded-xl border border-gray-800">
                <span className="px-2 py-1 bg-gray-800 rounded">XLSX</span>
                <span className="px-2 py-1 bg-gray-800 rounded">CSV</span>
                <span className="px-2 py-1 bg-gray-800 rounded">TXT</span>
                <span className="px-2 py-1 bg-blue-500/10 text-blue-400 rounded">ZERO-LATENCY</span>
              </div>
            </div>
          )}

          {/* Indexing Progress */}
          {isIndexing && progress && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-950/80 backdrop-blur-sm z-50 p-8">
              <div className="w-full max-w-lg space-y-8 bg-gray-900 p-8 rounded-3xl border border-gray-800 shadow-2xl">
                <div className="flex justify-between items-end">
                  <div className="space-y-1">
                    <h3 className="text-xl font-black text-white flex items-center gap-2">
                      <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                      BUILDING INDEX
                    </h3>
                    <p className="text-xs text-gray-500 font-mono truncate max-w-[320px]">
                      Parsing: {progress.currentFileName || 'Scanning files...'}
                    </p>
                  </div>
                  <div className="text-right">
                    <span className="text-3xl font-black text-blue-500 tabular-nums">
                      {progress.totalFiles > 0 ? Math.round((progress.processedFiles / progress.totalFiles) * 100) : 0}%
                    </span>
                  </div>
                </div>

                <div className="h-4 w-full bg-gray-800 rounded-full overflow-hidden border-4 border-gray-800">
                  <div 
                    className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 transition-all duration-300 ease-out relative"
                    style={{ width: `${progress.totalFiles > 0 ? (progress.processedFiles / progress.totalFiles) * 100 : 0}%` }}
                  >
                    <div className="absolute inset-0 bg-[linear-gradient(45deg,rgba(255,255,255,0.2)_25%,transparent_25%,transparent_50%,rgba(255,255,255,0.2)_50%,rgba(255,255,255,0.2)_75%,transparent_75%,transparent)] bg-[length:20px_20px] animate-[progress-stripe_1s_linear_infinite]"></div>
                  </div>
                </div>

                <div className="flex justify-between items-center">
                  <div className="text-[10px] font-black text-gray-600 uppercase tracking-widest flex items-center gap-2">
                    <FileText className="w-3 h-3" />
                    {progress.processedFiles} OF {progress.totalFiles} OBJECTS
                  </div>
                  <button 
                    onClick={handleCancelIndexing}
                    className="flex items-center gap-2 px-3 py-1.5 bg-red-500/10 hover:bg-red-500/20 border border-red-500/30 rounded-lg text-[10px] font-black text-red-500 transition-all uppercase tracking-widest"
                  >
                    <Ban className="w-3 h-3" />
                    Cancel Indexing
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Results Listing */}
          {stats && !isIndexing && (
            <div className="p-6">
              {results.length > 0 ? (
                <div className="max-w-6xl mx-auto space-y-6">
                  <div className="flex items-center gap-4 text-[10px] font-black text-gray-500 tracking-widest uppercase">
                    <div className="h-px flex-1 bg-gray-800/50"></div>
                    DISPLAYING {results.length} MATCHING CLUSTERS
                    <div className="h-px flex-1 bg-gray-800/50"></div>
                  </div>

                  <div className="grid grid-cols-1 gap-3">
                    {results.map((result) => (
                      <div key={result.id} className="group bg-gray-900/40 hover:bg-gray-900 border border-gray-800 hover:border-blue-500/30 rounded-2xl p-4 transition-all duration-200">
                        <div className="flex flex-col md:flex-row gap-4">
                          <div className="w-full md:w-1/4 space-y-2">
                            <div className="flex items-center gap-2">
                              <div className="bg-gray-800 p-1.5 rounded-lg">
                                <FileText className="w-3.5 h-3.5 text-blue-400" />
                              </div>
                              <span className="text-xs font-bold text-gray-200 truncate" title={result.fileName}>
                                {result.fileName}
                              </span>
                            </div>
                            <div className="flex flex-wrap gap-2 pl-9">
                              {result.sheetName && (
                                <span className="text-[9px] font-black text-indigo-400 bg-indigo-400/10 px-1.5 py-0.5 rounded border border-indigo-400/20 uppercase">
                                  {result.sheetName}
                                </span>
                              )}
                              <span className="text-[9px] font-black text-gray-500 bg-gray-800 px-1.5 py-0.5 rounded border border-gray-700 uppercase">
                                ROW {result.rowNumber}
                              </span>
                            </div>
                          </div>

                          <div className="flex-1">
                            <div className="bg-gray-950/60 p-3 rounded-xl border border-gray-800/50 font-mono text-[13px] leading-relaxed group-hover:border-blue-500/20 transition-colors">
                              <div className="flex flex-wrap gap-x-6 gap-y-2">
                                {Object.entries(result.rowData).map(([key, value]) => {
                                  const strVal = String(value);
                                  const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                                  return (
                                    <div key={key} className="flex flex-col">
                                      <span className="text-[9px] text-gray-600 font-bold uppercase mb-0.5 tracking-tighter">{key}</span>
                                      <span className={`text-gray-300 break-all ${isMatch ? 'bg-blue-500/20 text-blue-300 rounded px-1 -mx-1 font-bold ring-1 ring-blue-500/30' : ''}`}>
                                        {strVal || <span className="text-gray-800 italic text-[10px]">null</span>}
                                      </span>
                                    </div>
                                  );
                                })}
                              </div>
                            </div>
                          </div>

                          <div className="shrink-0 flex items-center justify-end md:block">
                            <button className="p-2 text-gray-700 hover:text-blue-500 hover:bg-blue-500/10 rounded-xl transition-all opacity-0 group-hover:opacity-100 hidden md:flex">
                              <ChevronRight className="w-5 h-5" />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>

                  {results.length >= 1000 && (
                    <div className="flex items-center gap-3 bg-blue-500/5 p-4 rounded-2xl border border-blue-500/20 text-blue-400 text-xs font-bold justify-center uppercase tracking-widest">
                      <Info className="w-4 h-4" />
                      Showing first 1000 results. Refine your query for more precision.
                    </div>
                  )}
                </div>
              ) : query.length > 0 || fileTypeFilter !== 'all' ? (
                <div className="h-64 flex flex-col items-center justify-center text-center space-y-4 opacity-40">
                  <div className="w-16 h-16 bg-gray-900 border border-gray-800 rounded-full flex items-center justify-center">
                    <Search className="w-6 h-6 text-gray-600" />
                  </div>
                  <div className="space-y-1">
                    <h4 className="text-lg font-bold text-white uppercase tracking-tighter">Zero Correlation</h4>
                    <p className="text-xs text-gray-500 font-medium">No records matching your current filter set were found in memory.</p>
                  </div>
                </div>
              ) : (
                <div className="h-64 flex flex-col items-center justify-center text-center space-y-4 opacity-40">
                  <div className="w-16 h-16 bg-gray-900 border border-gray-800 rounded-full flex items-center justify-center">
                    <Zap className="w-6 h-6 text-gray-600" />
                  </div>
                  <div className="space-y-1">
                    <h4 className="text-lg font-bold text-white uppercase tracking-tighter">Enter Query</h4>
                    <p className="text-xs text-gray-500 font-medium">Index complete. Start typing above to search across all indexed transaction rows.</p>
                  </div>
                </div>
              )}
            </div>
          )}

          {error && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center space-y-6 bg-gray-950/90 z-50">
              <div className="w-16 h-16 bg-red-500/10 rounded-2xl flex items-center justify-center border border-red-500/30">
                <X className="w-8 h-8 text-red-500" />
              </div>
              <div className="space-y-2">
                <h3 className="text-xl font-black text-white uppercase tracking-tighter">Indexing Failed</h3>
                <p className="text-gray-500 text-sm max-w-sm font-medium">{error}</p>
              </div>
              <button 
                onClick={() => setError(null)}
                className="px-8 py-3 bg-gray-900 border border-gray-800 rounded-xl text-xs font-black text-white hover:bg-gray-800 transition-all uppercase tracking-widest"
              >
                DISMISS ERROR
              </button>
            </div>
          )}
        </div>
      </main>

      {/* Footer Info Strip */}
      <footer className="px-6 py-2 bg-gray-900 border-t border-gray-800 flex justify-between items-center shrink-0 z-20">
        <div className="flex gap-5 text-[9px] font-black text-gray-600 uppercase tracking-widest">
          <span className="flex items-center gap-1.5"><ShieldCheck className="w-3 h-3 text-green-500/50" /> PRIVACY: LOCAL-HOST</span>
          <span className="flex items-center gap-1.5"><Info className="w-3 h-3 text-blue-500/50" /> ENGINE: WEB-WORKER V1</span>
        </div>
        <div className="text-[9px] text-gray-700 font-bold uppercase">
          X-SEARCH PRO // SECURE TRANSACTION ANALYTICS
        </div>
      </footer>

      <style>{`
        @keyframes progress-stripe {
          from { background-position: 0 0; }
          to { background-position: 40px 0; }
        }
      `}</style>
    </div>
  );
};

export default App;

/**
 * X-Search Pro Background Worker
 * Handles heavy lifting: parsing large datasets and fuzzy searching.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  let index = [];
  const MAX_RESULTS = 1000;
  const FILE_SIZE_LIMIT = 100 * 1024 * 1024; // 100MB limit per file for safety

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'INDEX_FILES':
        await indexFiles(payload);
        break;
      case 'SEARCH':
        const results = searchIndex(payload);
        self.postMessage({ action: 'SEARCH_RESULTS', payload: results });
        break;
      case 'CLEAR_INDEX':
        index = [];
        self.postMessage({ action: 'INDEX_CLEARED' });
        break;
    }
  };

  async function indexFiles(files) {
    let totalRows = 0;
    const startTime = Date.now();
    index = []; 

    for (let i = 0; i < files.length; i++) {
      const { name, path, blob, type } = files[i];

      // File size safety check
      if (blob.size > FILE_SIZE_LIMIT) {
        console.warn(\`Skipping large file: \${name} (\${(blob.size / 1024 / 1024).toFixed(2)} MB)\`);
        continue;
      }

      self.postMessage({ 
        action: 'PROGRESS', 
        payload: { 
          currentFileName: name, 
          processedFiles: i + 1, 
          totalFiles: files.length,
          isComplete: false
        } 
      });

      try {
        const rows = await parseFile(blob, type, name, path);
        // Using spread on large arrays can cause stack overflow, using loop instead
        for (let j = 0; j < rows.length; j++) {
            index.push(rows[j]);
        }
        totalRows += rows.length;
      } catch (err) {
        console.error('Indexing error in ' + name + ':', err);
      }
    }

    const endTime = Date.now();
    self.postMessage({ 
      action: 'INDEXING_COMPLETE', 
      payload: { 
        totalRows, 
        totalFiles: files.length, 
        timeTakenMs: endTime - startTime 
      } 
    });
  }

  async function parseFile(blob, type, name, path) {
    const results = [];

    try {
      if (type === 'xlsx' || type === 'xls') {
        const buffer = await blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'array', cellDates: true, cellFormula: false, cellText: false });

        workbook.SheetNames.forEach(sheetName => {
          const sheet = workbook.Sheets[sheetName];
          const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });

          jsonData.forEach((row, idx) => {
            const rowValues = Object.values(row).filter(v => v !== null && v !== undefined && v !== "");
            if (rowValues.length === 0) return; // Skip empty rows

            results.push({
              id: \`\${name}-\${sheetName}-\${idx}\`,
              fileName: name,
              filePath: path,
              sheetName: sheetName,
              rowNumber: idx + 2,
              rowData: row,
              searchString: rowValues.join(' ').toLowerCase()
            });
          });
        });
      } else if (type === 'csv') {
        const text = await blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });

        parsed.data.forEach((row, idx) => {
          const rowValues = Object.values(row).filter(v => v !== "");
          if (rowValues.length === 0) return;

          results.push({
            id: \`\${name}-\${idx}\`,
            fileName: name,
            filePath: path,
            rowNumber: idx + 2,
            rowData: row,
            searchString: rowValues.join(' ').toLowerCase()
          });
        });
      } else if (type === 'txt') {
        const text = await blob.text();
        const lines = text.split(/\\r?\\n/);

        lines.forEach((line, idx) => {
          const trimmed = line.trim();
          if (!trimmed) return;
          results.push({
            id: \`\${name}-\${idx}\`,
            fileName: name,
            filePath: path,
            rowNumber: idx + 1,
            rowData: { content: trimmed },
            searchString: trimmed.toLowerCase()
          });
        });
      }
    } catch (e) {
      console.warn('Parser failed for ' + name, e);
    }

    return results;
  }

  function searchIndex({ query, exactMatch, filters, sortBy }) {
    if (!query && filters.fileType === 'all') return [];

    let filtered = index;
    const lowerQuery = query ? query.toLowerCase() : "";

    // 1. Text Search with optimized loop
    if (lowerQuery) {
      const matchResults = [];
      for (let i = 0; i < filtered.length; i++) {
        const item = filtered[i];
        let isMatch = false;

        if (exactMatch) {
          const vals = Object.values(item.rowData);
          for (let k = 0; k < vals.length; k++) {
            if (String(vals[k]).toLowerCase() === lowerQuery) {
              isMatch = true;
              break;
            }
          }
        } else {
          isMatch = item.searchString.includes(lowerQuery);
        }

        if (isMatch) {
            matchResults.push(item);
            if (matchResults.length >= MAX_RESULTS) break; // Early exit on search limit
        }
      }
      filtered = matchResults;
    }

    // 2. File Type Filters
    if (filters && filters.fileType && filters.fileType !== 'all') {
      filtered = filtered.filter(item => {
        const ext = item.fileName.split('.').pop().toLowerCase();
        return ext === filters.fileType;
      });
    }

    // 3. Sorting
    if (sortBy) {
      filtered.sort((a, b) => {
        if (sortBy === 'fileName') return a.fileName.localeCompare(b.fileName);
        if (sortBy === 'rowNumber') return a.rowNumber - b.rowNumber;
        return 0;
      });
    }

    return filtered.slice(0, MAX_RESULTS);
  }
`;

