  const [stats, setStats] = useState<IndexingStats | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [fileTypeFilter, setFileTypeFilter] = useState('all');
  const [sortBy, setSortBy] = useState('fileName');
  const [error, setError] = useState<string | null>(null);
  const [statusMessage, setStatusMessage] = useState<string>('');

  const workerRef = useRef<Worker | null>(null);
  const searchTimeout = useRef<number | null>(null);

  /**
   * Safe Worker Initialization
   * Terminates any existing worker to prevent zombies and race conditions.
   */
  const initWorker = useCallback(() => {
    if (workerRef.current) {
      console.debug("Terminating existing worker...");
      workerRef.current.terminate();
    }

    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const worker = new Worker(URL.createObjectURL(blob));

    worker.onmessage = (e) => {
      const { action, payload } = e.data;

      switch (action) {
        case 'PROGRESS':
          setProgress(payload);
          break;
        case 'INDEXING_COMPLETE':
          setStats(payload);
          setIsIndexing(false);
          setStatusMessage('Ready');
          setProgress(prev => prev ? { ...prev, isComplete: true } : null);
          break;
        case 'SEARCH_RESULTS':
          setResults(payload);
          setIsSearching(false);
          break;
        case 'INDEX_CLEARED':
          setStats(null);
          setResults([]);
          setQuery('');
          setStatusMessage('Index Cleared');
          break;
      }
    };

    worker.onerror = (err) => {
        console.error("Worker Error:", err);
        setError("Search engine encountered a critical error. Indexing aborted.");
        setIsIndexing(false);
    };

    workerRef.current = worker;
  }, []);

  useEffect(() => {
    initWorker();
    return () => {
      workerRef.current?.terminate();
    };
  }, [initWorker]);

  /**
   * Debounced Search Orchestrator
   */
  const triggerSearch = useCallback((q: string, exact: boolean, filter: string, sort: string) => {
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);

    if (!q && filter === 'all') {
      setResults([]);
      setIsSearching(false);
      return;
    }

    setIsSearching(true);
    searchTimeout.current = window.setTimeout(() => {
      workerRef.current?.postMessage({
        action: 'SEARCH',
        payload: { 
          query: q, 
          exactMatch: exact, 
          filters: { fileType: filter },
          sortBy: sort
        }
      });
    }, 150); // Aggressive 150ms debounce for ultra-fast feel
  }, []);

  /**
   * Manual Cancellation Handler
   * Resets the entire engine state.
   */
  const handleCancelIndexing = useCallback(() => {
    if (isIndexing) {
      initWorker(); // Re-initializing is the most reliable way to kill ongoing parsing
      setIsIndexing(false);
      setProgress(null);
      setStats(null);
      setResults([]);
      setQuery('');
      setError(null);
      setStatusMessage('Indexing Cancelled');
