/**
 * X-Search Pro Background Worker (Task-Based)
 * Optimized for memory efficiency and on-demand search tasks.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'PROCESS_FILE':
        await processFile(payload);
        break;
    }
  };

  async function processFile({ fileId, blob, type, name, path, query, exactMatch }) {
    try {
      const rows = await parseFile(blob, type, name, path);

      // If a query is provided, filter results immediately for "First Search" performance
      let filteredRows = rows;
      if (query) {
        const lowerQuery = query.toLowerCase();
        filteredRows = rows.filter(row => {
          if (exactMatch) {
            return Object.values(row.rowData).some(val => String(val).toLowerCase() === lowerQuery);
          }
          return row.searchString.includes(lowerQuery);
        });
      }

      self.postMessage({ 
        action: 'FILE_PROCESSED', 
        payload: { 
          fileId,
          allRows: rows, // Send back all rows to be cached in the main thread
          matches: filteredRows 
        } 
      });
    } catch (err) {
      self.postMessage({ 
        action: 'FILE_ERROR', 
        payload: { fileId, error: err.message } 
      });
    }
  }

  async function parseFile(blob, type, name, path) {
    const results = [];

    if (type === 'xlsx' || type === 'xls') {
      const buffer = await blob.arrayBuffer();
      // Use lightweight options to speed up parsing and reduce memory
      const workbook = XLSX.read(buffer, { 
        type: 'array', 
        cellDates: true, 
        cellFormula: false, 
        cellText: false,
        bookSheets: true // Only read what's necessary initially
      });

      workbook.SheetNames.forEach(sheetName => {
        const sheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });

        jsonData.forEach((row, idx) => {
          const rowValues = Object.values(row).filter(v => v !== null && v !== undefined && v !== "");
          if (rowValues.length === 0) return;

          results.push({
            id: `${name}-${sheetName}-${idx}`,
            fileName: name,
            filePath: path,
            sheetName: sheetName,
            rowNumber: idx + 2,
            rowData: row,
            searchString: rowValues.join(' ').toLowerCase()
          });
        });
      });
    } else if (type === 'csv') {
      const text = await blob.text();
      const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });

      parsed.data.forEach((row, idx) => {
        const rowValues = Object.values(row).filter(v => v !== "");
        if (rowValues.length === 0) return;

        results.push({
          id: `${name}-${idx}`,
          fileName: name,
          filePath: path,
          rowNumber: idx + 2,
          rowData: row,
          searchString: rowValues.join(' ').toLowerCase()
        });
      });
    } else if (type === 'txt') {
      const text = await blob.text();
      const lines = text.split(/\r?\n/);

      lines.forEach((line, idx) => {
        const trimmed = line.trim();
        if (!trimmed) return;
        results.push({
          id: `${name}-${idx}`,
          fileName: name,
          filePath: path,
          rowNumber: idx + 1,
          rowData: { content: trimmed },
          searchString: trimmed.toLowerCase()
        });
      });
    }

    return results;
  }
`;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  ChevronRight,
  Filter,
  Download,
  X,
  Zap,
  Trash2,
  Info,
  SortAsc,
  Layers,
  Ban,
  AlertTriangle,
  CheckCircle2
} from 'lucide-react';
import { SearchResult } from './types';
import { workerScript } from './worker';

// Constants for tuning performance and stability
const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const MAX_TOTAL_RESULTS = 1000;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [fileTypeFilter, setFileTypeFilter] = useState('all');
  const [sortBy, setSortBy] = useState('fileName');
  const [error, setError] = useState<string | null>(null);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });
  const [cacheStats, setCacheStats] = useState({ cachedFiles: 0, totalRows: 0 });

  // References for managing state and background processes
  const workers = useRef<Worker[]>([]);
  const fileCache = useRef<Map<string, SearchResult[]>>(new Map());
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);

  // Initialize Worker Pool
  const initWorkerPool = useCallback(() => {
    // Clean up existing workers
    workers.current.forEach(w => w.terminate());
    workers.current = [];

    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);

    for (let i = 0; i < MAX_WORKERS; i++) {
      const worker = new Worker(workerUrl);
      workers.current.push(worker);
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  // Handle folder selection (Metadata only scan)
  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles || rawFiles.length === 0) return;

    setError(null);
    setResults([]);
    fileCache.current.clear();
    setCacheStats({ cachedFiles: 0, totalRows: 0 });

    const fileList: FileMetadata[] = [];
    const supportedExtensions = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      if (supportedExtensions.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }

    if (fileList.length === 0) {
      setError("No transaction-compatible files discovered (.xlsx, .csv, .txt).");
      setFiles([]);
      return;
    }

    setFiles(fileList);
  };

  // On-Demand Search Orchestrator
  const performSearch = useCallback(async (searchTerm: string, exact: boolean, filter: string) => {
    if (!searchTerm && filter === 'all') {
      setResults([]);
      setIsSearching(false);
      return;
    }

    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setResults([]);

    const filteredFileList = files.filter(f => filter === 'all' || f.type === filter);
    setSearchProgress({ scanned: 0, total: filteredFileList.length });

    const localResults: SearchResult[] = [];
    const pendingFiles: FileMetadata[] = [];

    // Step 1: Search the cache (Fastest)
    for (const file of filteredFileList) {
      if (fileCache.current.has(file.id)) {
        const rows = fileCache.current.get(file.id)!;
        const lowerQuery = searchTerm.toLowerCase();
        const matches = rows.filter(row => {
          if (exact) {
            return Object.values(row.rowData).some(val => String(val).toLowerCase() === lowerQuery);
          }
          return row.searchString.includes(lowerQuery);
        });
        localResults.push(...matches);
        setSearchProgress(prev => ({ ...prev, scanned: prev.scanned + 1 }));
      } else {
        pendingFiles.push(file);
      }
    }

    if (localResults.length > 0) {
      setResults([...localResults].slice(0, MAX_TOTAL_RESULTS));
    }

    if (pendingFiles.length === 0) {
      setIsSearching(false);
      return;
    }

    // Step 2: Search remaining files using Worker Pool (Parallel)
    let pendingCount = pendingFiles.length;
    let currentFileIndex = 0;
    const activeMatches: SearchResult[] = [...localResults];

    const processNext = (worker: Worker) => {
      if (currentFileIndex >= pendingFiles.length || searchId !== activeSearchId.current) {
        if (searchId === activeSearchId.current) {
            // Check if all workers are done
            if (--pendingCount <= 0) setIsSearching(false);
        }
        return;
      }

      const file = pendingFiles[currentFileIndex++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;

        const { action, payload } = e.data;
        if (action === 'FILE_PROCESSED') {
          const { fileId, allRows, matches } = payload;

          // Cache the full file content for future zero-latency searches
          fileCache.current.set(fileId, allRows);
          setCacheStats(prev => ({ 
            cachedFiles: prev.cachedFiles + 1, 
            totalRows: prev.totalRows + allRows.length 
          }));

          activeMatches.push(...matches);
          if (activeMatches.length <= MAX_TOTAL_RESULTS) {
            setResults([...activeMatches]);
          }

          setSearchProgress(prev => ({ ...prev, scanned: prev.scanned + 1 }));
          processNext(worker);
        } else if (action === 'FILE_ERROR') {
          console.error(`Error processing ${file.name}:`, payload.error);
          setSearchProgress(prev => ({ ...prev, scanned: prev.scanned + 1 }));
          processNext(worker);
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    // Start all workers
    workers.current.forEach(w => processNext(w));

  }, [files]);

  // Debounce search input
  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, fileTypeFilter);
    }, 300);
  };

  const onExactMatchToggle = () => {
    const next = !exactMatch;
    setExactMatch(next);
    performSearch(query, next, fileTypeFilter);
  };

  const onFilterChange = (val: string) => {
    setFileTypeFilter(val);
    performSearch(query, exactMatch, val);
  };

  const clearMemory = () => {
    fileCache.current.clear();
    setCacheStats({ cachedFiles: 0, totalRows: 0 });
    setResults([]);
    setQuery('');
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden select-none">
      {/* Dynamic Header */}
      <header className="px-6 py-4 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-30 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2.5 rounded-2xl shadow-xl shadow-blue-900/20">
            <Zap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight text-white flex items-center gap-2">
              X-SEARCH <span className="text-blue-500">ULTRA</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold tracking-[0.2em] uppercase">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              On-Demand Performance Mode
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {cacheStats.cachedFiles > 0 && (
            <div className="hidden md:flex flex-col items-end mr-4">
              <div className="text-[9px] font-black text-blue-500/80 uppercase tracking-widest flex items-center gap-1.5">
                <Database className="w-3 h-3" /> Cached Intelligence
              </div>
              <div className="text-[10px] font-bold text-gray-400">
                {cacheStats.cachedFiles} Files // {cacheStats.totalRows.toLocaleString()} Rows
              </div>
            </div>
          )}

          <button 
            onClick={clearMemory}
            className="p-2.5 text-gray-600 hover:text-red-400 hover:bg-red-400/10 rounded-xl transition-all border border-transparent hover:border-red-400/20"
            title="Purge RAM Cache"
          >
            <Trash2 className="w-4.5 h-4.5" />
          </button>

          <label className="group relative flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 active:scale-95 transition-all px-6 py-3 rounded-2xl font-black text-xs shadow-xl shadow-blue-900/40 border border-blue-400/20">
            <FolderOpen className="w-4 h-4 group-hover:scale-110 transition-transform" />
            {files.length > 0 ? 'SWITCH DIRECTORY' : 'ACTIVATE DIRECTORY'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Main Workspace */}
      <main className="flex-1 flex flex-col min-h-0 relative">

        <div className="px-6 py-6 bg-gray-900/80 backdrop-blur-2xl border-b border-gray-800/50 shrink-0 z-20">
          <div className="max-w-6xl mx-auto space-y-6">
            <div className="flex gap-4 items-center">
              <div className="relative flex-1 group">
                <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Instant Search ${files.length} transaction sources...` : "Select a local folder to activate searching..."}
                  className="w-full bg-gray-800/60 border border-gray-700/50 rounded-2xl py-4 pl-14 pr-6 text-base text-white placeholder-gray-600 focus:outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500/40 transition-all disabled:opacity-40 shadow-inner"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest hidden sm:inline">
                      Scanning {Math.round((searchProgress.scanned / searchProgress.total) * 100)}%
                    </span>
                    <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="hidden lg:flex items-center gap-2 shrink-0 bg-gray-800/80 border border-gray-700/50 rounded-2xl p-1.5 px-4 shadow-sm">
                <Filter className="w-4 h-4 text-gray-500" />
                <select 
                  className="bg-transparent border-none text-[11px] font-black text-gray-400 focus:ring-0 cursor-pointer py-2 pr-8 uppercase tracking-widest"
                  value={fileTypeFilter}
                  onChange={(e) => onFilterChange(e.target.value)}
                  disabled={files.length === 0}
                >
                  <option value="all">EVERYTHING</option>
                  <option value="xlsx">EXCEL (.xlsx)</option>
                  <option value="csv">CSV (.csv)</option>
                  <option value="txt">TEXT (.txt)</option>
