                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all duration-300 ${exactMatch ? 'bg-blue-600 shadow-[0_0_15px_rgba(37,99,235,0.3)]' : 'bg-gray-800 border border-gray-700'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MATCH
                </button>

                <div className="h-4 w-px bg-gray-800" />

                {files.length > 0 && (
                  <div className="flex items-center gap-6 text-[10px] font-black text-gray-500 tracking-wider">
                    <span className="flex items-center gap-2"><Layers className="w-4 h-4 text-gray-600" /> {files.length} SOURCE OBJECTS</span>
                    <span className="flex items-center gap-2 text-blue-500/70"><CheckCircle2 className="w-4 h-4" /> ENGINE READY</span>
                  </div>
                )}
              </div>

              {results.length > 0 && (
                <div className="text-[10px] font-black text-blue-500/80 tracking-[0.2em] bg-blue-500/5 px-4 py-2 rounded-full border border-blue-500/10">
                  {results.length >= MAX_TOTAL_RESULTS ? `TOP ${MAX_TOTAL_RESULTS}+ MATCHES` : `${results.length} MATCHES CORRELATED`}
                </div>
