                <div className="absolute -inset-20 bg-blue-600/5 rounded-full blur-[100px] animate-pulse"></div>
                <div className="w-40 h-40 bg-gray-900/50 border border-gray-800/40 rounded-[50px] flex items-center justify-center shadow-2xl relative z-10">
                  <FolderOpen className="w-16 h-16 text-blue-500/30" />
