                <div className="pt-4 flex justify-center gap-4">
                    <div className="px-4 py-2 bg-gray-900 border border-gray-800 rounded-xl text-[10px] font-black text-gray-600 tracking-widest uppercase">Worker Pool x{MAX_WORKERS}</div>
