/**
 * X-Search Pro Background Worker (Task-Based)
 * Optimized for memory efficiency and on-demand search tasks.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'PROCESS_FILE':
        await processFile(payload);
        break;
    }
  };

  async function processFile({ fileId, blob, type, name, path, query, exactMatch }) {
    try {
      const rows = await parseFile(blob, type, name, path);

      // If a query is provided, filter results immediately for "First Search" performance
      let filteredRows = rows;
      if (query) {
        const lowerQuery = query.toLowerCase();
        filteredRows = rows.filter(row => {
          if (exactMatch) {
            return Object.values(row.rowData).some(val => String(val).toLowerCase() === lowerQuery);
          }
          return row.searchString.includes(lowerQuery);
        });
      }

      self.postMessage({ 
        action: 'FILE_PROCESSED', 
        payload: { 
          fileId,
          allRows: rows, // Send back all rows to be cached in the main thread
          matches: filteredRows 
        } 
      });
    } catch (err) {
      self.postMessage({ 
        action: 'FILE_ERROR', 
        payload: { fileId, error: err.message } 
      });
    }
  }

  async function parseFile(blob, type, name, path) {
    const results = [];

    if (type === 'xlsx' || type === 'xls') {
      const buffer = await blob.arrayBuffer();
      // Use lightweight options to speed up parsing and reduce memory
      const workbook = XLSX.read(buffer, { 
        type: 'array', 
        cellDates: true, 
        cellFormula: false, 
        cellText: false,
        bookSheets: true // Only read what's necessary initially
      });

      workbook.SheetNames.forEach(sheetName => {
        const sheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });

        jsonData.forEach((row, idx) => {
          const rowValues = Object.values(row).filter(v => v !== null && v !== undefined && v !== "");
          if (rowValues.length === 0) return;

          results.push({
            // Fix: Escape template literal interpolation to prevent main-thread evaluation
            id: \`\${name}-\${sheetName}-\${idx}\`,
            fileName: name,
            filePath: path,
            sheetName: sheetName,
            rowNumber: idx + 2,
            rowData: row,
            searchString: rowValues.join(' ').toLowerCase()
          });
        });
      });
    } else if (type === 'csv') {
      const text = await blob.text();
      const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });

      parsed.data.forEach((row, idx) => {
        const rowValues = Object.values(row).filter(v => v !== "");
        if (rowValues.length === 0) return;

        results.push({
          // Fix: Escape template literal interpolation to prevent main-thread evaluation
          id: \`\${name}-\${idx}\`,
          fileName: name,
          filePath: path,
          rowNumber: idx + 2,
          rowData: row,
          searchString: rowValues.join(' ').toLowerCase()
        });
      });
    } else if (type === 'txt') {
      const text = await blob.text();
      // Fix: Escape backslashes in regex for proper string representation within template literal
      const lines = text.split(/\\r?\\n/);

      lines.forEach((line, idx) => {
        const trimmed = line.trim();
        if (!trimmed) return;
        results.push({
          // Fix: Escape template literal interpolation to prevent main-thread evaluation
          id: \`\${name}-\${idx}\`,
          fileName: name,
          filePath: path,
          rowNumber: idx + 1,
          rowData: { content: trimmed },
          searchString: trimmed.toLowerCase()
        });
      });
    }

    return results;
  }
`;

