/**
 * X-Search Pro Background Worker (Memory-Optimized)
 * Optimized for low memory footprint and chunked result delivery.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  const CHUNK_SIZE = 100; // Deliver matches in chunks to prevent UI freeze

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'PROCESS_FILE':
        await processFile(payload);
        break;
    }
  };

  async function processFile({ fileId, blob, type, name, path, query, exactMatch }) {
    try {
      const lowerQuery = query ? query.toLowerCase() : "";
      let matches = [];
      let totalRowsInFile = 0;

      const onRowProcessed = (row) => {
        totalRowsInFile++;
        const rowValues = Object.values(row).filter(v => v !== null && v !== undefined && v !== "");
        if (rowValues.length === 0) return;

        const searchString = rowValues.join(' ').toLowerCase();
        let isMatch = false;

        if (lowerQuery) {
          if (exactMatch) {
            isMatch = Object.values(row).some(val => String(val).toLowerCase() === lowerQuery);
          } else {
            isMatch = searchString.includes(lowerQuery);
          }
        } else {
          isMatch = true; // If no query, everything is a match (for list view)
        }

        if (isMatch) {
          matches.push({
            id: \`\${fileId}-\${totalRowsInFile}\`,
            fileName: name,
            filePath: path,
            rowNumber: totalRowsInFile + 1,
            rowData: row,
            searchString
          });

          // Chunk delivery
          if (matches.length >= CHUNK_SIZE) {
            self.postMessage({ 
              action: 'MATCH_CHUNK', 
              payload: { fileId, matches } 
            });
            matches = [];
          }
        }
      };

      if (type === 'xlsx' || type === 'xls') {
        const buffer = await blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { 
          type: 'array', 
          cellDates: true, 
          cellFormula: false, 
          cellText: false,
          cellNF: false,
          cellHTML: false
        });

        workbook.SheetNames.forEach(sheetName => {
          const sheet = workbook.Sheets[sheetName];
          if (!sheet) return;
          const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });
          jsonData.forEach(row => onRowProcessed({ ...row, _sheet: sheetName }));
        });
      } else if (type === 'csv') {
        const text = await blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });
        parsed.data.forEach(onRowProcessed);
      } else if (type === 'txt') {
        const text = await blob.text();
        const lines = text.split(/\\r?\\n/);
        lines.forEach((line, idx) => onRowProcessed({ content: line.trim() }));
      }

      // Send remaining matches
      if (matches.length > 0) {
        self.postMessage({ 
          action: 'MATCH_CHUNK', 
          payload: { fileId, matches } 
        });
      }

      self.postMessage({ 
        action: 'FILE_COMPLETE', 
        payload: { fileId, totalRows: totalRowsInFile } 
      });

    } catch (err) {
      self.postMessage({ 
        action: 'FILE_ERROR', 
        payload: { fileId, error: err.message } 
      });
    }
  }
`;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  ChevronRight,
  Filter,
  Download,
  X,
  Zap,
  Trash2,
  Info,
  SortAsc,
  Layers,
  Ban,
  AlertTriangle,
  CheckCircle2,
  History,
  ChevronDown,
  ArrowUpDown,
  FileSpreadsheet
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const INITIAL_VISIBLE_COUNT = 50;
const LOAD_MORE_STEP = 50;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [visibleCount, setVisibleCount] = useState(INITIAL_VISIBLE_COUNT);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'csv', 'txt']);
  const [sortBy, setSortBy] = useState<string>('relevance');
  const [error, setError] = useState<string | null>(null);
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);

  // Load recent searches from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  const saveSearch = (q: string, exact: boolean) => {
    if (!q.trim()) return;
    const newSearch: RecentSearch = { query: q, timestamp: Date.now(), exactMatch: exact };
    const updated = [newSearch, ...recentSearches.filter(s => s.query !== q)].slice(0, 10);
    setRecentSearches(updated);
    localStorage.setItem('xsearch_history', JSON.stringify(updated));
  };

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      const worker = new Worker(workerUrl);
      workers.current.push(worker);
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles || rawFiles.length === 0) return;

    setError(null);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);

    const fileList: FileMetadata[] = [];
    const supportedExtensions = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supportedExtensions.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }

    if (fileList.length === 0) {
      setError("No transaction-compatible files discovered.");
      setFiles([]);
      return;
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[]) => {
    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);

    const filteredFiles = files.filter(f => types.includes(f.type === 'xls' ? 'xlsx' : f.type));
    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm && types.length === files.map(f => f.type).length) {
      setIsSearching(false);
      return;
    }

    if (searchTerm) saveSearch(searchTerm, exact);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) {
        return;
      }

      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;

        if (action === 'MATCH_CHUNK') {
          setAllResults(prev => [...prev, ...payload.matches]);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) setIsSearching(false);
          startWorker(worker);
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    workers.current.forEach(w => startWorker(w));
  }, [files]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) 
      ? selectedFileTypes.filter(t => t !== type)
      : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next);
  };

  const sortedResults = useMemo(() => {
    const sorted = [...allResults];
    if (sortBy === 'fileName') sorted.sort((a, b) => a.fileName.localeCompare(b.fileName));
    else if (sortBy === 'rowNumber') sorted.sort((a, b) => a.rowNumber - b.rowNumber);
    return sorted;
  }, [allResults, sortBy]);

  const visibleResults = useMemo(() => sortedResults.slice(0, visibleCount), [sortedResults, visibleCount]);

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    const headers = Array.from(new Set(allResults.flatMap(r => Object.keys(r.rowData))));
    const csvRows = [
      headers.join(','),
      ...allResults.map(r => headers.map(h => `"${String(r.rowData[h] || '').replace(/"/g, '""')}"`).join(','))
    ];
    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `xsearch_export_${Date.now()}.csv`;
    a.click();
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans">
      {/* Dynamic Header */}
      <header className="px-6 py-3 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-30 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2 rounded-xl">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-lg font-black tracking-tight text-white flex items-center gap-2">
              X-SEARCH <span className="text-blue-500">PRO</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-widest">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              Main Thread Memory Guard Active
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-black text-xs shadow-lg shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'CHANGE FOLDER' : 'OPEN FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Main Area */}
      <main className="flex-1 flex flex-col min-h-0 relative">
        <div className="px-6 py-6 bg-gray-900/80 backdrop-blur-xl border-b border-gray-800/50 shrink-0 z-20">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-4 items-center">
              <div className="relative flex-1 group">
                <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Search across ${files.length} sources...` : "Select folder to start..."}
                  className="w-full bg-gray-800/60 border border-gray-700/50 rounded-2xl py-4 pl-14 pr-6 text-base text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-all disabled:opacity-40 shadow-inner"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">
                      {Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%
                    </span>
                    <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2 shrink-0 bg-gray-800/80 border border-gray-700/50 rounded-2xl p-1 px-4">
                <Filter className="w-4 h-4 text-gray-500" />
                {['xlsx', 'csv', 'txt'].map(type => (
                  <button
                    key={type}
                    onClick={() => toggleFileType(type)}
                    className={`px-3 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-blue-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={onExactMatchToggle}
                  className={`flex items-center gap-3 text-[10px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600 shadow-[0_0_15px_rgba(37,99,235,0.3)]' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MODE
                </button>
                <div className="h-4 w-px bg-gray-800" />
                <div className="flex items-center gap-4 text-[10px] font-black text-gray-500">
                  <span className="flex items-center gap-2"><ArrowUpDown className="w-3.5 h-3.5" /> SORT BY:</span>
                  <select 
                    value={sortBy} 
                    onChange={(e) => setSortBy(e.target.value)}
                    className="bg-transparent border-none text-blue-400 focus:ring-0 cursor-pointer uppercase"
                  >
                    <option value="relevance">RELEVANCE</option>
                    <option value="fileName">FILE NAME</option>
                    <option value="rowNumber">ROW ORDER</option>
                  </select>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4">
                  <div className="text-[10px] font-black text-blue-500/80 tracking-widest bg-blue-500/5 px-4 py-2 rounded-xl border border-blue-500/10">
                    {allResults.length.toLocaleString()} HITS
                  </div>
                  <button 
                    onClick={exportToCSV}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-900/40"
                  >
                    <Download className="w-3.5 h-3.5" />
                    EXPORT ALL
                  </button>
                </div>
              )}
            </div>

            {/* Recent Searches */}
            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
                <History className="w-3.5 h-3.5 text-gray-600" />
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => { setQuery(s.query); performSearch(s.query, s.exactMatch, selectedFileTypes); }}
                      className="text-[9px] font-bold text-gray-500 hover:text-blue-400 bg-gray-800/40 px-3 py-1.5 rounded-lg border border-gray-800 transition-all uppercase tracking-tighter"
                    >
                      {s.query}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-auto bg-gray-950 p-6">
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30 select-none">
              <FolderOpen className="w-20 h-20 mb-6" />
              <h3 className="text-xl font-black uppercase tracking-[0.4em]">Initialize Archive</h3>
              <p className="text-xs font-bold mt-2">Select a folder to activate zero-latency local searching.</p>
            </div>
          ) : visibleResults.length > 0 ? (
            <div className="max-w-7xl mx-auto space-y-4">
              {visibleResults.map((res) => (
                <div 
                  key={res.id} 
                  className={`group bg-gray-900/40 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/50 rounded-[32px] shadow-2xl bg-gray-900/90' : 'border-gray-800/50 rounded-2xl hover:border-blue-500/30'}`}
                >
                  <div 
                    className="p-5 flex items-center justify-between cursor-pointer"
                    onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                  >
                    <div className="flex items-center gap-5 min-w-0">
                      <div className={`p-2 rounded-xl transition-colors ${expandedId === res.id ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-500 group-hover:text-blue-500'}`}>
                        <FileText className="w-5 h-5" />
                      </div>
                      <div className="min-w-0">
                        <div className="text-xs font-black text-gray-200 uppercase tracking-tight flex items-center gap-3">
                          {res.fileName}
                          {res.rowData._sheet && (
                            <span className="text-[9px] px-2 py-0.5 bg-indigo-500/10 text-indigo-400 rounded border border-indigo-500/20">{res.rowData._sheet}</span>
                          )}
                        </div>
                        <div className="text-[10px] font-bold text-gray-600 mt-1 uppercase tracking-widest flex items-center gap-3">
                          LINE {res.rowNumber} <span className="w-1 h-1 rounded-full bg-gray-800"></span> 
                          <span className="truncate max-w-lg text-gray-400">
                            {Object.values(res.rowData).filter(v => typeof v !== 'object').slice(0, 4).join(' | ')}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className={`p-2 transition-transform duration-300 ${expandedId === res.id ? 'rotate-180 text-blue-500' : 'text-gray-700'}`}>
                      <ChevronDown className="w-5 h-5" />
                    </div>
                  </div>

                  {expandedId === res.id && (
                    <div className="px-5 pb-5 animate-in slide-in-from-top-2">
                      <div className="bg-gray-950/50 rounded-2xl border border-gray-800/50 p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {Object.entries(res.rowData).map(([key, value]) => {
                          if (key.startsWith('_')) return null;
                          const strVal = String(value);
                          const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                          return (
                            <div key={key} className="space-y-1.5 group/item">
                              <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest group-hover/item:text-blue-500/60 transition-colors">{key}</span>
                              <div className={`text-sm font-mono break-all leading-relaxed p-2 rounded-lg border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-white font-bold' : 'bg-gray-900/50 border-gray-800 text-gray-400'}`}>
                                {strVal || <span className="opacity-20 italic">EMPTY</span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {visibleCount < allResults.length && (
                <button 
                  onClick={() => setVisibleCount(prev => prev + LOAD_MORE_STEP)}
                  className="w-full py-6 mt-4 bg-gray-900/20 border border-dashed border-gray-800 rounded-2xl text-[11px] font-black text-gray-500 hover:text-white hover:border-blue-500/50 transition-all uppercase tracking-[0.4em]"
                >
                  LOAD MORE ({allResults.length - visibleCount} REMAINING)
                </button>
              )}
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-20">
              <AlertTriangle className="w-16 h-16 mb-6" />
              <h4 className="text-xl font-black uppercase tracking-widest">No Matches</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter">Query returned zero correlated objects.</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-20">
              <Zap className="w-16 h-16 mb-6" />
              <h4 className="text-xl font-black uppercase tracking-widest">Engine Ready</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter">Enter a transaction query to start scanning.</p>
            </div>
          )}
        </div>
      </main>

      {/* Footer Info */}
      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-widest shrink-0">
        <div className="flex gap-8 items-center">
          <span className="flex items-center gap-2"><Clock className="w-4 h-4 text-blue-500/40" /> POOL SIZE: {MAX_WORKERS} THREADS</span>
          <div className="h-4 w-px bg-gray-800" />
          <span className="flex items-center gap-2 text-indigo-500/40"><Database className="w-4 h-4" /> LOCAL_ENGINE_ACTIVE</span>
        </div>
        <div className="text-gray-700 italic">
          X-SEARCH PRO // V3.2.0 // ZERO-MEMORY LEAK ARCHITECTURE
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  ChevronRight,
  Filter,
  Download,
  X,
  Zap,
  Trash2,
  Info,
  SortAsc,
  Layers,
  Ban,
  AlertTriangle,
  CheckCircle2,
  History,
  ChevronDown,
  ArrowUpDown,
  FileSpreadsheet
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const INITIAL_VISIBLE_COUNT = 50;
const LOAD_MORE_STEP = 50;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [visibleCount, setVisibleCount] = useState(INITIAL_VISIBLE_COUNT);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'csv', 'txt']);
  const [sortBy, setSortBy] = useState<string>('relevance');
  const [error, setError] = useState<string | null>(null);
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);

  // Load recent searches from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  const saveSearch = (q: string, exact: boolean) => {
    if (!q.trim()) return;
    const newSearch: RecentSearch = { query: q, timestamp: Date.now(), exactMatch: exact };
    const updated = [newSearch, ...recentSearches.filter(s => s.query !== q)].slice(0, 10);
    setRecentSearches(updated);
    localStorage.setItem('xsearch_history', JSON.stringify(updated));
  };

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      const worker = new Worker(workerUrl);
      workers.current.push(worker);
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles || rawFiles.length === 0) return;

    setError(null);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);

    const fileList: FileMetadata[] = [];
    const supportedExtensions = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supportedExtensions.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }

    if (fileList.length === 0) {
      setError("No transaction-compatible files discovered.");
      setFiles([]);
      return;
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[]) => {
    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);

    const filteredFiles = files.filter(f => types.includes(f.type === 'xls' ? 'xlsx' : f.type));
    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm && types.length === files.map(f => f.type).length) {
      setIsSearching(false);
      return;
    }

    if (searchTerm) saveSearch(searchTerm, exact);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) {
        return;
      }

      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;

        if (action === 'MATCH_CHUNK') {
          setAllResults(prev => [...prev, ...payload.matches]);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) setIsSearching(false);
          startWorker(worker);
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    workers.current.forEach(w => startWorker(w));
  }, [files]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) 
      ? selectedFileTypes.filter(t => t !== type)
      : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next);
  };

  // Fix: Missing onExactMatchToggle implementation
  const onExactMatchToggle = useCallback(() => {
    const next = !exactMatch;
    setExactMatch(next);
    performSearch(query, next, selectedFileTypes);
  }, [exactMatch, query, selectedFileTypes, performSearch]);

  const sortedResults = useMemo(() => {
    const sorted = [...allResults];
    if (sortBy === 'fileName') sorted.sort((a, b) => a.fileName.localeCompare(b.fileName));
    else if (sortBy === 'rowNumber') sorted.sort((a, b) => a.rowNumber - b.rowNumber);
    return sorted;
  }, [allResults, sortBy]);

  const visibleResults = useMemo(() => sortedResults.slice(0, visibleCount), [sortedResults, visibleCount]);

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    // Fix: Explicitly typing headers as string[] to avoid 'unknown' index type error in line 219
    const headers: string[] = Array.from(new Set(allResults.flatMap(r => Object.keys(r.rowData))));
    const csvRows = [
      headers.join(','),
      ...allResults.map(r => headers.map(h => `"${String(r.rowData[h] || '').replace(/"/g, '""')}"`).join(','))
    ];
    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `xsearch_export_${Date.now()}.csv`;
    a.click();
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans">
      {/* Dynamic Header */}
      <header className="px-6 py-3 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-30 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2 rounded-xl">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-lg font-black tracking-tight text-white flex items-center gap-2">
              X-SEARCH <span className="text-blue-500">PRO</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-widest">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              Main Thread Memory Guard Active
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-5 py-2.5 rounded-xl font-black text-xs shadow-lg shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'CHANGE FOLDER' : 'OPEN FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Main Area */}
      <main className="flex-1 flex flex-col min-h-0 relative">
        <div className="px-6 py-6 bg-gray-900/80 backdrop-blur-xl border-b border-gray-800/50 shrink-0 z-20">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-4 items-center">
              <div className="relative flex-1 group">
                <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Search across ${files.length} sources...` : "Select folder to start..."}
                  className="w-full bg-gray-800/60 border border-gray-700/50 rounded-2xl py-4 pl-14 pr-6 text-base text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-all disabled:opacity-40 shadow-inner"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">
                      {Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%
                    </span>
                    <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2 shrink-0 bg-gray-800/80 border border-gray-700/50 rounded-2xl p-1 px-4">
                <Filter className="w-4 h-4 text-gray-500" />
                {['xlsx', 'csv', 'txt'].map(type => (
                  <button
                    key={type}
                    onClick={() => toggleFileType(type)}
                    className={`px-3 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-blue-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={onExactMatchToggle}
                  className={`flex items-center gap-3 text-[10px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600 shadow-[0_0_15px_rgba(37,99,235,0.3)]' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MODE
                </button>
                <div className="h-4 w-px bg-gray-800" />
                <div className="flex items-center gap-4 text-[10px] font-black text-gray-500">
                  <span className="flex items-center gap-2"><ArrowUpDown className="w-3.5 h-3.5" /> SORT BY:</span>
                  <select 
                    value={sortBy} 
                    onChange={(e) => setSortBy(e.target.value)}
                    className="bg-transparent border-none text-blue-400 focus:ring-0 cursor-pointer uppercase"
                  >
                    <option value="relevance">RELEVANCE</option>
                    <option value="fileName">FILE NAME</option>
                    <option value="rowNumber">ROW ORDER</option>
                  </select>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4">
                  <div className="text-[10px] font-black text-blue-500/80 tracking-widest bg-blue-500/5 px-4 py-2 rounded-xl border border-blue-500/10">
                    {allResults.length.toLocaleString()} HITS
                  </div>
                  <button 
                    onClick={exportToCSV}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-900/40"
                  >
                    <Download className="w-3.5 h-3.5" />
                    EXPORT ALL
                  </button>
                </div>
              )}
            </div>

            {/* Recent Searches */}
            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
                <History className="w-3.5 h-3.5 text-gray-600" />
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => { setQuery(s.query); performSearch(s.query, s.exactMatch, selectedFileTypes); }}
                      className="text-[9px] font-bold text-gray-500 hover:text-blue-400 bg-gray-800/40 px-3 py-1.5 rounded-lg border border-gray-800 transition-all uppercase tracking-tighter"
                    >
                      {s.query}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-auto bg-gray-950 p-6">
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30 select-none">
              <FolderOpen className="w-20 h-20 mb-6" />
              <h3 className="text-xl font-black uppercase tracking-[0.4em]">Initialize Archive</h3>
              <p className="text-xs font-bold mt-2">Select a folder to activate zero-latency local searching.</p>
            </div>
          ) : visibleResults.length > 0 ? (
            <div className="max-w-7xl mx-auto space-y-4">
              {visibleResults.map((res) => (
                <div 
                  key={res.id} 
                  className={`group bg-gray-900/40 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/50 rounded-[32px] shadow-2xl bg-gray-900/90' : 'border-gray-800/50 rounded-2xl hover:border-blue-500/30'}`}
                >
                  <div 
                    className="p-5 flex items-center justify-between cursor-pointer"
                    onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                  >
                    <div className="flex items-center gap-5 min-w-0">
                      <div className={`p-2 rounded-xl transition-colors ${expandedId === res.id ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-500 group-hover:text-blue-500'}`}>
                        <FileText className="w-5 h-5" />
                      </div>
                      <div className="min-w-0">
                        <div className="text-xs font-black text-gray-200 uppercase tracking-tight flex items-center gap-3">
                          {res.fileName}
                          {res.rowData._sheet && (
                            <span className="text-[9px] px-2 py-0.5 bg-indigo-500/10 text-indigo-400 rounded border border-indigo-500/20">{res.rowData._sheet}</span>
                          )}
                        </div>
                        <div className="text-[10px] font-bold text-gray-600 mt-1 uppercase tracking-widest flex items-center gap-3">
                          LINE {res.rowNumber} <span className="w-1 h-1 rounded-full bg-gray-800"></span> 
                          <span className="truncate max-w-lg text-gray-400">
                            {Object.values(res.rowData).filter(v => typeof v !== 'object').slice(0, 4).join(' | ')}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className={`p-2 transition-transform duration-300 ${expandedId === res.id ? 'rotate-180 text-blue-500' : 'text-gray-700'}`}>
                      <ChevronDown className="w-5 h-5" />
                    </div>
                  </div>

                  {expandedId === res.id && (
                    <div className="px-5 pb-5 animate-in slide-in-from-top-2">
                      <div className="bg-gray-950/50 rounded-2xl border border-gray-800/50 p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {Object.entries(res.rowData).map(([key, value]) => {
                          if (key.startsWith('_')) return null;
                          const strVal = String(value);
                          const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                          return (
                            <div key={key} className="space-y-1.5 group/item">
                              <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest group-hover/item:text-blue-500/60 transition-colors">{key}</span>
                              <div className={`text-sm font-mono break-all leading-relaxed p-2 rounded-lg border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-white font-bold' : 'bg-gray-900/50 border-gray-800 text-gray-400'}`}>
                                {strVal || <span className="opacity-20 italic">EMPTY</span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {visibleCount < allResults.length && (
                <button 
                  onClick={() => setVisibleCount(prev => prev + LOAD_MORE_STEP)}
                  className="w-full py-6 mt-4 bg-gray-900/20 border border-dashed border-gray-800 rounded-2xl text-[11px] font-black text-gray-500 hover:text-white hover:border-blue-500/50 transition-all uppercase tracking-[0.4em]"
                >
                  LOAD MORE ({allResults.length - visibleCount} REMAINING)
                </button>
              )}
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-20">
              <AlertTriangle className="w-16 h-16 mb-6" />
              <h4 className="text-xl font-black uppercase tracking-widest">No Matches</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter">Query returned zero correlated objects.</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-20">
              <Zap className="w-16 h-16 mb-6" />
              <h4 className="text-xl font-black uppercase tracking-widest">Engine Ready</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter">Enter a transaction query to start scanning.</p>
            </div>
          )}
        </div>
      </main>

      {/* Footer Info */}
      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-widest shrink-0">
        <div className="flex gap-8 items-center">
          <span className="flex items-center gap-2"><Clock className="w-4 h-4 text-blue-500/40" /> POOL SIZE: {MAX_WORKERS} THREADS</span>
          <div className="h-4 w-px bg-gray-800" />
          <span className="flex items-center gap-2 text-indigo-500/40"><Database className="w-4 h-4" /> LOCAL_ENGINE_ACTIVE</span>
        </div>
        <div className="text-gray-700 italic">
          X-SEARCH PRO // V3.2.0 // ZERO-MEMORY LEAK ARCHITECTURE
        </div>
      </footer>
    </div>
  );
};

export default App;

/**
 * X-Search Pro Background Worker (Memory-Safe Edition)
 * Optimized to prevent main-thread crashes by using small chunks and field truncation.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  const CHUNK_SIZE = 50; // Smaller chunks for even better responsiveness
  const MAX_FIELD_LENGTH = 1000; // Truncate extremely long cells to prevent memory bloat

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    switch (action) {
      case 'PROCESS_FILE':
        await processFile(payload);
        break;
    }
  };

  function truncate(val) {
    if (typeof val === 'string' && val.length > MAX_FIELD_LENGTH) {
      return val.substring(0, MAX_FIELD_LENGTH) + "... (truncated)";
    }
    return val;
  }

  async function processFile({ fileId, blob, type, name, path, query, exactMatch }) {
    try {
      const lowerQuery = query ? query.toLowerCase() : "";
      let matches = [];
      let totalRowsInFile = 0;

      const onRowProcessed = (row, sheetName = null) => {
        totalRowsInFile++;

        // Sanitize and truncate row data to protect memory
        const cleanRow = {};
        const values = [];
        for (const [k, v] of Object.entries(row)) {
          const truncatedVal = truncate(v);
          cleanRow[k] = truncatedVal;
          if (v !== null && v !== undefined && v !== "") {
            values.push(String(truncatedVal).toLowerCase());
          }
        }

        const searchString = values.join(' ');
        let isMatch = false;

        if (lowerQuery) {
          if (exactMatch) {
            isMatch = Object.values(cleanRow).some(val => String(val).toLowerCase() === lowerQuery);
          } else {
            isMatch = searchString.includes(lowerQuery);
          }
        } else {
          isMatch = true; 
        }

        if (isMatch) {
          matches.push({
            id: \`\${fileId}-\${sheetName || 'default'}-\${totalRowsInFile}\`,
            fileName: name,
            filePath: path,
            sheetName: sheetName,
            rowNumber: totalRowsInFile + 1,
            rowData: cleanRow,
            searchString: searchString.substring(0, 500) // Keep preview string short
          });

          if (matches.length >= CHUNK_SIZE) {
            self.postMessage({ 
              action: 'MATCH_CHUNK', 
              payload: { fileId, matches } 
            });
            matches = [];
          }
        }
      };

      if (type === 'xlsx' || type === 'xls') {
        const buffer = await blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { 
          type: 'array', 
          cellDates: true, 
          cellFormula: false, 
          cellText: false,
          cellNF: false,
          cellHTML: false
        });

        workbook.SheetNames.forEach(sheetName => {
          const sheet = workbook.Sheets[sheetName];
          if (!sheet) return;
          const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });
          jsonData.forEach(row => onRowProcessed(row, sheetName));
        });
      } else if (type === 'csv') {
        const text = await blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });
        parsed.data.forEach(row => onRowProcessed(row));
      } else if (type === 'txt') {
        const text = await blob.text();
        const lines = text.split(/\\r?\\n/);
        lines.forEach((line) => onRowProcessed({ content: line.trim() }));
      }

      if (matches.length > 0) {
        self.postMessage({ 
          action: 'MATCH_CHUNK', 
          payload: { fileId, matches } 
        });
      }

      self.postMessage({ 
        action: 'FILE_COMPLETE', 
        payload: { fileId, totalRows: totalRowsInFile } 
      });

    } catch (err) {
      self.postMessage({ 
        action: 'FILE_ERROR', 
        payload: { fileId, error: err.message } 
      });
    }
  }
`;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  Filter,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const INITIAL_VISIBLE_COUNT = 50;
const LOAD_MORE_STEP = 50;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [visibleCount, setVisibleCount] = useState(INITIAL_VISIBLE_COUNT);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [error, setError] = useState<string | null>(null);
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);

  // Load recent searches
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  const saveSearch = useCallback((q: string, exact: boolean, types: string[]) => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { query: q, timestamp: Date.now(), exactMatch: exact };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;

    setError(null);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);
    setShowSummary(false);

    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }

    if (fileList.length === 0) {
      setError("No transaction-compatible files discovered.");
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[]) => {
    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => types.includes(f.type));
    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact, types);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;

      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;

        if (action === 'MATCH_CHUNK') {
          // Use functional update to avoid stale closures
          setAllResults(prev => [...prev, ...payload.matches]);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) 
      ? selectedFileTypes.filter(t => t !== type)
      : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      let valA: any = a[sortConfig.key as keyof SearchResult] || a.rowData[sortConfig.key] || '';
      let valB: any = b[sortConfig.key as keyof SearchResult] || b.rowData[sortConfig.key] || '';

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  const visibleResults = useMemo(() => sortedResults.slice(0, visibleCount), [sortedResults, visibleCount]);

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    const headers = ['FileName', 'Path', 'Sheet', 'Row', ...Array.from(new Set(allResults.flatMap(r => Object.keys(r.rowData).filter(k => !k.startsWith('_')))))];
    const csvContent = [
      headers.join(','),
      ...allResults.map(r => {
        return headers.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'Path') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `xsearch_export_${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans">
      {/* Search Finished Popup */}
      {showSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-blue-900/40">
                <CheckCircle2 className="w-8 h-8 text-white" />
              </div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Search Complete</h2>
              <p className="text-gray-400 text-sm mb-6">
                Found <span className="text-white font-bold">{allResults.length.toLocaleString()}</span> hits across <span className="text-white font-bold">{searchProgress.total}</span> files in <span className="text-white font-bold">{((Date.now() - startTime.current) / 1000).toFixed(2)}s</span>.
              </p>
              <button 
                onClick={() => setShowSummary(false)}
                className="w-full py-3 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all"
              >
                Dismiss Report
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="px-6 py-3 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-30 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2 rounded-xl">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-lg font-black tracking-tight text-white flex items-center gap-2 uppercase">
              X-SEARCH <span className="text-blue-500">PRO</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-widest">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              Memory Guard: ON
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-6 py-2.5 rounded-xl font-black text-xs shadow-lg shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'SWITCH SOURCE' : 'MOUNT SOURCE'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Main Container */}
      <main className="flex-1 flex flex-col min-h-0 relative">
        <div className="px-6 py-6 bg-gray-900/80 backdrop-blur-xl border-b border-gray-800/50 shrink-0 z-20">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-4 items-center">
              <div className="relative flex-1 group">
                <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Query ${files.length} mounted files...` : "Select source folder to initialize..."}
                  className="w-full bg-gray-800/60 border border-gray-700/50 rounded-2xl py-4 pl-14 pr-6 text-base text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-all disabled:opacity-40 shadow-inner"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">
                      {Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%
                    </span>
                    <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2 shrink-0 bg-gray-800/80 border border-gray-700/50 rounded-2xl p-1 px-4">
                <Filter className="w-4 h-4 text-gray-500" />
                {['xlsx', 'csv', 'txt'].map(type => (
                  <button
                    key={type}
                    onClick={() => toggleFileType(type === 'xlsx' ? 'xlsx' : type)}
                    className={`px-3 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-blue-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => { setExactMatch(!exactMatch); performSearch(query, !exactMatch, selectedFileTypes); }}
                  className={`flex items-center gap-3 text-[10px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MODE
                </button>
                <div className="h-4 w-px bg-gray-800" />
                <div className="flex items-center gap-4 text-[10px] font-black text-gray-500">
                  <span className="flex items-center gap-2 uppercase"><ArrowUpDown className="w-3.5 h-3.5" /> Sorting:</span>
                  <div className="flex gap-2">
                    {['relevance', 'fileName', 'rowNumber'].map(key => (
                      <button 
                        key={key}
                        onClick={() => handleSort(key)}
                        className={`px-3 py-1.5 rounded-lg border transition-all uppercase ${sortConfig.key === key ? 'bg-blue-500/10 border-blue-500/50 text-blue-400' : 'bg-gray-800/50 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                      >
                        {key === 'rowNumber' ? 'Order' : key === 'fileName' ? 'File' : 'Rel.'}
                        {sortConfig.key === key && (sortConfig.direction === 'asc' ? <ArrowUp className="inline w-2.5 h-2.5 ml-1" /> : <ArrowDown className="inline w-2.5 h-2.5 ml-1" />)}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4">
                  <div className="text-[10px] font-black text-blue-500/80 tracking-widest bg-blue-500/5 px-4 py-2 rounded-xl border border-blue-500/10">
                    {allResults.length.toLocaleString()} HITS FOUND
                  </div>
                  <button 
                    onClick={exportToCSV}
                    className="flex items-center gap-2 px-5 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-900/40 transition-all"
                  >
                    <Download className="w-3.5 h-3.5" />
                    EXPORT DATA
                  </button>
                </div>
              )}
            </div>

            {/* Recent Searches */}
            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
                <History className="w-3.5 h-3.5 text-gray-600" />
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => { setQuery(s.query); performSearch(s.query, s.exactMatch, selectedFileTypes); }}
                      className="text-[9px] font-bold text-gray-500 hover:text-blue-400 bg-gray-800/40 px-3 py-1.5 rounded-lg border border-gray-800 transition-all uppercase tracking-tighter"
                    >
                      {s.query}
                    </button>
                  ))}
                  <button 
                    onClick={() => { setRecentSearches([]); localStorage.removeItem('xsearch_pro_history'); }}
                    className="text-[9px] font-bold text-red-500/50 hover:text-red-500 px-2"
                  >
                    Clear
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Results List */}
        <div className="flex-1 overflow-auto bg-gray-950 p-6 scroll-smooth">
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10 select-none grayscale">
              <Database className="w-24 h-24 mb-6" />
              <h3 className="text-2xl font-black uppercase tracking-[0.6em]">System Offline</h3>
              <p className="text-xs font-bold mt-2 uppercase tracking-[0.2em]">Mount a directory to enable local indexing.</p>
            </div>
          ) : visibleResults.length > 0 ? (
            <div className="max-w-7xl mx-auto space-y-4">
              {visibleResults.map((res) => (
                <div 
                  key={res.id} 
                  className={`group bg-gray-900/30 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/60 rounded-[32px] shadow-2xl bg-gray-900/95 ring-1 ring-blue-500/20' : 'border-gray-800/40 rounded-2xl hover:border-gray-700 hover:bg-gray-900/50'}`}
                >
                  <div 
                    className="p-5 flex items-center justify-between cursor-pointer"
                    onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                  >
                    <div className="flex items-center gap-6 min-w-0">
                      <div className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${expandedId === res.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-gray-800/80 text-gray-600 group-hover:text-blue-400 group-hover:bg-gray-800'}`}>
                        {res.fileName.endsWith('.csv') ? <FileCode className="w-5 h-5" /> : <FileSpreadsheet className="w-5 h-5" />}
                      </div>
                      <div className="min-w-0">
                        <div className="text-xs font-black text-gray-200 uppercase tracking-tight flex items-center gap-3">
                          {res.fileName}
                          {res.sheetName && (
                            <span className="text-[9px] px-2 py-0.5 bg-blue-500/10 text-blue-400 rounded-md border border-blue-500/20 font-bold uppercase">{res.sheetName}</span>
                          )}
                        </div>
                        <div className="text-[10px] font-bold text-gray-500 mt-1 uppercase tracking-widest flex items-center gap-3">
                          LINE: {res.rowNumber} <span className="w-1 h-1 rounded-full bg-gray-800"></span> 
                          <span className="truncate max-w-lg text-gray-400 font-mono italic">
                            {Object.values(res.rowData).slice(0, 5).join(' | ')}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className={`p-3 rounded-full transition-all ${expandedId === res.id ? 'bg-blue-600/10 text-blue-500 rotate-180' : 'text-gray-700'}`}>
                      <ChevronDown className="w-5 h-5" />
                    </div>
                  </div>

                  {expandedId === res.id && (
                    <div className="px-6 pb-6 animate-in slide-in-from-top-4 duration-300">
                      <div className="h-px bg-gradient-to-r from-transparent via-gray-800 to-transparent mb-6 opacity-50" />
                      <div className="bg-gray-950/40 rounded-[24px] border border-gray-800/50 p-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-8 gap-x-12">
                        {Object.entries(res.rowData).map(([key, value]) => {
                          if (key.startsWith('_')) return null;
                          const strVal = String(value);
                          const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                          return (
                            <div key={key} className="space-y-2 group/item">
                              <span className="text-[9px] font-black text-gray-600 uppercase tracking-[0.2em] group-hover/item:text-blue-500/80 transition-colors block">{key}</span>
                              <div className={`text-sm font-medium leading-relaxed p-3 rounded-xl border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-blue-100 shadow-inner' : 'bg-gray-900/60 border-gray-800 text-gray-400'}`}>
                                {strVal || <span className="opacity-20 italic">NULL_FIELD</span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {visibleCount < allResults.length && (
                <button 
                  onClick={() => setVisibleCount(prev => prev + LOAD_MORE_STEP)}
                  className="w-full py-8 mt-6 bg-gray-900/20 border border-dashed border-gray-800 rounded-[24px] text-[11px] font-black text-gray-600 hover:text-white hover:border-blue-500/40 hover:bg-blue-500/5 transition-all uppercase tracking-[0.5em]"
                >
                  LOAD MORE ({allResults.length - visibleCount} OBJECTS REMAINING)
                </button>
              )}
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30">
              <AlertTriangle className="w-16 h-16 mb-6 text-amber-500" />
              <h4 className="text-xl font-black uppercase tracking-widest">Zero Matches Found</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter text-gray-500">The query signature does not match any hosted objects.</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-10">
              <Zap className="w-20 h-20 mb-6 text-blue-500" />
              <h4 className="text-xl font-black uppercase tracking-[0.4em]">Engine Standby</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter text-gray-500">Initiate search to activate the local indexing pipeline.</p>
            </div>
          )}
        </div>
      </main>

      {/* Footer */}
      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-widest shrink-0">
        <div className="flex gap-8 items-center">
          <span className="flex items-center gap-2"><Clock className="w-4 h-4 text-blue-500/40" /> THREAD_POOL: {MAX_WORKERS} CORES</span>
          <div className="h-4 w-px bg-gray-800" />
          <span className="flex items-center gap-2 text-indigo-500/40"><Database className="w-4 h-4" /> LOCAL_ENGINE: ENCRYPTED</span>
        </div>
        <div className="flex items-center gap-6">
          <span className="text-green-500/40 flex items-center gap-2"><ShieldCheck className="w-4 h-4" /> 100% PRIVATE</span>
          <div className="h-4 w-px bg-gray-800" />
          <div className="text-gray-700">
            X-SEARCH PRO // V3.2.0 // STABLE BUILD
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  Filter,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const INITIAL_VISIBLE_COUNT = 50;
const LOAD_MORE_STEP = 50;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [visibleCount, setVisibleCount] = useState(INITIAL_VISIBLE_COUNT);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [error, setError] = useState<string | null>(null);
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);

  // Load recent searches
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  const saveSearch = useCallback((q: string, exact: boolean, types: string[]) => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { query: q, timestamp: Date.now(), exactMatch: exact };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;

    setError(null);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);
    setShowSummary(false);

    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }

    if (fileList.length === 0) {
      setError("No transaction-compatible files discovered.");
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[]) => {
    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setAllResults([]);
    setVisibleCount(INITIAL_VISIBLE_COUNT);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => types.includes(f.type));
    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact, types);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;

      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;

        if (action === 'MATCH_CHUNK') {
          // Use functional update to avoid stale closures
          setAllResults(prev => [...prev, ...payload.matches]);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) 
      ? selectedFileTypes.filter(t => t !== type)
      : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      // Accessing property either from the SearchResult object itself or from its rowData
      // Using 'as any' here because sortConfig.key might be a key in SearchResult OR in rowData
      // Added nullish coalescing for safer access to potential falsey values like 0 or empty strings
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  const visibleResults = useMemo(() => sortedResults.slice(0, visibleCount), [sortedResults, visibleCount]);

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    // Fix: Explicitly type headers to ensure 'h' in headers.map is string, avoiding 'unknown' index type errors
    const dynamicHeaders: string[] = Array.from(new Set(allResults.flatMap(r => Object.keys(r.rowData).filter(k => !k.startsWith('_')))));
    const headers: string[] = ['FileName', 'Path', 'Sheet', 'Row', ...dynamicHeaders];

    const csvContent = [
      headers.join(','),
      ...allResults.map(r => {
        return headers.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'Path') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          // Fixed: Accessing rowData with a safe string index to prevent 'unknown' index type error on line 248
          else val = String(r.rowData[h as string] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `xsearch_export_${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans">
      {/* Search Finished Popup */}
      {showSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-blue-900/40">
                <CheckCircle2 className="w-8 h-8 text-white" />
              </div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Search Complete</h2>
              <p className="text-gray-400 text-sm mb-6">
                Found <span className="text-white font-bold">{allResults.length.toLocaleString()}</span> hits across <span className="text-white font-bold">{searchProgress.total}</span> files in <span className="text-white font-bold">{((Date.now() - startTime.current) / 1000).toFixed(2)}s</span>.
              </p>
              <button 
                onClick={() => setShowSummary(false)}
                className="w-full py-3 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all"
              >
                Dismiss Report
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="px-6 py-3 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-30 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2 rounded-xl">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-lg font-black tracking-tight text-white flex items-center gap-2 uppercase">
              X-SEARCH <span className="text-blue-500">PRO</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-widest">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              Memory Guard: ON
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-6 py-2.5 rounded-xl font-black text-xs shadow-lg shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'SWITCH SOURCE' : 'MOUNT SOURCE'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Main Container */}
      <main className="flex-1 flex flex-col min-h-0 relative">
        <div className="px-6 py-6 bg-gray-900/80 backdrop-blur-xl border-b border-gray-800/50 shrink-0 z-20">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-4 items-center">
              <div className="relative flex-1 group">
                <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Query ${files.length} mounted files...` : "Select source folder to initialize..."}
                  className="w-full bg-gray-800/60 border border-gray-700/50 rounded-2xl py-4 pl-14 pr-6 text-base text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 transition-all disabled:opacity-40 shadow-inner"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">
                      {Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%
                    </span>
                    <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2 shrink-0 bg-gray-800/80 border border-gray-700/50 rounded-2xl p-1 px-4">
                <Filter className="w-4 h-4 text-gray-500" />
                {['xlsx', 'csv', 'txt'].map(type => (
                  <button
                    key={type}
                    onClick={() => toggleFileType(type === 'xlsx' ? 'xlsx' : type)}
                    className={`px-3 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-blue-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => { setExactMatch(!exactMatch); performSearch(query, !exactMatch, selectedFileTypes); }}
                  className={`flex items-center gap-3 text-[10px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MODE
                </button>
                <div className="h-4 w-px bg-gray-800" />
                <div className="flex items-center gap-4 text-[10px] font-black text-gray-500">
                  <span className="flex items-center gap-2 uppercase"><ArrowUpDown className="w-3.5 h-3.5" /> Sorting:</span>
                  <div className="flex gap-2">
                    {['relevance', 'fileName', 'rowNumber'].map(key => (
                      <button 
                        key={key}
                        onClick={() => handleSort(key)}
                        className={`px-3 py-1.5 rounded-lg border transition-all uppercase ${sortConfig.key === key ? 'bg-blue-500/10 border-blue-500/50 text-blue-400' : 'bg-gray-800/50 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                      >
                        {key === 'rowNumber' ? 'Order' : key === 'fileName' ? 'File' : 'Rel.'}
                        {sortConfig.key === key && (sortConfig.direction === 'asc' ? <ArrowUp className="inline w-2.5 h-2.5 ml-1" /> : <ArrowDown className="inline w-2.5 h-2.5 ml-1" />)}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4">
                  <div className="text-[10px] font-black text-blue-500/80 tracking-widest bg-blue-500/5 px-4 py-2 rounded-xl border border-blue-500/10">
                    {allResults.length.toLocaleString()} HITS FOUND
                  </div>
                  <button 
                    onClick={exportToCSV}
                    className="flex items-center gap-2 px-5 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-900/40 transition-all"
                  >
                    <Download className="w-3.5 h-3.5" />
                    EXPORT DATA
                  </button>
                </div>
              )}
            </div>

            {/* Recent Searches */}
            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
                <History className="w-3.5 h-3.5 text-gray-600" />
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => { setQuery(s.query); performSearch(s.query, s.exactMatch, selectedFileTypes); }}
                      className="text-[9px] font-bold text-gray-500 hover:text-blue-400 bg-gray-800/40 px-3 py-1.5 rounded-lg border border-gray-800 transition-all uppercase tracking-tighter"
                    >
                      {s.query}
                    </button>
                  ))}
                  <button 
                    onClick={() => { setRecentSearches([]); localStorage.removeItem('xsearch_pro_history'); }}
                    className="text-[9px] font-bold text-red-500/50 hover:text-red-500 px-2"
                  >
                    Clear
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Results List */}
        <div className="flex-1 overflow-auto bg-gray-950 p-6 scroll-smooth">
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10 select-none grayscale">
              <Database className="w-24 h-24 mb-6" />
              <h3 className="text-2xl font-black uppercase tracking-[0.6em]">System Offline</h3>
              <p className="text-xs font-bold mt-2 uppercase tracking-[0.2em]">Mount a directory to enable local indexing.</p>
            </div>
          ) : visibleResults.length > 0 ? (
            <div className="max-w-7xl mx-auto space-y-4">
              {visibleResults.map((res) => (
                <div 
                  key={res.id} 
                  className={`group bg-gray-900/30 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/60 rounded-[32px] shadow-2xl bg-gray-900/95 ring-1 ring-blue-500/20' : 'border-gray-800/40 rounded-2xl hover:border-gray-700 hover:bg-gray-900/50'}`}
                >
                  <div 
                    className="p-5 flex items-center justify-between cursor-pointer"
                    onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                  >
                    <div className="flex items-center gap-6 min-w-0">
                      <div className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${expandedId === res.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-gray-800/80 text-gray-600 group-hover:text-blue-400 group-hover:bg-gray-800'}`}>
                        {res.fileName.endsWith('.csv') ? <FileCode className="w-5 h-5" /> : <FileSpreadsheet className="w-5 h-5" />}
                      </div>
                      <div className="min-w-0">
                        <div className="text-xs font-black text-gray-200 uppercase tracking-tight flex items-center gap-3">
                          {res.fileName}
                          {res.sheetName && (
                            <span className="text-[9px] px-2 py-0.5 bg-blue-500/10 text-blue-400 rounded-md border border-blue-500/20 font-bold uppercase">{res.sheetName}</span>
                          )}
                        </div>
                        <div className="text-[10px] font-bold text-gray-500 mt-1 uppercase tracking-widest flex items-center gap-3">
                          LINE: {res.rowNumber} <span className="w-1 h-1 rounded-full bg-gray-800"></span> 
                          <span className="truncate max-w-lg text-gray-400 font-mono italic">
                            {Object.values(res.rowData).slice(0, 5).join(' | ')}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className={`p-3 rounded-full transition-all ${expandedId === res.id ? 'bg-blue-600/10 text-blue-500 rotate-180' : 'text-gray-700'}`}>
                      <ChevronDown className="w-5 h-5" />
                    </div>
                  </div>

                  {expandedId === res.id && (
                    <div className="px-6 pb-6 animate-in slide-in-from-top-4 duration-300">
                      <div className="h-px bg-gradient-to-r from-transparent via-gray-800 to-transparent mb-6 opacity-50" />
                      <div className="bg-gray-950/40 rounded-[24px] border border-gray-800/50 p-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-8 gap-x-12">
                        {Object.entries(res.rowData).map(([key, value]) => {
                          if (key.startsWith('_')) return null;
                          const strVal = String(value);
                          const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                          return (
                            <div key={key} className="space-y-2 group/item">
                              <span className="text-[9px] font-black text-gray-600 uppercase tracking-[0.2em] group-hover/item:text-blue-500/80 transition-colors block">{key}</span>
                              <div className={`text-sm font-medium leading-relaxed p-3 rounded-xl border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-blue-100 shadow-inner' : 'bg-gray-900/60 border-gray-800 text-gray-400'}`}>
                                {strVal || <span className="opacity-20 italic">NULL_FIELD</span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {visibleCount < allResults.length && (
                <button 
                  onClick={() => setVisibleCount(prev => prev + LOAD_MORE_STEP)}
                  className="w-full py-8 mt-6 bg-gray-900/20 border border-dashed border-gray-800 rounded-[24px] text-[11px] font-black text-gray-600 hover:text-white hover:border-blue-500/40 hover:bg-blue-500/5 transition-all uppercase tracking-[0.5em]"
                >
                  LOAD MORE ({allResults.length - visibleCount} OBJECTS REMAINING)
                </button>
              )}
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30">
              <AlertTriangle className="w-16 h-16 mb-6 text-amber-500" />
              <h4 className="text-xl font-black uppercase tracking-widest">Zero Matches Found</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter text-gray-500">The query signature does not match any hosted objects.</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-10">
              <Zap className="w-20 h-20 mb-6 text-blue-500" />
              <h4 className="text-xl font-black uppercase tracking-[0.4em]">Engine Standby</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-tighter text-gray-500">Initiate search to activate the local indexing pipeline.</p>
            </div>
          )}
        </div>
      </main>

      {/* Footer */}
      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-widest shrink-0">
        <div className="flex gap-8 items-center">
          <span className="flex items-center gap-2"><Clock className="w-4 h-4 text-blue-500/40" /> THREAD_POOL: {MAX_WORKERS} CORES</span>
          <div className="h-4 w-px bg-gray-800" />
          <span className="flex items-center gap-2 text-indigo-500/40"><Database className="w-4 h-4" /> LOCAL_ENGINE: ENCRYPTED</span>
        </div>
        <div className="flex items-center gap-6">
          <span className="text-green-500/40 flex items-center gap-2"><ShieldCheck className="w-4 h-4" /> 100% PRIVATE</span>
          <div className="h-4 w-px bg-gray-800" />
          <div className="text-gray-700">
            X-SEARCH PRO // V3.2.0 // STABLE BUILD
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  Filter,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown,
  Columns,
  MinusCircle,
  PlusCircle,
  Settings2
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const ROW_HEIGHT = 80; // Estimated collapsed row height
const VIRTUAL_BUFFER = 5;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [filterMode, setFilterMode] = useState<'include' | 'exclude'>('include');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportColumns, setExportColumns] = useState<string[]>([]);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Load recent searches
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  // Sync scroll and measure container
  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) {
        setContainerHeight(scrollContainerRef.current.clientHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const saveSearch = useCallback((q: string, exact: boolean) => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { query: q, timestamp: Date.now(), exactMatch: exact };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;

    setAllResults([]);
    setShowSummary(false);

    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => {
      const isIncluded = types.includes(f.type);
      return mode === 'include' ? isIncluded : !isIncluded;
    });

    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;

      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;

        if (action === 'MATCH_CHUNK') {
          setAllResults(prev => [...prev, ...payload.matches]);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes, filterMode);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) 
      ? selectedFileTypes.filter(t => t !== type)
      : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next, filterMode);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const availableColumns = useMemo(() => {
    const cols = new Set<string>(['FileName', 'Path', 'Sheet', 'Row']);
    allResults.slice(0, 100).forEach(r => {
      Object.keys(r.rowData).forEach(k => {
        if (!k.startsWith('_')) cols.add(k);
      });
    });
    return Array.from(cols);
  }, [allResults]);

  useEffect(() => {
    setExportColumns(availableColumns);
  }, [availableColumns]);

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  // Virtual Scrolling Calculations
  const startIdx = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
  const endIdx = Math.min(sortedResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
  const visibleItems = sortedResults.slice(startIdx, endIdx);
  const totalHeight = sortedResults.length * ROW_HEIGHT;
  const offsetY = startIdx * ROW_HEIGHT;

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    const csvContent = [
      exportColumns.join(','),
      ...allResults.map(r => {
        return exportColumns.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'Path') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_pro_export_${Date.now()}.csv`;
    link.click();
    setShowExportModal(false);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans selection:bg-blue-500/30">

      {/* Search Finished Popup */}
      {showSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-blue-900/40">
                <CheckCircle2 className="w-8 h-8 text-white" />
              </div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Search Complete</h2>
              <p className="text-gray-400 text-sm mb-6">
                Indexed <span className="text-white font-bold">{allResults.length.toLocaleString()}</span> hits across <span className="text-white font-bold">{searchProgress.total}</span> sources in <span className="text-white font-bold">{((Date.now() - startTime.current) / 1000).toFixed(2)}s</span>.
              </p>
              <button onClick={() => setShowSummary(false)} className="w-full py-3 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Dismiss</button>
            </div>
          </div>
        </div>
      )}

      {/* CSV Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
          <div className="bg-gray-900 border border-gray-800 rounded-[40px] p-8 max-w-2xl w-full shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-500/10 rounded-2xl border border-indigo-500/20 text-indigo-400">
                  <Columns className="w-6 h-6" />
                </div>
                <h2 className="text-2xl font-black uppercase tracking-tight">Configure Export</h2>
              </div>
              <button onClick={() => setShowExportModal(false)} className="p-3 bg-gray-800/50 hover:bg-red-500/10 text-gray-500 hover:text-red-400 rounded-full transition-all"><X className="w-6 h-6" /></button>
            </div>

            <p className="text-gray-500 text-xs font-bold uppercase tracking-widest mb-6 px-1">Select Columns to Include:</p>

            <div className="flex-1 overflow-auto px-1 space-y-2 mb-8 grid grid-cols-2 gap-3 auto-rows-min">
              {availableColumns.map(col => (
                <button
                  key={col}
                  onClick={() => setExportColumns(prev => prev.includes(col) ? prev.filter(c => c !== col) : [...prev, col])}
                  className={`flex items-center justify-between px-5 py-3 rounded-2xl border transition-all text-xs font-bold uppercase ${exportColumns.includes(col) ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-400' : 'bg-gray-800/30 border-gray-800 text-gray-500'}`}
                >
                  {col}
                  {exportColumns.includes(col) ? <CheckCircle2 className="w-4 h-4" /> : <div className="w-4 h-4 rounded-full border border-gray-700" />}
                </button>
              ))}
            </div>

            <div className="flex gap-4">
              <button onClick={() => setExportColumns([])} className="flex-1 py-4 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Select None</button>
              <button onClick={() => setExportColumns(availableColumns)} className="flex-1 py-4 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Select All</button>
              <button onClick={exportToCSV} className="flex-[2] py-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-indigo-900/40">Download CSV</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="px-6 py-4 bg-gray-900/50 backdrop-blur-xl border-b border-gray-800 flex justify-between items-center shrink-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2.5 rounded-2xl shadow-lg shadow-blue-900/20">
            <Zap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight text-white flex items-center gap-2 uppercase">
              X-SEARCH <span className="text-blue-500">PRO</span>
            </h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-[0.2em] mt-0.5">
              <ShieldCheck className="w-3 h-3 text-green-500" />
              100% Client-Side Engine
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-7 py-3 rounded-2xl font-black text-xs shadow-xl shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'RE-MOUNT SOURCE' : 'MOUNT FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      {/* Control Panel */}
      <main className="flex-1 flex flex-col min-h-0 relative">
        <div className="px-6 py-8 bg-gray-900/30 border-b border-gray-800/50 shrink-0 z-20">
          <div className="max-w-7xl mx-auto space-y-8">
            <div className="flex gap-6 items-start">
              <div className="relative flex-1 group">
                <Search className={`absolute left-6 top-[26px] -translate-y-1/2 w-6 h-6 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Query across ${files.length.toLocaleString()} files...` : "Choose a source folder to activate the indexer..."}
                  className="w-full bg-gray-800/40 border border-gray-700/50 rounded-[28px] py-6 pl-16 pr-8 text-lg text-white placeholder-gray-600 focus:outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500/50 transition-all disabled:opacity-30 shadow-2xl"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-6 top-1/2 -translate-y-1/2 flex items-center gap-4 bg-gray-900/80 px-4 py-2 rounded-xl border border-gray-800">
                    <span className="text-xs font-black text-blue-500 uppercase tracking-widest">
                      Indexing {Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%
                    </span>
                    <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex flex-col gap-3 shrink-0">
                <div className="flex items-center gap-2 bg-gray-800/40 border border-gray-700/50 rounded-2xl p-2 pr-4 shadow-xl">
                  <button 
                    onClick={() => { const nm = filterMode === 'include' ? 'exclude' : 'include'; setFilterMode(nm); performSearch(query, exactMatch, selectedFileTypes, nm); }}
                    className={`p-2 rounded-xl transition-all flex items-center gap-2 px-3 ${filterMode === 'include' ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'}`}
                  >
                    {filterMode === 'include' ? <PlusCircle className="w-4 h-4" /> : <MinusCircle className="w-4 h-4" />}
                    <span className="text-[10px] font-black uppercase tracking-widest">{filterMode}</span>
                  </button>
                  <div className="w-px h-6 bg-gray-700" />
                  <div className="flex items-center gap-1">
                    {['xlsx', 'csv', 'txt'].map(type => (
                      <button
                        key={type}
                        onClick={() => toggleFileType(type)}
                        className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-gray-700 text-white border border-gray-600' : 'text-gray-500 hover:text-gray-300'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-8">
                <button 
                  onClick={() => { setExactMatch(!exactMatch); performSearch(query, !exactMatch, selectedFileTypes, filterMode); }}
                  className={`flex items-center gap-4 text-[11px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-11 h-6 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600 shadow-[0_0_20px_rgba(37,99,235,0.4)]' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT SIGNATURE
                </button>
                <div className="h-6 w-px bg-gray-800" />
                <div className="flex items-center gap-6 text-[11px] font-black text-gray-500">
                  <span className="flex items-center gap-2 uppercase tracking-[0.2em]"><ArrowUpDown className="w-4 h-4 text-gray-600" /> SORT SEQUENCE:</span>
                  <div className="flex gap-2.5">
                    {['relevance', 'fileName', 'rowNumber'].map(key => (
                      <button 
                        key={key}
                        onClick={() => handleSort(key)}
                        className={`px-4 py-2 rounded-xl border transition-all uppercase tracking-tighter ${sortConfig.key === key ? 'bg-blue-500/10 border-blue-500/50 text-blue-400 shadow-[0_0_20px_rgba(59,130,246,0.1)]' : 'bg-gray-800/30 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                      >
                        {key === 'rowNumber' ? 'Line' : key === 'fileName' ? 'File' : 'Rel.'}
                        {sortConfig.key === key && (sortConfig.direction === 'asc' ? <ArrowUp className="inline w-3 h-3 ml-2" /> : <ArrowDown className="inline w-3 h-3 ml-2" />)}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-5">
                  <div className="text-[11px] font-black text-blue-500/90 tracking-[0.2em] bg-blue-500/5 px-6 py-2.5 rounded-2xl border border-blue-500/10 shadow-lg shadow-blue-500/5">
                    {allResults.length.toLocaleString()} OBJECTS MATCHED
                  </div>
                  <button 
                    onClick={() => setShowExportModal(true)}
                    className="flex items-center gap-3 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl text-[11px] font-black uppercase shadow-xl shadow-indigo-900/40 transition-all active:scale-95"
                  >
                    <Download className="w-4 h-4" />
                    EXPORT DATA
                  </button>
                </div>
              )}
            </div>

            {/* Recent Searches */}
            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-4 animate-in fade-in slide-in-from-top-2">
                <div className="flex items-center gap-2 text-[10px] font-black text-gray-600 uppercase tracking-widest">
                  <History className="w-4 h-4" /> HISTORY
                </div>
                <div className="flex flex-wrap gap-2 flex-1">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => { setQuery(s.query); performSearch(s.query, s.exactMatch, selectedFileTypes, filterMode); }}
                      className="text-[10px] font-bold text-gray-500 hover:text-white bg-gray-800/20 px-4 py-2 rounded-xl border border-gray-800/50 transition-all uppercase tracking-tight flex items-center gap-2 hover:bg-gray-800 group"
                    >
                      {s.query}
                      <ChevronRight className="w-3 h-3 opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all" />
                    </button>
                  ))}
                  <button onClick={() => { setRecentSearches([]); localStorage.removeItem('xsearch_pro_history'); }} className="text-[10px] font-bold text-red-500/40 hover:text-red-500 px-4 transition-colors">Clear</button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Results Container with Virtual Scrolling */}
        <div 
          ref={scrollContainerRef}
          onScroll={handleScroll}
          className="flex-1 overflow-auto bg-gray-950 px-6 py-8 relative scroll-smooth"
        >
          {files.length === 0 ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center opacity-[0.03] select-none pointer-events-none grayscale">
              <Database className="w-64 h-64 mb-12" />
              <h3 className="text-6xl font-black uppercase tracking-[0.8em]">Offline</h3>
              <p className="text-xl font-bold mt-4 uppercase tracking-[0.4em]">Index initialization required</p>
            </div>
          ) : sortedResults.length > 0 ? (
            <div className="max-w-7xl mx-auto relative" style={{ height: totalHeight }}>
              <div style={{ transform: `translateY(${offsetY}px)` }} className="space-y-4">
                {visibleItems.map((res) => (
                  <div 
                    key={res.id} 
                    className={`group bg-gray-900/40 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/50 rounded-[36px] shadow-2xl bg-gray-900/95 ring-1 ring-blue-500/20' : 'border-gray-800/50 rounded-3xl hover:border-gray-700/80 hover:bg-gray-900/60'}`}
                    style={{ height: expandedId === res.id ? 'auto' : ROW_HEIGHT - 16 }}
                  >
                    <div 
                      className="p-5 flex items-center justify-between cursor-pointer"
                      onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                    >
                      <div className="flex items-center gap-6 min-w-0">
                        <div className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${expandedId === res.id ? 'bg-blue-600 text-white shadow-xl shadow-blue-900/40' : 'bg-gray-800 text-gray-600 group-hover:text-blue-400 group-hover:scale-110'}`}>
                          {res.fileName.endsWith('.csv') ? <FileCode className="w-6 h-6" /> : <FileSpreadsheet className="w-6 h-6" />}
                        </div>
                        <div className="min-w-0">
                          <div className="text-sm font-black text-gray-100 uppercase tracking-tight flex items-center gap-4">
                            {res.fileName}
                            {res.sheetName && (
                              <span className="text-[9px] px-3 py-1 bg-indigo-500/10 text-indigo-400 rounded-lg border border-indigo-500/20 font-black tracking-widest uppercase">{res.sheetName}</span>
                            )}
                          </div>
                          <div className="text-[11px] font-bold text-gray-500 mt-1 uppercase tracking-widest flex items-center gap-4">
                            <span>Line <span className="text-gray-300">{res.rowNumber}</span></span> 
                            <span className="w-1 h-1 rounded-full bg-gray-800" /> 
                            <span className="truncate max-w-lg text-gray-500 font-mono italic">
                              {Object.values(res.rowData).slice(0, 4).join(' • ')}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className={`p-3 rounded-full transition-all ${expandedId === res.id ? 'bg-blue-600/10 text-blue-500 rotate-180' : 'text-gray-800 bg-gray-800/40 group-hover:text-gray-400'}`}>
                        <ChevronDown className="w-5 h-5" />
                      </div>
                    </div>

                    {expandedId === res.id && (
                      <div className="px-8 pb-10 animate-in slide-in-from-top-6 duration-500">
                        <div className="h-px bg-gradient-to-r from-transparent via-gray-800 to-transparent mb-10 opacity-60" />
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-y-10 gap-x-12">
                          {Object.entries(res.rowData).map(([key, value]) => {
                            if (key.startsWith('_')) return null;
                            const strVal = String(value);
                            const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                            return (
                              <div key={key} className="space-y-3 group/item">
                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-[0.25em] group-hover/item:text-blue-500/80 transition-colors block">{key}</span>
                                <div className={`text-sm font-medium leading-relaxed p-4 rounded-2xl border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-blue-100 shadow-[inset_0_2px_10px_rgba(59,130,246,0.1)]' : 'bg-gray-900/60 border-gray-800 text-gray-400'}`}>
                                  {strVal || <span className="opacity-20 italic font-mono uppercase tracking-widest">Null</span>}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30 select-none">
              <AlertTriangle className="w-20 h-20 mb-8 text-amber-600/50" />
              <h4 className="text-3xl font-black uppercase tracking-[0.4em] text-gray-600">No Signatures Found</h4>
              <p className="text-sm font-bold mt-4 uppercase tracking-[0.2em] text-gray-500">Zero correlated objects across local memory space</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-10 select-none">
              <Zap className="w-24 h-24 mb-10 text-blue-600/50" />
              <h4 className="text-3xl font-black uppercase tracking-[0.4em] text-gray-600">Engine Standby</h4>
              <p className="text-sm font-bold mt-4 uppercase tracking-[0.2em] text-gray-500">Awaiting search sequence input...</p>
            </div>
          )}
        </div>
      </main>

      {/* Footer */}
      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-[0.3em] shrink-0 z-50">
        <div className="flex gap-10 items-center">
          <span className="flex items-center gap-3 transition-colors hover:text-blue-400"><Clock className="w-4 h-4 text-blue-500/30" /> THREAD_POOL_CORES: {MAX_WORKERS}</span>
          <div className="h-5 w-px bg-gray-800" />
          <span className="flex items-center gap-3 text-indigo-500/50"><Database className="w-4 h-4" /> VIRTUAL_RENDER_ACTIVE</span>
        </div>
        <div className="flex items-center gap-8">
          <span className="text-green-500/30 flex items-center gap-3"><ShieldCheck className="w-4 h-4" /> ZERO_UPLOAD_ENCRYPTED</span>
          <div className="h-5 w-px bg-gray-800" />
          <div className="text-gray-700 tracking-[0.1em]">
            X-SEARCH PRO // V3.5.0 // STABLE ARCHITECTURE
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  Filter,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  // Add missing ChevronRight icon import
  ChevronRight,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown,
  Columns,
  MinusCircle,
  PlusCircle,
  Settings2
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const ROW_HEIGHT = 80; // Estimated collapsed row height
const VIRTUAL_BUFFER = 5;

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [filterMode, setFilterMode] = useState<'include' | 'exclude'>('include');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportColumns, setExportColumns] = useState<string[]>([]);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Load recent searches
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  // Sync scroll and measure container
  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) {
        setContainerHeight(scrollContainerRef.current.clientHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const saveSearch = useCallback((q: string, exact: boolean) => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { query: q, timestamp: Date.now(), exactMatch: exact };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;

    setAllResults([]);
    setShowSummary(false);

    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];

    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    const searchId = ++activeSearchId.current;
    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => {
      const isIncluded = types.includes(f.type);
      return mode === 'include' ? isIncluded : !isIncluded;
    });

    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;

      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;

        if (action === 'MATCH_CHUNK') {
          setAllResults(prev => [...prev, ...payload.matches]);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };

      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: {
          fileId: file.id,
          blob: file.blob,
          type: file.type,
          name: file.name,
          path: file.path,
          query: searchTerm,
          exactMatch: exact
        }
      });
    };

    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes, filterMode);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) 
      ? selectedFileTypes.filter(t => t !== type)
      : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next, filterMode);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const availableColumns = useMemo(() => {
    const cols = new Set<string>(['FileName', 'Path', 'Sheet', 'Row']);
    allResults.slice(0, 100).forEach(r => {
      Object.keys(r.rowData).forEach(k => {
        if (!k.startsWith('_')) cols.add(k);
      });
    });
    return Array.from(cols);
  }, [allResults]);

  useEffect(() => {
    setExportColumns(availableColumns);
  }, [availableColumns]);

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  // Virtual Scrolling Calculations
  const startIdx = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
  const endIdx = Math.min(sortedResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
  const visibleItems = sortedResults.slice(startIdx, endIdx);
  const totalHeight = sortedResults.length * ROW_HEIGHT;
  const offsetY = startIdx * ROW_HEIGHT;

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    const csvContent = [
      exportColumns.join(','),
      ...allResults.map(r => {
        return exportColumns.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'Path') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_pro_export_${Date.now()}.csv`;
    link.click();
    setShowExportModal(false);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans selection:bg-blue-500/30">

      {/* Search Finished Popup */}
      {showSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-blue-900/40">
                <CheckCircle2 className="w-8 h-8 text-white" />
              </div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Search Complete</h2>
              <p className="text-gray-400 text-sm mb-6">
