                    >
                      {s.query} <ChevronRight className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-all" />
                    </button>
                  ))}
                  <button onClick={() => { setRecentSearches([]); localStorage.removeItem('xsearch_pro_v2_history'); }} className="text-[10px] font-bold text-red-500/40 hover:text-red-500 px-3">Clear</button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div 
          ref={scrollContainerRef}
          onScroll={handleScroll}
          className="flex-1 overflow-auto bg-gray-950 px-6 py-8 relative scroll-smooth"
        >
          {files.length === 0 ? (
