          <div className="text-gray-700">X-SEARCH PRO // V3.6.0 // STABLE</div>
        </div>
      </footer>
    </div>
  );
};

export default App;

/**
 * X-Search Pro Background Worker (Ultra-Performance Edition)
 * Optimized with lazy allocation and primitive loops for maximum throughput.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  const CHUNK_SIZE = 100; // Increased chunk size for higher throughput
  const MAX_FIELD_LENGTH = 1000;

  self.onmessage = async function(e) {
    const { action, payload } = e.data;
    if (action === 'PROCESS_FILE') {
      await processFile(payload);
    }
  };

  function truncate(val) {
    if (typeof val === 'string' && val.length > MAX_FIELD_LENGTH) {
      return val.substring(0, MAX_FIELD_LENGTH) + "...";
    }
    return val;
  }

  async function processFile({ fileId, blob, type, name, path, query, exactMatch }) {
    try {
      const lowerQuery = query ? query.toLowerCase() : "";
      const isQueryEmpty = !lowerQuery;
      let matches = [];
      let totalRowsInFile = 0;

      const onRowProcessed = (row, sheetName = null) => {
        totalRowsInFile++;

        let isMatch = isQueryEmpty;

        // Optimized First Pass: Check for match without allocating objects
        if (!isMatch) {
          for (const key in row) {
            const val = row[key];
            if (val == null || val === "") continue;

            const strVal = String(val).toLowerCase();
            if (exactMatch) {
              if (strVal === lowerQuery) {
                isMatch = true;
                break;
              }
            } else {
              if (strVal.indexOf(lowerQuery) !== -1) {
                isMatch = true;
                break;
              }
            }
          }
        }

        // Lazy allocation: Only build structured data if it's a hit
        if (isMatch) {
          const cleanRow = {};
          let searchPreview = "";
          let previewCount = 0;

          for (const key in row) {
            const truncatedVal = truncate(row[key]);
            cleanRow[key] = truncatedVal;
            if (previewCount < 4 && truncatedVal) {
              searchPreview += (searchPreview ? " • " : "") + String(truncatedVal);
              previewCount++;
            }
          }

          matches.push({
            id: \`\${fileId}-\${sheetName || 'default'}-\${totalRowsInFile}\`,
            fileName: name,
            filePath: path,
            sheetName: sheetName,
            rowNumber: totalRowsInFile + 1,
            rowData: cleanRow,
            searchString: searchPreview
          });

          if (matches.length >= CHUNK_SIZE) {
            self.postMessage({ action: 'MATCH_CHUNK', payload: { fileId, matches } });
            matches = [];
          }
        }
      };

      if (type === 'xlsx' || type === 'xls') {
        const buffer = await blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { 
          type: 'array', 
          cellDates: true, 
          cellFormula: false, 
          cellText: false,
          cellNF: false,
          cellHTML: false
        });

        for (let i = 0; i < workbook.SheetNames.length; i++) {
          const sheetName = workbook.SheetNames[i];
          const sheet = workbook.Sheets[sheetName];
          if (!sheet) continue;
          const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });
          for (let j = 0; j < jsonData.length; j++) {
            onRowProcessed(jsonData[j], sheetName);
          }
        }
      } else if (type === 'csv') {
        const text = await blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });
        const data = parsed.data;
        for (let i = 0; i < data.length; i++) {
          onRowProcessed(data[i]);
        }
      } else if (type === 'txt') {
        const text = await blob.text();
        const lines = text.split(/\\r?\\n/);
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].trim()) {
            onRowProcessed({ content: lines[i].trim() });
          }
        }
      }

      if (matches.length > 0) {
        self.postMessage({ action: 'MATCH_CHUNK', payload: { fileId, matches } });
      }

      self.postMessage({ action: 'FILE_COMPLETE', payload: { fileId, totalRows: totalRowsInFile } });

    } catch (err) {
      self.postMessage({ action: 'FILE_ERROR', payload: { fileId, error: err.message } });
    }
  }
`;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  FileText, 
  Loader2, 
  Clock, 
  Database,
  Filter,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  ChevronRight,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown,
  PlusCircle,
  MinusCircle,
  Hash,
  TableProperties
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const ROW_HEIGHT = 80; 
const VIRTUAL_BUFFER = 10;
const BATCH_FLUSH_INTERVAL = 150; // Throttling UI updates to 150ms

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [filterMode, setFilterMode] = useState<'include' | 'exclude'>('include');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Throttling Buffer
  const resultsBuffer = useRef<SearchResult[]>([]);
  const flushTimeout = useRef<number | null>(null);

  const flushResults = useCallback(() => {
    if (resultsBuffer.current.length > 0) {
      const newItems = [...resultsBuffer.current];
      resultsBuffer.current = [];
      setAllResults(prev => [...prev, ...newItems]);
    }
    flushTimeout.current = null;
  }, []);

  const queueResults = useCallback((items: SearchResult[]) => {
    resultsBuffer.current.push(...items);
    if (!flushTimeout.current) {
      flushTimeout.current = window.setTimeout(flushResults, BATCH_FLUSH_INTERVAL);
    }
  }, [flushResults]);

  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_v2_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) {
        setContainerHeight(scrollContainerRef.current.clientHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const saveSearch = useCallback((q: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { 
        query: q, 
        timestamp: Date.now(), 
        exactMatch: exact,
        selectedFileTypes: types,
        filterMode: mode
      };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_v2_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;
    setAllResults([]);
    resultsBuffer.current = [];
    setShowSummary(false);
    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];
    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    const searchId = ++activeSearchId.current;

    // Clear state and buffer
    if (flushTimeout.current) window.clearTimeout(flushTimeout.current);
    flushTimeout.current = null;
    resultsBuffer.current = [];

    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => {
      const isIncluded = types.includes(f.type);
      return mode === 'include' ? isIncluded : !isIncluded;
    });

    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact, types, mode);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;
      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;
        if (action === 'MATCH_CHUNK') {
          queueResults(payload.matches);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            flushResults();
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };
      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: { fileId: file.id, blob: file.blob, type: file.type, name: file.name, path: file.path, query: searchTerm, exactMatch: exact }
      });
    };
    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch, queueResults, flushResults]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes, filterMode);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) ? selectedFileTypes.filter(t => t !== type) : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next, filterMode);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';
      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();
      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  const startIdx = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
  const endIdx = Math.min(sortedResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
  const visibleItems = sortedResults.slice(startIdx, endIdx);
  const totalHeight = sortedResults.length * ROW_HEIGHT;
  const offsetY = startIdx * ROW_HEIGHT;

  const exportToCSV = () => {
    if (allResults.length === 0) return;
    const allHeadersSet = new Set<string>(['FileName', 'FilePath', 'Sheet', 'Row']);
    allResults.forEach(r => {
      for (const k in r.rowData) {
        if (!k.startsWith('_')) allHeadersSet.add(k);
      }
    });
    const headers = Array.from(allHeadersSet);

    const csvContent = [
      headers.join(','),
      ...allResults.map(r => {
        return headers.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'FilePath') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_full_export_${Date.now()}.csv`;
    link.click();
  };

  const handleRecentClick = (s: RecentSearch) => {
    setQuery(s.query);
    setExactMatch(s.exactMatch);
    setSelectedFileTypes(s.selectedFileTypes);
    setFilterMode(s.filterMode);
    performSearch(s.query, s.exactMatch, s.selectedFileTypes, s.filterMode);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans selection:bg-blue-500/30">
      {showSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-blue-900/40">
                <CheckCircle2 className="w-8 h-8 text-white" />
              </div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Search Finished</h2>
              <p className="text-gray-400 text-sm mb-6">
                Found <span className="text-white font-bold">{allResults.length.toLocaleString()}</span> hits across <span className="text-white font-bold">{searchProgress.total}</span> files in <span className="text-white font-bold">{((Date.now() - startTime.current) / 1000).toFixed(2)}s</span>.
              </p>
              <button onClick={() => setShowSummary(false)} className="w-full py-3 bg-blue-600 hover:bg-blue-500 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Continue</button>
            </div>
          </div>
        </div>
      )}

      <header className="px-6 py-4 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2.5 rounded-2xl shadow-lg">
            <Zap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white uppercase">X-SEARCH <span className="text-blue-500">PRO</span></h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-[0.2em] mt-0.5">
              <ShieldCheck className="w-3 h-3 text-green-500" /> Secure Local Engine
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-7 py-3 rounded-2xl font-black text-xs shadow-xl shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'MOUNT NEW SOURCE' : 'MOUNT FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0">
        <div className="px-6 py-8 bg-gray-900/30 border-b border-gray-800/50 shrink-0">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-6 items-start">
              <div className="relative flex-1 group">
                <Search className={`absolute left-6 top-[26px] -translate-y-1/2 w-6 h-6 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Querying ${files.length.toLocaleString()} files locally...` : "Choose a source folder to begin..."}
                  className="w-full bg-gray-800/40 border border-gray-700/50 rounded-[28px] py-6 pl-16 pr-8 text-lg text-white placeholder-gray-600 focus:outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500/50 transition-all shadow-2xl"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-6 top-1/2 -translate-y-1/2 flex items-center gap-4 bg-gray-900/90 px-4 py-2 rounded-xl border border-gray-700">
                    <span className="text-xs font-black text-blue-500 uppercase tracking-widest">{Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%</span>
                    <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex flex-col gap-3 shrink-0">
                <div className="flex items-center gap-2 bg-gray-800/40 border border-gray-700/50 rounded-2xl p-2 pr-4 shadow-lg">
                  <button 
                    onClick={() => { const nm = filterMode === 'include' ? 'exclude' : 'include'; setFilterMode(nm); performSearch(query, exactMatch, selectedFileTypes, nm); }}
                    className={`p-2 rounded-xl transition-all flex items-center gap-2 px-3 ${filterMode === 'include' ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'}`}
                  >
                    {filterMode === 'include' ? <PlusCircle className="w-4 h-4" /> : <MinusCircle className="w-4 h-4" />}
                    <span className="text-[10px] font-black uppercase">{filterMode}</span>
                  </button>
                  <div className="w-px h-6 bg-gray-700 mx-1" />
                  <div className="flex items-center gap-1">
                    {['xlsx', 'csv', 'txt'].map(type => (
                      <button
                        key={type}
                        onClick={() => toggleFileType(type)}
                        className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-500 hover:text-gray-300'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => { setExactMatch(!exactMatch); performSearch(query, !exactMatch, selectedFileTypes, filterMode); }}
                  className={`flex items-center gap-3 text-[11px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MATCH
                </button>
                <div className="h-6 w-px bg-gray-800" />
                <div className="flex items-center gap-4 text-[11px] font-black text-gray-500">
                  <span className="flex items-center gap-2 uppercase tracking-widest"><ArrowUpDown className="w-4 h-4" /> Sort By:</span>
                  <div className="flex gap-2">
                    {['relevance', 'fileName', 'rowNumber'].map(key => (
                      <button 
                        key={key}
                        onClick={() => handleSort(key)}
                        className={`px-3 py-1.5 rounded-lg border transition-all uppercase ${sortConfig.key === key ? 'bg-blue-500/10 border-blue-500/50 text-blue-400 shadow-md' : 'bg-gray-800/30 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                      >
                        {key === 'rowNumber' ? 'Row' : key === 'fileName' ? 'File' : 'Rel.'}
                        {sortConfig.key === key && (sortConfig.direction === 'asc' ? <ArrowUp className="inline w-3 h-3 ml-1" /> : <ArrowDown className="inline w-3 h-3 ml-1" />)}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4">
                  <button 
                    onClick={exportToCSV}
                    className="flex items-center gap-3 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl text-[11px] font-black uppercase shadow-lg shadow-indigo-900/20 transition-all"
                  >
                    <Download className="w-4 h-4" />
                    Export All Results
                  </button>
                </div>
              )}
            </div>

            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-4 animate-in fade-in slide-in-from-top-2">
                <div className="flex items-center gap-2 text-[10px] font-black text-gray-600 uppercase tracking-widest">
                  <History className="w-4 h-4" /> RECENT
                </div>
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => handleRecentClick(s)}
                      className="text-[10px] font-bold text-gray-500 hover:text-white bg-gray-800/30 px-4 py-2 rounded-xl border border-gray-800 hover:bg-gray-800 transition-all flex items-center gap-2 group"
                    >
                      {s.query} <ChevronRight className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-all" />
                    </button>
                  ))}
                  <button onClick={() => { setRecentSearches([]); localStorage.removeItem('xsearch_pro_v2_history'); }} className="text-[10px] font-bold text-red-500/40 hover:text-red-500 px-3">Clear</button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div 
          ref={scrollContainerRef}
          onScroll={handleScroll}
          className="flex-1 overflow-auto bg-gray-950 px-6 py-8 relative scroll-smooth"
        >
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-[0.05] grayscale">
              <Database className="w-32 h-32 mb-8" />
              <h3 className="text-4xl font-black uppercase tracking-[0.5em]">Indexer Idle</h3>
              <p className="text-lg font-bold mt-2 uppercase tracking-[0.2em]">Mount a source to initialize scanning</p>
            </div>
          ) : sortedResults.length > 0 ? (
            <div className="max-w-7xl mx-auto relative" style={{ height: totalHeight }}>
              <div style={{ transform: `translateY(${offsetY}px)` }} className="space-y-4">
                {visibleItems.map((res) => (
                  <div 
                    key={res.id} 
                    className={`group bg-gray-900/40 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/60 rounded-[32px] shadow-2xl bg-gray-900/95 ring-1 ring-blue-500/20' : 'border-gray-800/40 rounded-2xl hover:border-gray-700/80 hover:bg-gray-900/60'}`}
                    style={{ height: expandedId === res.id ? 'auto' : ROW_HEIGHT - 16 }}
                  >
                    <div 
                      className="p-5 flex items-center justify-between cursor-pointer"
                      onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                    >
                      <div className="flex items-center gap-6 min-w-0">
                        <div className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${expandedId === res.id ? 'bg-blue-600 text-white shadow-xl' : 'bg-gray-800 text-gray-600 group-hover:text-blue-400 group-hover:scale-105'}`}>
                          {res.fileName.endsWith('.csv') ? <FileCode className="w-6 h-6" /> : <FileSpreadsheet className="w-6 h-6" />}
                        </div>
                        <div className="min-w-0">
                          <div className="text-sm font-black text-gray-100 uppercase tracking-tight flex items-center gap-4">
                            {res.fileName}
                            {res.sheetName && (
                              <span className="text-[9px] px-2.5 py-1 bg-blue-500/10 text-blue-400 rounded-lg border border-blue-500/20 font-black tracking-widest">{res.sheetName}</span>
                            )}
                          </div>
                          <div className="text-[11px] font-bold text-gray-500 mt-1 uppercase tracking-widest flex items-center gap-4">
                            <span>Row <span className="text-gray-300">{res.rowNumber}</span></span> 
                            <span className="w-1 h-1 rounded-full bg-gray-800" /> 
                            <span className="truncate max-w-lg text-gray-500 font-mono italic">
                              {res.searchString}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className={`p-2 rounded-full transition-all ${expandedId === res.id ? 'bg-blue-600/10 text-blue-500 rotate-180' : 'text-gray-700'}`}>
                        <ChevronDown className="w-5 h-5" />
                      </div>
                    </div>

                    {expandedId === res.id && (
                      <div className="px-8 pb-10 animate-in slide-in-from-top-4 duration-300">
                        <div className="h-px bg-gradient-to-r from-transparent via-gray-800 to-transparent mb-8" />
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-y-8 gap-x-12">
                          <div className="col-span-full mb-2">
                            <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em] flex items-center gap-2">
                              <TableProperties className="w-3.5 h-3.5" /> Full Row Attributes
                            </h4>
                          </div>
                          {Object.entries(res.rowData).map(([key, value]) => {
                            if (key.startsWith('_')) return null;
                            const strVal = String(value);
                            const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                            return (
                              <div key={key} className="space-y-2 group/item">
                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-widest group-hover/item:text-blue-400 transition-colors cursor-pointer" onClick={(e) => { e.stopPropagation(); handleSort(key); }}>
                                  {key}
                                </span>
                                <div className={`text-sm font-medium leading-relaxed p-4 rounded-2xl border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-blue-50 shadow-inner' : 'bg-gray-900/60 border-gray-800 text-gray-400'}`}>
                                  {strVal || <span className="opacity-20 italic">Empty</span>}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30 select-none">
              <AlertTriangle className="w-20 h-20 mb-8 text-amber-600" />
              <h4 className="text-3xl font-black uppercase tracking-[0.4em] text-gray-600">Zero Correlated Data</h4>
              <p className="text-sm font-bold mt-2 uppercase tracking-[0.2em] text-gray-500">The query signature did not return any local objects</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-10 select-none">
              <Zap className="w-24 h-24 mb-10 text-blue-600" />
              <h4 className="text-3xl font-black uppercase tracking-[0.5em] text-gray-600">Engine Standby</h4>
              <p className="text-sm font-bold mt-2 uppercase tracking-[0.2em] text-gray-500">Scanning logic offline // Awaiting input sequence</p>
            </div>
          )}
        </div>
      </main>

      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-[0.3em] shrink-0 z-50">
        <div className="flex gap-10 items-center">
          <span className="flex items-center gap-3"><Clock className="w-4 h-4 text-blue-500/30" /> CORES_ACTIVE: {MAX_WORKERS}</span>
          <div className="h-5 w-px bg-gray-800" />
          <span className="flex items-center gap-3 text-indigo-500/50"><Hash className="w-4 h-4" /> VIRTUAL_PIPELINE: ENABLED</span>
        </div>
        <div className="flex items-center gap-8">
          <span className="text-green-500/30 flex items-center gap-3"><ShieldCheck className="w-4 h-4" /> LOCAL_ONLY</span>
          <div className="h-5 w-px bg-gray-800" />
          <div className="text-gray-700">X-SEARCH PRO // V3.7.0 // OPTIMIZED BUILD</div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  Loader2, 
  Clock, 
  Database,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  ChevronRight,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown,
  PlusCircle,
  MinusCircle,
  Hash,
  TableProperties,
  Columns,
  Check
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const ROW_HEIGHT = 80; 
const VIRTUAL_BUFFER = 10;
const BATCH_FLUSH_INTERVAL = 150; 

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [filterMode, setFilterMode] = useState<'include' | 'exclude'>('include');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [selectedExportColumns, setSelectedExportColumns] = useState<string[]>([]);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const resultsBuffer = useRef<SearchResult[]>([]);
  const flushTimeout = useRef<number | null>(null);

  const flushResults = useCallback(() => {
    if (resultsBuffer.current.length > 0) {
      const newItems = [...resultsBuffer.current];
      resultsBuffer.current = [];
      setAllResults(prev => [...prev, ...newItems]);
    }
    flushTimeout.current = null;
  }, []);

  const queueResults = useCallback((items: SearchResult[]) => {
    resultsBuffer.current.push(...items);
    if (!flushTimeout.current) {
      flushTimeout.current = window.setTimeout(flushResults, BATCH_FLUSH_INTERVAL);
    }
  }, [flushResults]);

  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_v2_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) {
        setContainerHeight(scrollContainerRef.current.clientHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const saveSearch = useCallback((q: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { 
        query: q, 
        timestamp: Date.now(), 
        exactMatch: exact,
        selectedFileTypes: types,
        filterMode: mode
      };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_v2_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  // Dynamically calculate available columns from results for the export modal
  const availableColumns = useMemo(() => {
    const cols = new Set<string>(['FileName', 'FilePath', 'Sheet', 'Row']);
    // Samples 500 results to find headers
    allResults.slice(0, 500).forEach(r => {
      for (const k in r.rowData) {
        if (!k.startsWith('_')) cols.add(k);
      }
    });
    return Array.from(cols);
  }, [allResults]);

  useEffect(() => {
    if (showExportModal) {
      setSelectedExportColumns(availableColumns);
    }
  }, [showExportModal, availableColumns]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;
    setAllResults([]);
    resultsBuffer.current = [];
    setShowSummary(false);
    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];
    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    const searchId = ++activeSearchId.current;
    if (flushTimeout.current) window.clearTimeout(flushTimeout.current);
    flushTimeout.current = null;
    resultsBuffer.current = [];

    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => {
      const isIncluded = types.includes(f.type);
      return mode === 'include' ? isIncluded : !isIncluded;
    });

    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact, types, mode);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;
      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;
        if (action === 'MATCH_CHUNK') {
          queueResults(payload.matches);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            flushResults();
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };
      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: { fileId: file.id, blob: file.blob, type: file.type, name: file.name, path: file.path, query: searchTerm, exactMatch: exact }
      });
    };
    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch, queueResults, flushResults]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes, filterMode);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) ? selectedFileTypes.filter(t => t !== type) : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next, filterMode);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';
      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();
      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  const startIdx = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
  const endIdx = Math.min(sortedResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
  const visibleItems = sortedResults.slice(startIdx, endIdx);
  const totalHeight = sortedResults.length * ROW_HEIGHT;
  const offsetY = startIdx * ROW_HEIGHT;

  const exportToCSV = () => {
    if (allResults.length === 0 || selectedExportColumns.length === 0) return;

    const csvContent = [
      selectedExportColumns.join(','),
      ...allResults.map(r => {
        return selectedExportColumns.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'FilePath') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_custom_export_${Date.now()}.csv`;
    link.click();
    setShowExportModal(false);
  };

  const handleRecentClick = (s: RecentSearch) => {
    setQuery(s.query);
    setExactMatch(s.exactMatch);
    setSelectedFileTypes(s.selectedFileTypes);
    setFilterMode(s.filterMode);
    performSearch(s.query, s.exactMatch, s.selectedFileTypes, s.filterMode);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans selection:bg-blue-500/30">

      {/* Export Configuration Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
          <div className="bg-gray-900 border border-gray-800 rounded-[40px] p-8 max-w-4xl w-full shadow-2xl overflow-hidden flex flex-col max-h-[85vh]">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-500/10 rounded-2xl border border-indigo-500/20 text-indigo-400">
                  <Columns className="w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-2xl font-black uppercase tracking-tight">Export Schema</h2>
                  <p className="text-gray-500 text-xs font-bold uppercase tracking-widest mt-1">Select columns to include in CSV</p>
                </div>
              </div>
              <button onClick={() => setShowExportModal(false)} className="p-3 bg-gray-800/50 hover:bg-red-500/10 text-gray-500 hover:text-red-400 rounded-full transition-all">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-1 space-y-2 mb-8 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3 auto-rows-min">
              {availableColumns.map(col => {
                const isSelected = selectedExportColumns.includes(col);
                // Highlight important columns as mentioned in prompt
                const isImportant = ['Amount', 'Date', 'Nature', 'Debit', 'Credit'].some(imp => col.toLowerCase().includes(imp.toLowerCase()));

                return (
                  <button
                    key={col}
                    onClick={() => setSelectedExportColumns(prev => 
                      isSelected ? prev.filter(c => c !== col) : [...prev, col]
                    )}
                    className={`flex items-center justify-between px-5 py-3.5 rounded-2xl border transition-all text-[11px] font-black uppercase tracking-tight ${isSelected ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-300' : 'bg-gray-800/30 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                  >
                    <span className="flex items-center gap-2 truncate">
                      {isImportant && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />}
                      {col}
                    </span>
                    <div className={`w-5 h-5 rounded-lg border flex items-center justify-center transition-all ${isSelected ? 'bg-indigo-600 border-indigo-500 text-white' : 'border-gray-700 bg-gray-900/50'}`}>
                      {isSelected && <Check className="w-3.5 h-3.5" />}
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="flex gap-4 shrink-0">
              <button onClick={() => setSelectedExportColumns([])} className="flex-1 py-4 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Clear Selection</button>
              <button onClick={() => setSelectedExportColumns(availableColumns)} className="flex-1 py-4 bg-gray-800 hover:bg-gray-700 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Select All (*)</button>
              <button 
                onClick={exportToCSV} 
                disabled={selectedExportColumns.length === 0}
                className="flex-[2] py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl shadow-indigo-900/40"
              >
                Generate CSV Export
              </button>
            </div>
          </div>
        </div>
      )}

      {showSummary && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[32px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-blue-900/40">
                <CheckCircle2 className="w-8 h-8 text-white" />
              </div>
              <h2 className="text-xl font-black uppercase tracking-widest mb-2">Scan Finished</h2>
              <p className="text-gray-400 text-sm mb-6">
                Found <span className="text-white font-bold">{allResults.length.toLocaleString()}</span> hits across <span className="text-white font-bold">{searchProgress.total}</span> files in <span className="text-white font-bold">{((Date.now() - startTime.current) / 1000).toFixed(2)}s</span>.
              </p>
              <button onClick={() => setShowSummary(false)} className="w-full py-3 bg-blue-600 hover:bg-blue-500 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Continue</button>
            </div>
          </div>
        </div>
      )}

      <header className="px-6 py-4 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2.5 rounded-2xl shadow-lg">
            <Zap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white uppercase">X-SEARCH <span className="text-blue-500">PRO</span></h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-[0.2em] mt-0.5">
              <ShieldCheck className="w-3 h-3 text-green-500" /> Secure Local Engine
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-7 py-3 rounded-2xl font-black text-xs shadow-xl shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'MOUNT NEW SOURCE' : 'MOUNT FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0">
        <div className="px-6 py-8 bg-gray-900/30 border-b border-gray-800/50 shrink-0">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-6 items-start">
              <div className="relative flex-1 group">
                <Search className={`absolute left-6 top-[26px] -translate-y-1/2 w-6 h-6 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? `Querying ${files.length.toLocaleString()} files locally...` : "Choose a source folder to begin..."}
                  className="w-full bg-gray-800/40 border border-gray-700/50 rounded-[28px] py-6 pl-16 pr-8 text-lg text-white placeholder-gray-600 focus:outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500/50 transition-all shadow-2xl"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-6 top-1/2 -translate-y-1/2 flex items-center gap-4 bg-gray-900/90 px-4 py-2 rounded-xl border border-gray-700">
                    <span className="text-xs font-black text-blue-500 uppercase tracking-widest">{Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%</span>
                    <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>

              <div className="flex flex-col gap-3 shrink-0">
                <div className="flex items-center gap-2 bg-gray-800/40 border border-gray-700/50 rounded-2xl p-2 pr-4 shadow-lg">
                  <button 
                    onClick={() => { const nm = filterMode === 'include' ? 'exclude' : 'include'; setFilterMode(nm); performSearch(query, exactMatch, selectedFileTypes, nm); }}
                    className={`p-2 rounded-xl transition-all flex items-center gap-2 px-3 ${filterMode === 'include' ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'}`}
                  >
                    {filterMode === 'include' ? <PlusCircle className="w-4 h-4" /> : <MinusCircle className="w-4 h-4" />}
                    <span className="text-[10px] font-black uppercase">{filterMode}</span>
                  </button>
                  <div className="w-px h-6 bg-gray-700 mx-1" />
                  <div className="flex items-center gap-1">
                    {['xlsx', 'csv', 'txt'].map(type => (
                      <button
                        key={type}
                        onClick={() => toggleFileType(type)}
                        className={`px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${selectedFileTypes.includes(type) ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-500 hover:text-gray-300'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => { setExactMatch(!exactMatch); performSearch(query, !exactMatch, selectedFileTypes, filterMode); }}
                  className={`flex items-center gap-3 text-[11px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600 hover:text-gray-400'}`}
                  disabled={files.length === 0}
                >
                  <div className={`w-10 h-5 rounded-full relative transition-all ${exactMatch ? 'bg-blue-600' : 'bg-gray-800'}`}>
                    <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${exactMatch ? 'translate-x-5' : ''}`} />
                  </div>
                  STRICT MATCH
                </button>
                <div className="h-6 w-px bg-gray-800" />
                <div className="flex items-center gap-4 text-[11px] font-black text-gray-500">
                  <span className="flex items-center gap-2 uppercase tracking-widest"><ArrowUpDown className="w-4 h-4" /> Sort By:</span>
                  <div className="flex gap-2">
                    {['relevance', 'fileName', 'rowNumber'].map(key => (
                      <button 
                        key={key}
                        onClick={() => handleSort(key)}
                        className={`px-3 py-1.5 rounded-lg border transition-all uppercase ${sortConfig.key === key ? 'bg-blue-500/10 border-blue-500/50 text-blue-400 shadow-md' : 'bg-gray-800/30 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                      >
                        {key === 'rowNumber' ? 'Row' : key === 'fileName' ? 'File' : 'Rel.'}
                        {sortConfig.key === key && (sortConfig.direction === 'asc' ? <ArrowUp className="inline w-3 h-3 ml-1" /> : <ArrowDown className="inline w-3 h-3 ml-1" />)}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4">
                  <button 
                    onClick={() => setShowExportModal(true)}
                    className="flex items-center gap-3 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl text-[11px] font-black uppercase shadow-lg shadow-indigo-900/20 transition-all active:scale-95"
                  >
                    <Download className="w-4 h-4" />
                    Configure CSV Export
                  </button>
                </div>
              )}
            </div>

            {recentSearches.length > 0 && !query && (
              <div className="flex items-center gap-4 animate-in fade-in slide-in-from-top-2">
                <div className="flex items-center gap-2 text-[10px] font-black text-gray-600 uppercase tracking-widest">
                  <History className="w-4 h-4" /> RECENT
                </div>
                <div className="flex flex-wrap gap-2">
                  {recentSearches.map((s, i) => (
                    <button
                      key={i}
                      onClick={() => handleRecentClick(s)}
                      className="text-[10px] font-bold text-gray-500 hover:text-white bg-gray-800/30 px-4 py-2 rounded-xl border border-gray-800 hover:bg-gray-800 transition-all flex items-center gap-2 group"
                    >
                      {s.query} <ChevronRight className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-all" />
                    </button>
                  ))}
                  <button onClick={() => { setRecentSearches([]); localStorage.removeItem('xsearch_pro_v2_history'); }} className="text-[10px] font-bold text-red-500/40 hover:text-red-500 px-3">Clear History</button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div 
          ref={scrollContainerRef}
          onScroll={handleScroll}
          className="flex-1 overflow-auto bg-gray-950 px-6 py-8 relative scroll-smooth"
        >
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-[0.05] grayscale">
              <Database className="w-32 h-32 mb-8" />
              <h3 className="text-4xl font-black uppercase tracking-[0.5em]">Indexer Idle</h3>
              <p className="text-lg font-bold mt-2 uppercase tracking-[0.2em]">Mount a source to initialize scanning</p>
            </div>
          ) : sortedResults.length > 0 ? (
            <div className="max-w-7xl mx-auto relative" style={{ height: totalHeight }}>
              <div style={{ transform: `translateY(${offsetY}px)` }} className="space-y-4">
                {visibleItems.map((res) => (
                  <div 
                    key={res.id} 
                    className={`group bg-gray-900/40 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/60 rounded-[32px] shadow-2xl bg-gray-900/95 ring-1 ring-blue-500/20' : 'border-gray-800/40 rounded-2xl hover:border-gray-700/80 hover:bg-gray-900/60'}`}
                    style={{ height: expandedId === res.id ? 'auto' : ROW_HEIGHT - 16 }}
                  >
                    <div 
                      className="p-5 flex items-center justify-between cursor-pointer"
                      onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                    >
                      <div className="flex items-center gap-6 min-w-0">
                        <div className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${expandedId === res.id ? 'bg-blue-600 text-white shadow-xl' : 'bg-gray-800 text-gray-600 group-hover:text-blue-400 group-hover:scale-105'}`}>
                          {res.fileName.endsWith('.csv') ? <FileCode className="w-6 h-6" /> : <FileSpreadsheet className="w-6 h-6" />}
                        </div>
                        <div className="min-w-0">
                          <div className="text-sm font-black text-gray-100 uppercase tracking-tight flex items-center gap-4">
                            {res.fileName}
                            {res.sheetName && (
                              <span className="text-[9px] px-2.5 py-1 bg-blue-500/10 text-blue-400 rounded-lg border border-blue-500/20 font-black tracking-widest">{res.sheetName}</span>
                            )}
                          </div>
                          <div className="text-[11px] font-bold text-gray-500 mt-1 uppercase tracking-widest flex items-center gap-4">
                            <span>Row <span className="text-gray-300">{res.rowNumber}</span></span> 
                            <span className="w-1 h-1 rounded-full bg-gray-800" /> 
                            <span className="truncate max-w-lg text-gray-500 font-mono italic">
                              {res.searchString}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className={`p-2 rounded-full transition-all ${expandedId === res.id ? 'bg-blue-600/10 text-blue-500 rotate-180' : 'text-gray-700'}`}>
                        <ChevronDown className="w-5 h-5" />
                      </div>
                    </div>

                    {expandedId === res.id && (
                      <div className="px-8 pb-10 animate-in slide-in-from-top-4 duration-300">
                        <div className="h-px bg-gradient-to-r from-transparent via-gray-800 to-transparent mb-8" />
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-y-8 gap-x-12">
                          <div className="col-span-full mb-2">
                            <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em] flex items-center gap-2">
                              <TableProperties className="w-3.5 h-3.5" /> Full Row Attributes
                            </h4>
                          </div>
                          {Object.entries(res.rowData).map(([key, value]) => {
                            if (key.startsWith('_')) return null;
                            const strVal = String(value);
                            const isMatch = query && strVal.toLowerCase().includes(query.toLowerCase());
                            return (
                              <div key={key} className="space-y-2 group/item">
                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-widest group-hover/item:text-blue-400 transition-colors cursor-pointer" onClick={(e) => { e.stopPropagation(); handleSort(key); }}>
                                  {key}
                                </span>
                                <div className={`text-sm font-medium leading-relaxed p-4 rounded-2xl border transition-all ${isMatch ? 'bg-blue-600/10 border-blue-500/40 text-blue-50 shadow-inner' : 'bg-gray-900/60 border-gray-800 text-gray-400'}`}>
                                  {strVal || <span className="opacity-20 italic font-mono uppercase tracking-widest">Null</span>}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-30 select-none">
              <AlertTriangle className="w-20 h-20 mb-8 text-amber-600" />
              <h4 className="text-3xl font-black uppercase tracking-[0.4em] text-gray-600">Zero Correlated Data</h4>
              <p className="text-sm font-bold mt-2 uppercase tracking-[0.2em] text-gray-500">The query signature did not return any local objects</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-10 select-none">
              <Zap className="w-24 h-24 mb-10 text-blue-600" />
              <h4 className="text-3xl font-black uppercase tracking-[0.5em] text-gray-600">Engine Standby</h4>
              <p className="text-sm font-bold mt-2 uppercase tracking-[0.2em] text-gray-500">Scanning logic offline // Awaiting input sequence</p>
            </div>
          )}
        </div>
      </main>

      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[10px] font-black text-gray-600 uppercase tracking-[0.3em] shrink-0 z-50">
        <div className="flex gap-10 items-center">
          <span className="flex items-center gap-3"><Clock className="w-4 h-4 text-blue-500/30" /> CORES_ACTIVE: {MAX_WORKERS}</span>
          <div className="h-5 w-px bg-gray-800" />
          <span className="flex items-center gap-3 text-indigo-500/50"><Hash className="w-4 h-4" /> VIRTUAL_PIPELINE: ENABLED</span>
        </div>
        <div className="flex items-center gap-8">
          <span className="text-green-500/30 flex items-center gap-3"><ShieldCheck className="w-4 h-4" /> LOCAL_ONLY</span>
          <div className="h-5 w-px bg-gray-800" />
          <div className="text-gray-700">X-SEARCH PRO // V3.8.0 // HIGH-SPEED ARCHITECTURE</div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  Loader2, 
  Clock, 
  Database,
  Download,
  Zap,
  AlertTriangle,
  History,
  ChevronDown,
  ChevronRight,
  ArrowUpDown,
  CheckCircle2,
  X,
  FileSpreadsheet,
  FileCode,
  ArrowUp,
  ArrowDown,
  PlusCircle,
  MinusCircle,
  Hash,
  TableProperties,
  Columns,
  Check,
  LayoutGrid,
  ListFilter
} from 'lucide-react';
import { SearchResult, RecentSearch } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const ROW_HEIGHT = 80; 
const VIRTUAL_BUFFER = 10;
const BATCH_FLUSH_INTERVAL = 150; 

const IMPORTANT_KEYWORDS = ['amount', 'date', 'nature', 'debit', 'credit', 'ref', 'balance', 'description', 'particulars'];

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [filterMode, setFilterMode] = useState<'include' | 'exclude'>('include');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [selectedExportColumns, setSelectedExportColumns] = useState<string[]>([]);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0 });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const resultsBuffer = useRef<SearchResult[]>([]);
  const flushTimeout = useRef<number | null>(null);

  const flushResults = useCallback(() => {
    if (resultsBuffer.current.length > 0) {
      const newItems = [...resultsBuffer.current];
      resultsBuffer.current = [];
      setAllResults(prev => [...prev, ...newItems]);
    }
    flushTimeout.current = null;
  }, []);

  const queueResults = useCallback((items: SearchResult[]) => {
    resultsBuffer.current.push(...items);
    if (!flushTimeout.current) {
      flushTimeout.current = window.setTimeout(flushResults, BATCH_FLUSH_INTERVAL);
    }
  }, [flushResults]);

  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_v2_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) {
        setContainerHeight(scrollContainerRef.current.clientHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const saveSearch = useCallback((q: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    if (!q.trim()) return;
    setRecentSearches(prev => {
      const newSearch: RecentSearch = { 
        query: q, 
        timestamp: Date.now(), 
        exactMatch: exact,
        selectedFileTypes: types,
        filterMode: mode
      };
      const filtered = prev.filter(s => s.query !== q);
      const updated = [newSearch, ...filtered].slice(0, 10);
      localStorage.setItem('xsearch_pro_v2_history', JSON.stringify(updated));
      return updated;
    });
  }, []);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  // Comprehensive column header extraction
  const availableColumns = useMemo(() => {
    const standardHeaders = ['FileName', 'FilePath', 'Sheet', 'Row'];
    const dynamicHeaders = new Set<string>();

    // Sample a larger chunk for heterogeneous data files
    allResults.slice(0, 1000).forEach(r => {
      for (const k in r.rowData) {
        if (!k.startsWith('_')) dynamicHeaders.add(k);
      }
    });

    const sortedDynamics = Array.from(dynamicHeaders).sort((a, b) => {
      const aLower = a.toLowerCase();
      const bLower = b.toLowerCase();
      const aImp = IMPORTANT_KEYWORDS.some(k => aLower.includes(k));
      const bImp = IMPORTANT_KEYWORDS.some(k => bLower.includes(k));
      if (aImp && !bImp) return -1;
      if (!aImp && bImp) return 1;
      return aLower.localeCompare(bLower);
    });

    return [...standardHeaders, ...sortedDynamics];
  }, [allResults]);

  useEffect(() => {
    if (showExportModal && selectedExportColumns.length === 0) {
      setSelectedExportColumns(availableColumns);
    }
  }, [showExportModal, availableColumns]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;
    setAllResults([]);
    resultsBuffer.current = [];
    setShowSummary(false);
    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];
    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, types: string[], mode: 'include' | 'exclude') => {
    const searchId = ++activeSearchId.current;
    if (flushTimeout.current) window.clearTimeout(flushTimeout.current);
    flushTimeout.current = null;
    resultsBuffer.current = [];

    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => {
      const isIncluded = types.includes(f.type);
      return mode === 'include' ? isIncluded : !isIncluded;
    });

    setSearchProgress({ scanned: 0, total: filteredFiles.length });

    if (!searchTerm) {
      setIsSearching(false);
      return;
    }

    saveSearch(searchTerm, exact, types, mode);

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;
      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;
        if (action === 'MATCH_CHUNK') {
          queueResults(payload.matches);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            flushResults();
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };
      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: { fileId: file.id, blob: file.blob, type: file.type, name: file.name, path: file.path, query: searchTerm, exactMatch: exact }
      });
    };
    workers.current.forEach(w => startWorker(w));
  }, [files, saveSearch, queueResults, flushResults]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, selectedFileTypes, filterMode);
    }, 400);
  };

  const toggleFileType = (type: string) => {
    const next = selectedFileTypes.includes(type) ? selectedFileTypes.filter(t => t !== type) : [...selectedFileTypes, type];
    setSelectedFileTypes(next);
    performSearch(query, exactMatch, next, filterMode);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';
      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();
      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  const startIdx = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
  const endIdx = Math.min(sortedResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
  const visibleItems = sortedResults.slice(startIdx, endIdx);
  const totalHeight = sortedResults.length * ROW_HEIGHT;
  const offsetY = startIdx * ROW_HEIGHT;

  const exportToCSV = () => {
    if (allResults.length === 0 || selectedExportColumns.length === 0) return;

    const csvContent = [
      selectedExportColumns.join(','),
      ...allResults.map(r => {
        return selectedExportColumns.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'FilePath') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || 'N/A';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          return `"${val.replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_export_${Date.now()}.csv`;
    link.click();
    setShowExportModal(false);
  };

  const handleRecentClick = (s: RecentSearch) => {
    setQuery(s.query);
    setExactMatch(s.exactMatch);
    setSelectedFileTypes(s.selectedFileTypes);
    setFilterMode(s.filterMode);
    performSearch(s.query, s.exactMatch, s.selectedFileTypes, s.filterMode);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-100 overflow-hidden font-sans selection:bg-blue-500/30">

      {/* 'Select *' CSV Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/85 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-gray-900 border border-gray-800 rounded-[40px] p-8 max-w-5xl w-full shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-5">
                <div className="p-4 bg-blue-600/10 rounded-3xl border border-blue-500/20 text-blue-400">
                  <Database className="w-7 h-7" />
                </div>
                <div>
                  <h2 className="text-2xl font-black uppercase tracking-tight">Full-Schema Export</h2>
                  <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest mt-1">Configure columns for 'Select *' extraction</p>
                </div>
              </div>
              <button onClick={() => setShowExportModal(false)} className="p-3 bg-gray-800 hover:bg-red-500/20 text-gray-400 hover:text-red-400 rounded-full transition-all">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="grid grid-cols-4 gap-4 mb-6">
                <div className="col-span-4 flex items-center justify-between px-2">
                    <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Header Catalog ({availableColumns.length} fields detected)</span>
                    <div className="flex gap-4">
                        <button onClick={() => setSelectedExportColumns([])} className="text-[10px] font-bold text-red-400 hover:underline">Select None</button>
                        <button onClick={() => setSelectedExportColumns(availableColumns)} className="text-[10px] font-bold text-blue-400 hover:underline">Select All (*)</button>
                    </div>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-1 space-y-2 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-2 auto-rows-min pb-10">
              {availableColumns.map(col => {
                const isSelected = selectedExportColumns.includes(col);
                const isImportant = IMPORTANT_KEYWORDS.some(imp => col.toLowerCase().includes(imp));

                return (
                  <button
                    key={col}
                    onClick={() => setSelectedExportColumns(prev => 
                      isSelected ? prev.filter(c => c !== col) : [...prev, col]
                    )}
                    className={`flex items-center justify-between px-4 py-3 rounded-xl border transition-all text-[10px] font-black uppercase tracking-tighter ${isSelected ? 'bg-blue-600/10 border-blue-500/50 text-blue-300' : 'bg-gray-800/20 border-gray-800 text-gray-600 hover:border-gray-700'}`}
                  >
                    <span className="flex items-center gap-2 truncate">
                      {isImportant && <div className="w-2 h-2 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.6)]" title="Important Transaction Field" />}
                      {col}
                    </span>
                    <div className={`w-4 h-4 rounded-md border flex items-center justify-center shrink-0 transition-all ${isSelected ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 bg-gray-950'}`}>
                      {isSelected && <Check className="w-3 h-3" />}
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="flex gap-4 pt-8 border-t border-gray-800 shrink-0">
              <button 
                onClick={exportToCSV} 
                disabled={selectedExportColumns.length === 0}
                className="flex-1 py-5 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 disabled:opacity-30 disabled:grayscale rounded-[20px] text-[11px] font-black uppercase tracking-[0.2em] transition-all shadow-2xl shadow-blue-900/40 flex items-center justify-center gap-3"
              >
                <Download className="w-5 h-5" />
                Generate CSV (Full Correlated Data)
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Main UI Header */}
      <header className="px-6 py-4 bg-gray-900 border-b border-gray-800 flex justify-between items-center shrink-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2.5 rounded-2xl shadow-lg shadow-blue-900/20">
            <Zap className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white uppercase">X-SEARCH <span className="text-blue-500">PRO</span></h1>
            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-bold uppercase tracking-[0.2em] mt-0.5">
              <ShieldCheck className="w-3 h-3 text-green-500" /> Professional Grade Indexer
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-blue-600 hover:bg-blue-500 transition-all px-7 py-3 rounded-2xl font-black text-xs shadow-xl shadow-blue-900/40">
            <FolderOpen className="w-4 h-4" />
            {files.length > 0 ? 'UPDATE SOURCE' : 'MOUNT FOLDER'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0">
        {/* Search Controls */}
        <div className="px-6 py-8 bg-gray-900/30 border-b border-gray-800/50 shrink-0">
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="flex gap-6 items-start">
