              <p className="text-[10px] font-black mt-4 uppercase tracking-[0.3em] text-gray-700">Input extraction sequence to begin indexing</p>
            </div>
          )}
        </div>
      </main>

      {/* Footer Info */}
      <footer className="px-6 py-4 bg-gray-900 border-t border-gray-800 flex justify-between items-center text-[9px] font-black text-gray-600 uppercase tracking-[0.3em] shrink-0 z-50">
