  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'relevance', direction: 'desc' });
  const [recentSearches, setRecentSearches] = useState<RecentSearch[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showSummary, setShowSummary] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0, errors: [] as string[] });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const resultsBuffer = useRef<SearchResult[]>([]);
  const flushTimeout = useRef<number | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('xsearch_pro_v4_history');
    if (saved) setRecentSearches(JSON.parse(saved));
  }, []);

  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) {
        setContainerHeight(scrollContainerRef.current.clientHeight);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const flushResults = useCallback(() => {
    if (resultsBuffer.current.length > 0) {
      const newItems = [...resultsBuffer.current];
      resultsBuffer.current = [];
      setAllResults(prev => [...prev, ...newItems]);
    }
    flushTimeout.current = null;
  }, []);

  const queueResults = useCallback((items: SearchResult[]) => {
    resultsBuffer.current.push(...items);
    if (!flushTimeout.current) {
      flushTimeout.current = window.setTimeout(flushResults, BATCH_FLUSH_INTERVAL);
    }
  }, [flushResults]);

  const initWorkerPool = useCallback(() => {
    workers.current.forEach(w => w.terminate());
    workers.current = [];
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      workers.current.push(new Worker(workerUrl));
    }
  }, []);

  useEffect(() => {
    initWorkerPool();
    return () => workers.current.forEach(w => w.terminate());
  }, [initWorkerPool]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;

    setAllResults([]);
    resultsBuffer.current = [];
    setShowSummary(false);

    const fileList: FileMetadata[] = [];
    const supported = ['xlsx', 'xls', 'csv', 'txt'];
    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (supported.includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, fuzzy: boolean, types: string[], mode: 'include' | 'exclude') => {
    const searchId = ++activeSearchId.current;
    if (flushTimeout.current) window.clearTimeout(flushTimeout.current);
    flushTimeout.current = null;
    resultsBuffer.current = [];

    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => {
      const isIncluded = types.includes(f.type);
      return mode === 'include' ? isIncluded : !isIncluded;
    });

    setSearchProgress({ scanned: 0, total: filteredFiles.length, errors: [] });

    if (searchTerm) {
      const newSearch: RecentSearch = { query: searchTerm, timestamp: Date.now(), exactMatch: exact, selectedFileTypes: types, filterMode: mode };
      setRecentSearches(prev => [newSearch, ...prev.filter(s => s.query !== searchTerm)].slice(0, 10));
      localStorage.setItem('xsearch_pro_v4_history', JSON.stringify([newSearch, ...recentSearches.filter(s => s.query !== searchTerm)].slice(0, 10)));
    }

    let pendingFiles = [...filteredFiles];
    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= pendingFiles.length || searchId !== activeSearchId.current) return;
      const file = pendingFiles[currentIdx++];
      worker.onmessage = (e) => {
        if (searchId !== activeSearchId.current) return;
        const { action, payload } = e.data;
        if (action === 'MATCH_CHUNK') {
          queueResults(payload.matches);
        } else if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          if (action === 'FILE_ERROR') {
            setSearchProgress(p => ({ ...p, errors: [...p.errors, `${file.name}: ${payload.error}`] }));
          }
          completedCount++;
          setSearchProgress(prev => ({ ...prev, scanned: completedCount }));
          if (completedCount === filteredFiles.length) {
            flushResults();
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
      };
      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: { fileId: file.id, blob: file.blob, type: file.type, name: file.name, path: file.path, query: searchTerm, exactMatch: exact, fuzzy }
      });
    };
    workers.current.forEach(w => startWorker(w));
  }, [files, queueResults, flushResults, recentSearches]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => {
      performSearch(val, exactMatch, fuzzySearch, selectedFileTypes, filterMode);
    }, 400);
  };

  const handleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const sortedResults = useMemo(() => {
    if (sortConfig.key === 'relevance') return allResults;
    const sorted = [...allResults];
    sorted.sort((a, b) => {
      const key = sortConfig.key;
      let valA: any = (a as any)[key] ?? a.rowData[key] ?? '';
      let valB: any = (b as any)[key] ?? b.rowData[key] ?? '';
      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();
      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [allResults, sortConfig]);

  // VIRTUAL SCROLLING LOGIC
  const startIdx = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
  const endIdx = Math.min(sortedResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
  const visibleItems = sortedResults.slice(startIdx, endIdx);
  const totalHeight = sortedResults.length * ROW_HEIGHT;
  const offsetY = startIdx * ROW_HEIGHT;

  const exportFullCSV = () => {
    if (allResults.length === 0) return;

    // Find all unique keys across all results for "Select *" behavior
    const allKeys = new Set<string>(['FileName', 'FilePath', 'Sheet', 'Row']);
    allResults.forEach(r => Object.keys(r.rowData).forEach(k => allKeys.add(k)));
    const headerArray = Array.from(allKeys);

    const csvContent = [
      headerArray.join(','),
      ...allResults.map(r => {
        return headerArray.map(h => {
          let val = '';
          if (h === 'FileName') val = r.fileName;
          else if (h === 'FilePath') val = r.filePath;
          else if (h === 'Sheet') val = r.sheetName || '';
          else if (h === 'Row') val = String(r.rowNumber);
          else val = String(r.rowData[h] || '');
          // Escape CSV
          return `"${String(val).replace(/"/g, '""')}"`;
        }).join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `xsearch_export_${Date.now()}.csv`;
    link.click();
    setShowExportModal(false);
  };

  return (
    <div className="flex flex-col h-screen bg-[#0a0a0c] text-gray-200 overflow-hidden font-sans">

      {/* Header */}
      <header className="px-6 py-4 bg-[#111114] border-b border-gray-800 flex justify-between items-center shrink-0 z-50 shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-600 p-2.5 rounded-xl shadow-lg shadow-blue-900/20">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight text-white uppercase">X-SEARCH <span className="text-blue-500">PRO</span></h1>
            <div className="flex items-center gap-2 text-[9px] text-gray-500 font-bold uppercase tracking-[0.2em]">
              <ShieldCheck className="w-3 h-3 text-green-500" /> Secure Local Transaction Intelligence
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <label className="group flex items-center gap-3 cursor-pointer bg-[#1a1a1e] hover:bg-gray-800 transition-all px-6 py-2.5 rounded-xl font-bold text-xs border border-gray-800 active:scale-95">
            <FolderOpen className="w-4 h-4 text-gray-400 group-hover:text-white" />
            {files.length > 0 ? `${files.length} Files Indexed` : 'Select Directory'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>

          {allResults.length > 0 && (
            <button 
              onClick={() => setShowExportModal(true)}
              className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-xs font-black uppercase transition-all shadow-lg shadow-blue-900/20 active:scale-95"
            >
              <Download className="w-4 h-4" />
              Export
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0 bg-[#0d0d0f]">
        {/* Search & Filters */}
        <div className="px-6 py-6 bg-[#111114] border-b border-gray-800 shrink-0">
          <div className="max-w-6xl mx-auto space-y-4">
            <div className="flex gap-4">
              <div className="relative flex-1">
                <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
                <input 
                  type="text"
                  placeholder={files.length > 0 ? "Deep search across all partitions..." : "Select source folder to begin indexing..."}
                  className="w-full bg-[#1a1a1e] border border-gray-800 rounded-2xl py-4 pl-14 pr-6 text-lg text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500/50 transition-all"
                  disabled={files.length === 0}
                  value={query}
                  onChange={(e) => onQueryChange(e.target.value)}
                  autoFocus
                />
                {isSearching && (
                  <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">{Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%</span>
                    <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-6">
                <button 
                  onClick={() => { setFuzzySearch(!fuzzySearch); performSearch(query, exactMatch, !fuzzySearch, selectedFileTypes, filterMode); }}
                  className={`flex items-center gap-3 text-[10px] font-black tracking-widest transition-all ${fuzzySearch ? 'text-blue-400' : 'text-gray-600'}`}
                >
                  <Sparkles className={`w-4 h-4 ${fuzzySearch ? 'animate-pulse' : ''}`} />
                  FUZZY LOGIC
                </button>
                <div className="h-4 w-px bg-gray-800" />
                <button 
                  onClick={() => { setExactMatch(!exactMatch); performSearch(query, !exactMatch, fuzzySearch, selectedFileTypes, filterMode); }}
                  className={`flex items-center gap-3 text-[10px] font-black tracking-widest transition-all ${exactMatch ? 'text-blue-400' : 'text-gray-600'}`}
                >
                  <Database className="w-4 h-4" />
                  STRICT MATCH
                </button>
                <div className="h-4 w-px bg-gray-800" />
                <div className="flex items-center gap-2">
                  {['xlsx', 'csv', 'txt'].map(type => (
                    <button
                      key={type}
                      onClick={() => {
                        const next = selectedFileTypes.includes(type) ? selectedFileTypes.filter(t => t !== type) : [...selectedFileTypes, type];
                        setSelectedFileTypes(next);
                        performSearch(query, exactMatch, fuzzySearch, next, filterMode);
                      }}
                      className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all border ${selectedFileTypes.includes(type) ? 'bg-blue-600/10 border-blue-500/40 text-blue-400' : 'border-gray-800 text-gray-600'}`}
                    >
                      {type}
                    </button>
                  ))}
                </div>
              </div>

              {allResults.length > 0 && (
                <div className="flex items-center gap-4 text-[10px] font-black text-gray-500 uppercase tracking-widest">
                  <span>Results: {allResults.length.toLocaleString()}</span>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Results Body */}
        <div 
          ref={scrollContainerRef}
          onScroll={handleScroll}
          className="flex-1 overflow-auto bg-[#0a0a0c] relative custom-scrollbar"
        >
          {files.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-10 grayscale pointer-events-none select-none">
              <Database className="w-48 h-48 mb-8" />
              <h3 className="text-4xl font-black uppercase tracking-[0.5em]">Indexer Idle</h3>
              <p className="text-sm font-bold mt-4 uppercase tracking-[0.2em]">Mount a directory to begin transaction extraction</p>
            </div>
          ) : sortedResults.length > 0 ? (
            <div className="max-w-6xl mx-auto py-8" style={{ height: totalHeight }}>
              <div style={{ transform: `translateY(${offsetY}px)` }}>
                {visibleItems.map((res) => (
                  <div 
                    key={res.id} 
                    className={`mb-2 mx-4 group bg-[#111114]/60 border transition-all duration-300 overflow-hidden ${expandedId === res.id ? 'border-blue-500/50 rounded-2xl bg-[#15151a] shadow-2xl ring-1 ring-blue-500/20' : 'border-gray-800/40 rounded-xl hover:border-gray-700/60 hover:bg-[#16161a]'}`}
                    style={{ height: expandedId === res.id ? 'auto' : ROW_HEIGHT - 8 }}
                  >
                    <div 
                      className="p-4 flex items-center justify-between cursor-pointer"
                      onClick={() => setExpandedId(expandedId === res.id ? null : res.id)}
                    >
                      <div className="flex items-center gap-5 min-w-0">
                        <div className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all ${expandedId === res.id ? 'bg-blue-600 text-white' : 'bg-[#1a1a1e] text-gray-600 group-hover:text-blue-400'}`}>
                          {res.fileName.endsWith('.csv') ? <FileCode className="w-5 h-5" /> : <FileSpreadsheet className="w-5 h-5" />}
                        </div>
                        <div className="min-w-0">
                          <div className="text-xs font-black text-gray-200 uppercase tracking-tight truncate flex items-center gap-3">
                            {res.fileName}
                            {res.sheetName && <span className="text-[8px] px-1.5 py-0.5 bg-indigo-500/10 text-indigo-400 rounded-md border border-indigo-500/20">{res.sheetName}</span>}
                          </div>
                          <div className="text-[10px] font-bold text-gray-500 mt-1 uppercase tracking-widest flex items-center gap-3">
                            <span className="shrink-0 text-gray-600">ROW {res.rowNumber}</span>
                            <span className="truncate max-w-lg text-gray-400 italic font-medium opacity-80">{res.searchString}</span>
                          </div>
                        </div>
                      </div>
                      <ChevronDown className={`w-4 h-4 text-gray-600 transition-transform duration-300 ${expandedId === res.id ? 'rotate-180 text-blue-500' : ''}`} />
                    </div>

                    {expandedId === res.id && (
                      <div className="px-6 pb-6 pt-2 animate-in slide-in-from-top-2 duration-300">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 mt-2">
                          {Object.entries(res.rowData).map(([key, value]) => {
                            const isPrio = PRIORITY_KEYWORDS.some(k => key.toLowerCase().includes(k));
                            return (
                              <div key={key} className="p-3 bg-[#1a1a1e] rounded-xl border border-gray-800/50 hover:border-gray-700 transition-colors">
                                <div className="text-[8px] font-black text-gray-500 uppercase tracking-widest mb-1 flex items-center gap-2">
                                  {isPrio && <div className="w-1.5 h-1.5 rounded-full bg-blue-500" />}
                                  {key}
                                </div>
                                <div className="text-[11px] font-medium text-gray-300 break-words">{String(value) || <span className="opacity-20 italic">Null</span>}</div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ) : query ? (
            <div className="h-full flex flex-col items-center justify-center opacity-40">
              <AlertTriangle className="w-16 h-16 mb-6 text-amber-600" />
              <h4 className="text-2xl font-black uppercase tracking-widest text-gray-600">Zero matches found</h4>
              <p className="text-xs font-bold mt-2 uppercase tracking-widest text-gray-700">Refine signature or adjust strictness</p>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-10">
              <Zap className="w-24 h-24 mb-6 text-blue-600" />
              <h4 className="text-3xl font-black uppercase tracking-[0.4em] text-gray-700">Memory Standby</h4>
            </div>
          )}
        </div>
      </main>

      {/* Footer */}
      <footer className="px-6 py-3 bg-[#111114] border-t border-gray-800 flex justify-between items-center text-[9px] font-black text-gray-600 uppercase tracking-widest shrink-0">
        <div className="flex gap-8 items-center">
          <span className="flex items-center gap-2"><Clock className="w-3 h-3 text-blue-500/40" /> THREADS: {MAX_WORKERS}</span>
          <span className="flex items-center gap-2"><Hash className="w-3 h-3 text-indigo-500/40" /> PARTITIONS: {files.length}</span>
          {searchProgress.errors.length > 0 && (
            <span className="text-red-500 flex items-center gap-2 animate-pulse">
              <FileWarning className="w-3 h-3" /> FAILED: {searchProgress.errors.length}
            </span>
          )}
        </div>
        <div className="flex items-center gap-6">
          <span className="text-green-500/40 flex items-center gap-2"><ShieldCheck className="w-3 h-3" /> 100% CLIENT-SIDE</span>
          <span className="text-gray-800">X-SEARCH PRO V4.0.0</span>
        </div>
      </footer>

      {/* Export Confirmation Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-6 animate-in fade-in duration-300">
          <div className="bg-[#111114] border border-gray-800 rounded-3xl p-8 max-w-sm w-full shadow-2xl ring-1 ring-white/10">
            <h2 className="text-xl font-black uppercase tracking-tight mb-4 flex items-center gap-4">
              <Download className="w-6 h-6 text-blue-500" /> Confirm Export
            </h2>
            <p className="text-gray-400 text-xs font-medium mb-8 leading-relaxed">
              Initiating full dataset extraction. All columns will be included in a 'Select *' structure. This process is 100% local.
            </p>
            <div className="flex gap-4">
              <button onClick={() => setShowExportModal(false)} className="flex-1 py-3 bg-[#1a1a1e] hover:bg-gray-800 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">Cancel</button>
              <button onClick={exportFullCSV} className="flex-1 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl text-[10px] font-black uppercase tracking-widest text-white transition-all shadow-lg shadow-blue-900/40">Download CSV</button>
            </div>
          </div>
        </div>
      )}

      {/* Summary Modal */}
      {showSummary && !isSearching && allResults.length > 0 && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 p-6 animate-in fade-in zoom-in-95 duration-500 pointer-events-none">
          <div className="bg-[#111114] border border-gray-800 rounded-[32px] p-8 max-w-xs w-full text-center shadow-[0_0_50px_rgba(0,0,0,0.5)] pointer-events-auto">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-blue-900/30">
              <CheckCircle2 className="w-8 h-8 text-white" />
            </div>
            <h3 className="text-lg font-black uppercase tracking-tight mb-2">Extraction Done</h3>
            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-6">
              Indexed {allResults.length.toLocaleString()} matches in {((Date.now() - startTime.current) / 1000).toFixed(1)}s
            </p>
            <button onClick={() => setShowSummary(false)} className="w-full py-4 bg-[#1a1a1e] hover:bg-gray-800 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all">Explore Data</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface SearchResult {
  id: string;
  fileId: string;
  fileName: string;
  filePath: string;
  sheetName?: string;
  rowNumber: number;
  searchString: string; // Limited preview for the list
}

export interface RecentSearch {
  query: string;
  timestamp: number;
  exactMatch: boolean;
  selectedFileTypes: string[];
  filterMode: 'include' | 'exclude';
}

export interface SortConfig {
  key: string;
  direction: 'asc' | 'desc';
}

/**
 * X-Search Pro Background Worker (High-Throughput Edition)
 * Optimized for O(1) memory growth and deferred data fetching.
 */
export const workerScript = `
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  self.importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');

  const CHUNK_SIZE = 500; 
  const PRIORITY_KEYS = ['date', 'amount', 'nature', 'debit', 'credit', 'balance', 'name', 'particulars', 'ref', 'account'];

  // Cache for the current session to avoid re-parsing during detail fetching or export
  let fileCache = new Map(); // id -> { blob, type, name }
  let matchCache = new Map(); // fileId -> Set of matched row numbers

  self.onmessage = async function(e) {
    const { action, payload } = e.data;

    if (action === 'PROCESS_FILE') {
      await processFile(payload);
    } else if (action === 'FETCH_ROW_DETAIL') {
      await fetchRowDetail(payload);
    } else if (action === 'GENERATE_EXPORT') {
      await generateExport(payload);
    }
  };

  function matchesFuzzy(queryTerms, searchableString) {
    for (const term of queryTerms) {
      if (!searchableString.includes(term)) return false;
    }
    return true;
  }

  async function fetchRowDetail({ fileId, rowNumber, sheetName }) {
    const file = fileCache.get(fileId);
    if (!file) return;

    try {
      let rowData = null;
      if (file.type === 'xlsx' || file.type === 'xls') {
        const buffer = await file.blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'array', dense: true });
        const sheet = workbook.Sheets[sheetName || workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { defval: "" });
        rowData = jsonData[rowNumber - 2]; // Adjust for 1-based row numbers and header
      } else if (file.type === 'csv') {
        const text = await file.blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });
        rowData = parsed.data[rowNumber - 2];
      } else {
        const text = await file.blob.text();
        const lines = text.split(/\\r?\\n/);
        rowData = { content: lines[rowNumber - 2] };
      }
      self.postMessage({ action: 'ROW_DETAIL_RESULT', payload: { fileId, rowNumber, rowData } });
    } catch (err) {
      console.error("Detail fetch error", err);
    }
  }

  async function processFile({ fileId, blob, type, name, path, query, exactMatch, fuzzy }) {
    fileCache.set(fileId, { blob, type, name });
    const fileMatchedRows = new Set();

    try {
      const lowerQuery = query.toLowerCase();
      const queryTerms = lowerQuery.split(/\\s+/).filter(t => t.length > 0);
      const isQueryEmpty = queryTerms.length === 0;
      let matches = [];
      let totalRows = 0;

      const onRowProcessed = (row, sName = null) => {
        totalRows++;
        let searchable = [];
        let preview = [];

        for (const key in row) {
          const val = String(row[key]);
          searchable.push(val.toLowerCase());
          const lKey = key.toLowerCase();
          if (PRIORITY_KEYS.some(pk => lKey.includes(pk)) && preview.length < 4) {
            preview.push(\`\${key}: \${val}\`);
          }
        }

        const fullStr = searchable.join(' ');
        let isMatch = isQueryEmpty;
        if (!isMatch) {
          if (exactMatch) isMatch = searchable.some(v => v === lowerQuery);
          else if (fuzzy) isMatch = matchesFuzzy(queryTerms, fullStr);
          else isMatch = fullStr.includes(lowerQuery);
        }

        if (isMatch) {
          fileMatchedRows.add(totalRows);
          matches.push({
            id: \`\${fileId}-\${totalRows}\`,
            fileId,
            fileName: name,
            filePath: path,
            sheetName: sName,
            rowNumber: totalRows + 1,
            searchString: preview.length ? preview.join(' • ') : searchable.slice(0, 3).join(' • ')
          });

          if (matches.length >= CHUNK_SIZE) {
            self.postMessage({ action: 'MATCH_CHUNK', payload: { fileId, matches } });
            matches = [];
          }
        }
      };

      if (type === 'xlsx' || type === 'xls') {
        const buffer = await blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'array', dense: true, cellDates: true });
        for (const sName of workbook.SheetNames) {
          const sheet = workbook.Sheets[sName];
          const data = XLSX.utils.sheet_to_json(sheet, { defval: "" });
          for (const row of data) onRowProcessed(row, sName);
        }
      } else if (type === 'csv') {
        const text = await blob.text();
        Papa.parse(text, { 
          header: true, 
          skipEmptyLines: true, 
          step: (results) => onRowProcessed(results.data) 
        });
      } else {
        const text = await blob.text();
        text.split(/\\r?\\n/).forEach(line => {
          if (line.trim()) onRowProcessed({ content: line.trim() });
        });
      }

      if (matches.length > 0) self.postMessage({ action: 'MATCH_CHUNK', payload: { fileId, matches } });
      matchCache.set(fileId, fileMatchedRows);
      self.postMessage({ action: 'FILE_COMPLETE', payload: { fileId, totalRows } });
    } catch (err) {
      self.postMessage({ action: 'FILE_ERROR', payload: { fileId, error: err.message } });
    }
  }

  async function generateExport({ queries }) {
    // Generate CSV for all matches in the current session
    const allHeaders = new Set(['FileName', 'RowNumber', 'Sheet']);
    const allRows = [];

    for (const [fileId, matchedRowIndices] of matchCache.entries()) {
      const file = fileCache.get(fileId);
      if (!file || matchedRowIndices.size === 0) continue;

      let fileRows = [];
      if (file.type === 'xlsx' || file.type === 'xls') {
        const buffer = await file.blob.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'array', dense: true });
        workbook.SheetNames.forEach(sName => {
          const sheet = workbook.Sheets[sName];
          const data = XLSX.utils.sheet_to_json(sheet, { defval: "" });
          data.forEach((r, idx) => {
            if (matchedRowIndices.has(idx + 1)) {
              const exportRow = { FileName: file.name, RowNumber: idx + 2, Sheet: sName, ...r };
              Object.keys(exportRow).forEach(k => allHeaders.add(k));
              fileRows.push(exportRow);
            }
          });
        });
      } else if (file.type === 'csv') {
        const text = await file.blob.text();
        const parsed = Papa.parse(text, { header: true, skipEmptyLines: true });
        parsed.data.forEach((r, idx) => {
          if (matchedRowIndices.has(idx + 1)) {
            const exportRow = { FileName: file.name, RowNumber: idx + 2, Sheet: 'N/A', ...r };
            Object.keys(exportRow).forEach(k => allHeaders.add(k));
            fileRows.push(exportRow);
          }
        });
      }
      allRows.push(...fileRows);
    }

    const headers = Array.from(allHeaders);
    const csvContent = [
      headers.join(','),
      ...allRows.map(r => headers.map(h => \`"\${String(r[h] || '').replace(/"/g, '""')}"\`).join(','))
    ].join('\\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    self.postMessage({ action: 'EXPORT_READY', payload: { blob } });
  }
`;

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  FolderOpen, 
  ShieldCheck, 
  Loader2, 
  Clock, 
  Database,
  Download,
  Zap,
  AlertTriangle,
  ChevronDown,
  CheckCircle2,
  FileSpreadsheet,
  FileCode,
  Sparkles,
  FileWarning
} from 'lucide-react';
import { SearchResult, RecentSearch, SortConfig } from './types';
import { workerScript } from './worker';

const MAX_WORKERS = Math.min(navigator.hardwareConcurrency || 4, 4);
const ROW_HEIGHT = 80; 
const VIRTUAL_BUFFER = 12;
const BATCH_FLUSH_INTERVAL = 150; 

interface FileMetadata {
  id: string;
  name: string;
  path: string;
  type: string;
  blob: File;
  size: number;
}

const App: React.FC = () => {
  const [query, setQuery] = useState('');
  const [allResults, setAllResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [exactMatch, setExactMatch] = useState(false);
  const [fuzzySearch, setFuzzySearch] = useState(true);
  const [selectedFileTypes, setSelectedFileTypes] = useState<string[]>(['xlsx', 'xls', 'csv', 'txt']);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [expandedData, setExpandedData] = useState<Record<string, any> | null>(null);
  const [showSummary, setShowSummary] = useState(false);

  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [searchProgress, setSearchProgress] = useState({ scanned: 0, total: 0, errors: [] as string[] });

  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  const workers = useRef<Worker[]>([]);
  const searchTimeout = useRef<number | null>(null);
  const activeSearchId = useRef<number>(0);
  const startTime = useRef<number>(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const resultsBuffer = useRef<SearchResult[]>([]);
  const flushTimeout = useRef<number | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (scrollContainerRef.current) setContainerHeight(scrollContainerRef.current.clientHeight);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const flushResults = useCallback(() => {
    if (resultsBuffer.current.length > 0) {
      const newItems = [...resultsBuffer.current];
      resultsBuffer.current = [];
      setAllResults(prev => [...prev, ...newItems]);
    }
    flushTimeout.current = null;
  }, []);

  const queueResults = useCallback((items: SearchResult[]) => {
    resultsBuffer.current.push(...items);
    if (!flushTimeout.current) flushTimeout.current = window.setTimeout(flushResults, BATCH_FLUSH_INTERVAL);
  }, [flushResults]);

  useEffect(() => {
    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const url = URL.createObjectURL(blob);
    for (let i = 0; i < MAX_WORKERS; i++) {
      const w = new Worker(url);
      w.onmessage = (e) => {
        const { action, payload } = e.data;
        if (action === 'MATCH_CHUNK') queueResults(payload.matches);
        if (action === 'ROW_DETAIL_RESULT') setExpandedData(payload.rowData);
        if (action === 'EXPORT_READY') {
          const link = document.createElement("a");
          link.href = URL.createObjectURL(payload.blob);
          link.download = `xsearch_export_${Date.now()}.csv`;
          link.click();
          setIsExporting(false);
        }
      };
      workers.current.push(w);
    }
    return () => workers.current.forEach(w => w.terminate());
  }, [queueResults]);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawFiles = e.target.files;
    if (!rawFiles) return;
    const fileList: FileMetadata[] = [];
    for (let i = 0; i < rawFiles.length; i++) {
      const file = rawFiles[i];
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      if (['xlsx', 'xls', 'csv', 'txt'].includes(extension)) {
        fileList.push({
          id: `${file.name}-${file.size}-${file.lastModified}`,
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          type: extension,
          blob: file,
          size: file.size
        });
      }
    }
    setFiles(fileList);
  };

  const performSearch = useCallback(async (searchTerm: string, exact: boolean, fuzzy: boolean, types: string[]) => {
    const searchId = ++activeSearchId.current;
    if (flushTimeout.current) window.clearTimeout(flushTimeout.current);
    flushTimeout.current = null;
    resultsBuffer.current = [];
    setIsSearching(true);
    setAllResults([]);
    setShowSummary(false);
    startTime.current = Date.now();

    const filteredFiles = files.filter(f => types.includes(f.type));
    setSearchProgress({ scanned: 0, total: filteredFiles.length, errors: [] });

    let currentIdx = 0;
    let completedCount = 0;

    const startWorker = (worker: Worker) => {
      if (currentIdx >= filteredFiles.length || searchId !== activeSearchId.current) return;
      const file = filteredFiles[currentIdx++];
      worker.postMessage({
        action: 'PROCESS_FILE',
        payload: { fileId: file.id, blob: file.blob, type: file.type, name: file.name, path: file.path, query: searchTerm, exactMatch: exact, fuzzy }
      });

      const oldMsg = worker.onmessage;
      worker.onmessage = (e) => {
        const { action, payload } = e.data;
        if (action === 'FILE_COMPLETE' || action === 'FILE_ERROR') {
          completedCount++;
          setSearchProgress(p => ({ ...p, scanned: completedCount, errors: action === 'FILE_ERROR' ? [...p.errors, payload.error] : p.errors }));
          if (completedCount === filteredFiles.length) {
            flushResults();
            setIsSearching(false);
            setShowSummary(true);
          } else {
            startWorker(worker);
          }
        }
        if (oldMsg) oldMsg(e);
      };
    };
    workers.current.forEach(w => startWorker(w));
  }, [files, flushResults]);

  const onQueryChange = (val: string) => {
    setQuery(val);
    if (searchTimeout.current) window.clearTimeout(searchTimeout.current);
    searchTimeout.current = window.setTimeout(() => performSearch(val, exactMatch, fuzzySearch, selectedFileTypes), 400);
  };

  const handleExpand = (res: SearchResult) => {
    if (expandedId === res.id) {
      setExpandedId(null);
      setExpandedData(null);
    } else {
      setExpandedId(res.id);
      setExpandedData(null);
      workers.current[0].postMessage({
        action: 'FETCH_ROW_DETAIL',
        payload: { fileId: res.fileId, rowNumber: res.rowNumber, sheetName: res.sheetName }
      });
    }
  };

  const startExport = () => {
    setIsExporting(true);
    workers.current[0].postMessage({ action: 'GENERATE_EXPORT', payload: {} });
  };

  const visibleItems = useMemo(() => {
    const start = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - VIRTUAL_BUFFER);
    const end = Math.min(allResults.length, Math.ceil((scrollTop + containerHeight) / ROW_HEIGHT) + VIRTUAL_BUFFER);
    return { items: allResults.slice(start, end), startIdx: start };
  }, [allResults, scrollTop, containerHeight]);

  return (
    <div className="flex flex-col h-screen bg-[#0a0a0c] text-gray-200 overflow-hidden font-sans">
      <header className="px-6 py-4 bg-[#111114] border-b border-gray-800 flex justify-between items-center z-50">
        <div className="flex items-center gap-4">
          <div className="bg-blue-600 p-2 rounded-xl">
            <Zap className="w-5 h-5 text-white" />
          </div>
          <h1 className="text-xl font-black uppercase tracking-tight">X-SEARCH <span className="text-blue-500">PRO</span></h1>
        </div>

        <div className="flex items-center gap-4">
          <label className="flex items-center gap-3 cursor-pointer bg-[#1a1a1e] px-5 py-2 rounded-xl text-xs font-bold border border-gray-800">
            <FolderOpen className="w-4 h-4 text-gray-400" />
            {files.length || 'Select Directory'}
            <input type="file" className="hidden" webkitdirectory="" directory="" multiple onChange={handleFolderSelect} />
          </label>

          {allResults.length > 0 && (
            <button 
              onClick={startExport}
              disabled={isExporting}
              className="flex items-center gap-2 px-5 py-2 bg-blue-600 text-white rounded-xl text-xs font-bold disabled:opacity-50"
            >
              {isExporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
              Export CSV
            </button>
          )}
        </div>
      </header>

      <main className="flex-1 flex flex-col bg-[#0d0d0f]">
        <div className="px-6 py-6 bg-[#111114] border-b border-gray-800">
          <div className="max-w-6xl mx-auto space-y-4">
            <div className="relative">
              <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 ${isSearching ? 'text-blue-500' : 'text-gray-500'}`} />
              <input 
                type="text"
                placeholder="Deep search local records..."
                className="w-full bg-[#1a1a1e] border border-gray-800 rounded-2xl py-4 pl-14 pr-6 text-lg"
                disabled={files.length === 0}
                value={query}
                onChange={(e) => onQueryChange(e.target.value)}
              />
              {isSearching && (
                <div className="absolute right-5 top-1/2 -translate-y-1/2 flex items-center gap-3">
                  <span className="text-[10px] text-blue-500 font-bold uppercase">{Math.round((searchProgress.scanned / (searchProgress.total || 1)) * 100)}%</span>
                  <Loader2 className="w-4 h-4 animate-spin text-blue-500" />
                </div>
              )}
            </div>

            <div className="flex items-center gap-6">
              <button onClick={() => setFuzzySearch(!fuzzySearch)} className={`flex items-center gap-2 text-[10px] font-black tracking-widest ${fuzzySearch ? 'text-blue-400' : 'text-gray-600'}`}>
                <Sparkles className="w-4 h-4" /> FUZZY ENGINE
              </button>
              <div className="h-3 w-px bg-gray-800" />
              <button onClick={() => setExactMatch(!exactMatch)} className={`flex items-center gap-2 text-[10px] font-black tracking-widest ${exactMatch ? 'text-blue-400' : 'text-gray-600'}`}>
                <Database className="w-4 h-4" /> EXACT MATCH
              </button>
            </div>
          </div>
        </div>

        <div ref={scrollContainerRef} onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)} className="flex-1 overflow-auto bg-[#0a0a0c]">
          {files.length > 0 ? (
            <div className="max-w-6xl mx-auto py-6" style={{ height: allResults.length * ROW_HEIGHT }}>
              <div style={{ transform: `translateY(${visibleItems.startIdx * ROW_HEIGHT}px)` }}>
                {visibleItems.items.map((res) => (
                  <div 
                    key={res.id} 
                    className={`mb-2 mx-4 bg-[#111114] border rounded-xl overflow-hidden transition-all ${expandedId === res.id ? 'border-blue-500 ring-1 ring-blue-500/20' : 'border-gray-800'}`}
                  >
                    <div className="p-4 flex items-center justify-between cursor-pointer" onClick={() => handleExpand(res)}>
                      <div className="flex items-center gap-4 min-w-0">
                        <div className="w-10 h-10 bg-[#1a1a1e] rounded-lg flex items-center justify-center">
                          {res.fileName.endsWith('.csv') ? <FileCode className="w-5 h-5 text-gray-400" /> : <FileSpreadsheet className="w-5 h-5 text-gray-400" />}
                        </div>
                        <div className="min-w-0">
                          <div className="text-xs font-bold truncate">{res.fileName} <span className="text-[10px] text-gray-600 ml-2">ROW {res.rowNumber}</span></div>
                          <div className="text-[10px] text-gray-500 truncate italic mt-0.5">{res.searchString}</div>
                        </div>
                      </div>
                      <ChevronDown className={`w-4 h-4 transition-transform ${expandedId === res.id ? 'rotate-180 text-blue-500' : 'text-gray-600'}`} />
                    </div>
                    {expandedId === res.id && (
                      <div className="px-6 pb-6 pt-2 border-t border-gray-800/50 bg-[#0d0d0f]">
                        {expandedData ? (
                          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3 mt-2">
                            {Object.entries(expandedData).map(([key, value]) => (
                              <div key={key} className="p-2 bg-[#1a1a1e] rounded-lg border border-gray-800">
                                <div className="text-[8px] font-bold text-gray-500 uppercase mb-1">{key}</div>
                                <div className="text-[10px] text-gray-200">{String(value) || '—'}</div>
                              </div>
                            ))}
                          </div>
                        ) : (
                          <div className="flex items-center gap-3 py-4 text-xs text-gray-500 italic">
                            <Loader2 className="w-4 h-4 animate-spin" /> Fetching row details from source...
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center opacity-20">
              <Database className="w-24 h-24 mb-4" />
              <div className="text-xl font-black uppercase">Mount Directory</div>
            </div>
          )}
        </div>
      </main>

      <footer className="px-6 py-3 bg-[#111114] border-t border-gray-800 flex justify-between items-center text-[9px] font-black text-gray-600 uppercase">
        <div className="flex gap-8">
          <span>CORES: {MAX_WORKERS}</span>
          <span>FILES: {files.length}</span>
          {searchProgress.errors.length > 0 && <span className="text-red-500 animate-pulse">ERRORS: {searchProgress.errors.length}</span>}
        </div>
        <span>X-SEARCH PRO V4.1.0-DEFERRED</span>
      </footer>

      {showSummary && allResults.length > 0 && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 pointer-events-none">
          <div className="bg-[#111114] border border-gray-800 rounded-3xl p-8 text-center shadow-2xl pointer-events-auto">
            <CheckCircle2 className="w-12 h-12 text-blue-500 mx-auto mb-4" />
            <div className="text-lg font-bold mb-1">{allResults.length.toLocaleString()} Matches</div>
            <div className="text-[10px] text-gray-500 mb-6 uppercase">Time: {((Date.now() - startTime.current) / 1000).toFixed(2)}s</div>
            <button onClick={() => setShowSummary(false)} className="px-8 py-3 bg-blue-600 text-white rounded-xl text-[10px] font-bold uppercase">Explore</button>
          </div>
        </div>
      )}
    </div>
  );
};

